// Footer display version, read directly from package.json so it never drifts
// from the actual build. package.json 3.0.0 -> displays "v3.0". Bump the major
// in package.json by hand at real releases; minor/patch track iterations.
const DISPLAY_VERSION = (() => {
  const parts = String(PKG_VERSION || '0.0.0').split('.');
  const major = parts[0] || '0';
  const minor = parts[1] || '0';
  return `v${major}.${minor}`;
})();

