/* Percentile-banded scores within asset type — see notes accompanying mockup */
const SCORE_RANGES = {
  Process:  { critical: 95, high: 75, moderate: 50 },  // top quartile / etc within Process range 33-109
  System:   { critical: 175, high: 100, moderate: 50 },// within System range 6-210
  Facility: { critical: 100, high: 70, moderate: 50 }, // within Facility range 32-203
};

const band = (score, type = 'Process') => {
  const r = SCORE_RANGES[type] || SCORE_RANGES.Process;
  if (score >= r.critical) return { label: 'CRITICAL', color: T.critical, soft: T.criticalSoft };
  if (score >= r.high)     return { label: 'HIGH',     color: T.high,     soft: T.highSoft };
  if (score >= r.moderate) return { label: 'MODERATE', color: T.moderate, soft: T.moderateSoft };
  return                        { label: 'LOW',      color: T.low,      soft: T.lowSoft };
};

