/* ============================================================================
   CASCADE COMPUTATION — deduplicated downstream traversal
   ============================================================================ */

function computeCascade(seedIds) {
  // Returns: { direct: Set, totalCascade: Set, byDepth: Map<id, depth> }
  // direct = unique union of immediate children of any seed
  // totalCascade = full transitive closure, deduplicated, excluding seeds
  const seedSet = new Set(seedIds);
  const direct = new Set();
  const totalCascade = new Set();
  const byDepth = new Map();

  // Direct level
  for (const sid of seedIds) {
    const children = DOWNSTREAM_EDGES[sid] || [];
    for (const c of children) {
      if (!seedSet.has(c)) direct.add(c);
    }
  }

  // BFS for total cascade
  let frontier = new Set(seedIds);
  let depth = 0;
  while (frontier.size > 0 && depth < 12) {
    const next = new Set();
    for (const node of frontier) {
      const children = DOWNSTREAM_EDGES[node] || [];
      for (const c of children) {
        if (!seedSet.has(c) && !totalCascade.has(c)) {
          totalCascade.add(c);
          if (!byDepth.has(c)) byDepth.set(c, depth + 1);
          next.add(c);
        }
      }
    }
    frontier = next;
    depth++;
  }

  return { direct, totalCascade, byDepth };
}

function getCascadeItem(id) {
  // Try local FACILITIES/PROCESSES/SYSTEMS data first (richer detail), then DEP_LOOKUP
  return lookup[id] || DEP_LOOKUP[id] || null;
}

/* Format a date as relative ("2 hours ago", "yesterday", "3 days ago") */
function formatRelativeDate(iso) {
  const then = new Date(iso);
  const now = new Date();
  const diffMs = now - then;
  const diffMin = Math.floor(diffMs / 60000);
  const diffHr = Math.floor(diffMin / 60);
  const diffDay = Math.floor(diffHr / 24);
  if (diffMin < 1) return 'just now';
  if (diffMin < 60) return `${diffMin} min ago`;
  if (diffHr < 24) return `${diffHr} hr ago`;
  if (diffDay === 1) return 'yesterday';
  if (diffDay < 7) return `${diffDay} days ago`;
  return then.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
}

/* Build a per-seed tree for visualization.
   Returns: array of trees, one per seed. Each tree node:
     { id, depth, children: [...], isDup: boolean, isSeed: boolean }
   - Children appear under each parent that reaches them (graph mirror)
   - Items marked isDup=true after their first appearance in this seed's tree
   - Items marked isSeed=true if they're another scenario seed (convergence point)
   - Cycles broken: a node never appears as its own descendant
*/
function buildCascadeTree(seedIds, maxDepth = 8) {
  const seedSet = new Set(seedIds);
  return seedIds.map(seedId => {
    const seenInThisTree = new Set([seedId]);

    function expand(nodeId, depth, ancestors) {
      const children = (DOWNSTREAM_EDGES[nodeId] || []).filter(c => !ancestors.has(c));
      const childNodes = [];
      for (const childId of children) {
        const isDup = seenInThisTree.has(childId);
        const isSeed = seedSet.has(childId) && childId !== seedId;
        const node = {
          id: childId,
          depth: depth + 1,
          isDup,
          isSeed,
          children: [],
        };
        // Only recurse the FIRST time we see this child (to prevent infinite expansion);
        // duplicate occurrences render as leaf rows with the dup badge.
        if (!isDup && depth + 1 < maxDepth) {
          seenInThisTree.add(childId);
          const newAncestors = new Set(ancestors);
          newAncestors.add(childId);
          node.children = expand(childId, depth + 1, newAncestors);
        }
        childNodes.push(node);
      }
      return childNodes;
    }

    return {
      id: seedId,
      depth: 0,
      isDup: false,
      isSeed: true,
      children: expand(seedId, 0, new Set([seedId])),
    };
  });
}

const ALL = [...PROCESSES, ...SYSTEMS, ...FACILITIES];
const lookup = Object.fromEntries(ALL.map(x => [x.id, x]));

