/* ============================================================================
   DESKTOP RESPONSIVENESS PRIMITIVES (Sprint 1 - Session 1.6)

   The DST is mobile-first. At and above DESKTOP_BREAKPOINT, a persistent
   sidebar takes over primary navigation and the app rearranges to a
   sidebar + main-content layout. Below the breakpoint, behavior is
   unchanged from the v15-equivalent mobile-only experience.

   See DST_Desktop_Responsiveness_Plan.md for the full set of decisions.
   ============================================================================ */

const DESKTOP_BREAKPOINT = 1024;
const SIDEBAR_WIDTH = 240;

// Watches window.innerWidth and reports whether we're at or above the
// desktop breakpoint. Returns false on first render in environments where
// `window` is unavailable (SSR), then flips on mount if applicable.
function useIsDesktop() {
  const getMatch = () => typeof window !== 'undefined'
    && window.innerWidth >= DESKTOP_BREAKPOINT;
  const [isDesktop, setIsDesktop] = useState(getMatch);
  useEffect(() => {
    const onResize = () => setIsDesktop(getMatch());
    onResize();                                  // sync on mount
    window.addEventListener('resize', onResize);
    return () => window.removeEventListener('resize', onResize);
  }, []);
  return isDesktop;
}

/* ============================================================================
   BRAND LOGO - Renders the org's stacked logo PNG from the public folder.
   Logo paths and aspect ratio sourced from dst.config.js.
   Component name kept as PCCALogo for backwards compatibility with existing
   call sites; the rendered output is whatever logo is configured.
   ============================================================================ */

function PCCALogo({ height = 64, showWordmark = true }) {
  const src = DST_CONFIG.logo.stackedSrc;
  const aspectRatio = DST_CONFIG.logo.stackedAspectRatio;
  const displayWidth = height * aspectRatio;
  return (
    <img
      src={src}
      alt={DST_CONFIG.logo.altText}
      style={{
        height: height,
        width: displayWidth,
        display: 'block',
        objectFit: 'contain',
      }}
    />
  );
}

// White brand logo for placement directly on the dark slate background (login
// page, desktop sidebar) — no white box behind it. Sized by height; width
// derives from the asset's aspect ratio.
function WhiteLogo({ height = 64 }) {
  const src = DST_CONFIG.logo.whiteSrc;
  const aspectRatio = DST_CONFIG.logo.whiteAspectRatio || 1.347;
  return (
    <img
      src={src}
      alt={DST_CONFIG.logo.altText}
      style={{
        height: height,
        width: height * aspectRatio,
        display: 'block',
        objectFit: 'contain',
      }}
    />
  );
}

