/* ============================================================================
   SIDEBAR (Session 1.6) - Desktop-only persistent navigation

   Rendered only at and above DESKTOP_BREAKPOINT. Fixed width, full height,
   always visible (no collapse). Replaces the BottomNav's role as primary
   navigation on desktop.

   Items are listed top-to-bottom per Decision 3 of the Desktop Plan:
     - Logo (larger than mobile)
     - Home / Scenarios / Map / Critical Contacts / Admin Portal (admin only)
     - Spacer
     - User menu (avatar + name + sign-out)

   Active nav item gets a left-edge accent fill and brand-color text.
   ============================================================================ */

function Sidebar({
  currentUser, activeKey, onNavigate, onLogout,
}) {
  const items = [
    { key: 'home',            label: 'Home',              icon: HomeIcon,       screen: 'home' },
    { key: 'currentScenario', label: 'Current Scenario',  icon: Activity,       screen: 'scenario' },
    { key: 'savedScenarios',  label: 'Saved Scenarios',   icon: ClipboardList,  screen: 'myScenarios' },
    { key: 'map',             label: 'Map / Weather',     icon: MapIcon,        screen: 'map' },
    { key: 'contacts',        label: 'Critical Contacts', icon: Users,          screen: 'contacts' },
  ];
  if (currentUser?.role === 'admin') {
    items.push({ key: 'admin', label: 'Admin Portal', icon: UserCog, screen: 'admin' });
  }
  // Instructions — always last (under Critical Contacts for users, under Admin
  // Portal for admins). Opens the overview PDF in a new tab rather than
  // navigating to an in-app screen.
  items.push({ key: 'instructions', label: 'Instructions', icon: FileText, screen: '__overview__' });

  return (
    <aside className="dst-no-print" style={{
      width: SIDEBAR_WIDTH, flexShrink: 0, height: '100%',
      background: T.darkBlue,
      display: 'flex', flexDirection: 'column',
      borderRight: `1px solid ${T.navy}`,
      overflowY: 'auto',
    }}>
      {/* Logo block — white logo directly on the slate background (no box) */}
      <div style={{
        padding: '24px 20px 20px',
        display: 'flex', justifyContent: 'center', alignItems: 'center',
        borderBottom: `1px solid ${T.navy}`,
      }}>
        <WhiteLogo height={84}/>
      </div>

      {/* Nav items */}
      <nav style={{ padding: '12px 0', flex: 1 }}>
        {items.map(({ key, label, icon: Icon, screen }) => {
          const active = activeKey === key;
          return (
            <button
              key={key}
              onClick={() => {
                if (screen === '__overview__') {
                  window.open(DST_CONFIG.overviewPdf, '_blank', 'noopener,noreferrer');
                } else {
                  onNavigate(screen);
                }
              }}
              style={{
                width: '100%', display: 'flex', alignItems: 'center', gap: 12,
                padding: '12px 20px',
                background: active ? T.navy : 'transparent',
                color: active ? '#fff' : 'rgba(255,255,255,0.78)',
                border: 'none', cursor: 'pointer',
                borderLeft: `3px solid ${active ? T.teal : 'transparent'}`,
                fontFamily: 'Poppins, sans-serif',
                fontSize: 13, fontWeight: active ? 600 : 500,
                letterSpacing: '0.02em', textAlign: 'left',
                transition: 'background 120ms ease, color 120ms ease',
              }}
              onMouseEnter={e => { if (!active) e.currentTarget.style.background = 'rgba(255,255,255,0.05)'; }}
              onMouseLeave={e => { if (!active) e.currentTarget.style.background = 'transparent'; }}
            >
              <Icon size={17} strokeWidth={2}/>
              <span>{label}</span>
            </button>
          );
        })}
      </nav>

      {/* User menu (bottom-anchored via flex spacer above) */}
      {currentUser && (
        <div style={{
          padding: '14px 16px 20px',
          borderTop: `1px solid ${T.navy}`,
          display: 'flex', flexDirection: 'column', gap: 10,
        }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
            <div style={{
              width: 36, height: 36, borderRadius: '50%',
              background: currentUser.role === 'admin' ? '#7A1F12' : T.teal,
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              fontFamily: '"Zilla Slab", serif', fontWeight: 700, fontSize: 15,
              color: '#fff', flexShrink: 0,
            }}>
              {(currentUser.name || currentUser.email).charAt(0).toUpperCase()}
            </div>
            <div style={{ minWidth: 0, flex: 1 }}>
              <div style={{
                fontFamily: 'Poppins, sans-serif', fontSize: 12, fontWeight: 600,
                color: '#fff', overflow: 'hidden', textOverflow: 'ellipsis',
                whiteSpace: 'nowrap',
              }}>{currentUser.name || currentUser.email}</div>
              <div style={{
                fontFamily: 'Poppins, sans-serif', fontSize: 10,
                color: 'rgba(255,255,255,0.55)', letterSpacing: '0.06em',
                textTransform: 'uppercase', marginTop: 1,
              }}>{currentUser.role === 'admin' ? 'Admin' : 'User'}</div>
            </div>
          </div>
          <button onClick={onLogout} style={{
            display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 6,
            padding: '8px 10px', background: 'transparent', color: 'rgba(255,255,255,0.78)',
            border: `1px solid rgba(255,255,255,0.18)`, cursor: 'pointer',
            fontFamily: 'Poppins, sans-serif', fontSize: 10, fontWeight: 700,
            letterSpacing: '0.12em', textTransform: 'uppercase',
          }}
          onMouseEnter={e => { e.currentTarget.style.background = 'rgba(255,255,255,0.05)'; }}
          onMouseLeave={e => { e.currentTarget.style.background = 'transparent'; }}
          >
            <LogOut size={12} strokeWidth={2}/>
            Sign Out
          </button>
        </div>
      )}
    </aside>
  );
}

// Map a screen-state value to its sidebar nav key. Used so the active item
// stays highlighted even when the user is deep inside a screen (e.g. on a
// process detail page, the "Home" key remains active since detail pages
// originate from Home -> list -> detail).
function screenToSidebarKey(screen) {
  switch (screen) {
    case 'home':                                    return 'home';
    case 'list': case 'detail': case 'deps':        return 'home';
    case 'scenario':
    case 'cascade': case 'report': case 'notes':    return 'currentScenario';
    case 'myScenarios':                             return 'savedScenarios';
    case 'map':                                     return 'map';
    case 'contacts':                                return 'contacts';
    case 'admin':                                   return 'admin';
    default:                                        return null;
  }
}

function Sheet({ open, onClose, title, children }) {
  // Session 1.8: Sheet renders as a bottom-sheet on mobile (existing behavior)
  // and as a centered modal on desktop. Content inside is unchanged at either
  // breakpoint - only the container, positioning, and chrome differ.
  const isDesktop = useIsDesktop();

  // Escape-to-close. Listening on window so the keystroke works regardless of
  // which element has focus inside the sheet. Effect runs only while open so
  // closed sheets do not consume keystrokes.
  useEffect(() => {
    if (!open) return;
    const onKey = (e) => { if (e.key === 'Escape') onClose(); };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [open, onClose]);

  if (!open) return null;
  return (
    <div onClick={onClose} style={{
      // Fixed to the viewport so the modal covers the sidebar too on desktop.
      // On mobile there is no sidebar so this is visually identical to the
      // pre-1.8 absolute positioning.
      position: 'fixed', inset: 0, zIndex: 200,
      background: 'rgba(14,30,51,0.5)',
      display: 'flex',
      alignItems: isDesktop ? 'center'        : 'flex-end',
      justifyContent: isDesktop ? 'center'    : 'stretch',
      padding: isDesktop ? '24px' : 0,
      animation: 'fadeIn 200ms ease',
    }}>
      <style>{`
        @keyframes fadeIn  { from { opacity: 0; }                          to { opacity: 1; } }
        @keyframes slideUp { from { transform: translateY(100%); }          to { transform: translateY(0); } }
        @keyframes scaleIn { from { transform: scale(0.96); opacity: 0; }   to { transform: scale(1); opacity: 1; } }
      `}</style>
      <div onClick={e => e.stopPropagation()} style={{
        background: T.bg,
        width: isDesktop ? 'min(640px, 100%)' : '100%',
        maxHeight: isDesktop ? 'min(85vh, 760px)' : '85%',
        // Top corners are always rounded; bottom corners only on desktop where
        // the sheet floats as a card. On mobile the bottom is the edge of the
        // viewport, so square bottom corners look correct.
        borderTopLeftRadius: 20, borderTopRightRadius: 20,
        borderBottomLeftRadius: isDesktop ? 20 : 0,
        borderBottomRightRadius: isDesktop ? 20 : 0,
        padding: '12px 0 24px',
        overflow: 'hidden',
        display: 'flex', flexDirection: 'column',
        boxShadow: isDesktop ? '0 20px 60px rgba(0,0,0,0.35)' : 'none',
        animation: isDesktop
          ? 'scaleIn 200ms cubic-bezier(0.4, 0, 0.2, 1)'
          : 'slideUp 240ms cubic-bezier(0.4, 0, 0.2, 1)',
      }}>
        {/* Drag handle (mobile only). On a bottom sheet, the pill is a
            touch-affordance hint. On desktop a centered modal does not drag
            and the pill would just be visual clutter. */}
        {!isDesktop && (
          <div style={{ width: 38, height: 4, background: T.rule, borderRadius: 2, margin: '0 auto 12px' }}/>
        )}
        <div style={{
          padding: isDesktop ? '4px 24px 14px' : '0 20px 12px',
          borderBottom: `1px solid ${T.ruleSoft}`,
          display: 'flex', justifyContent: 'space-between', alignItems: 'center',
        }}>
          <div style={{
            fontFamily: '"Zilla Slab", serif', fontSize: 18, fontWeight: 600,
            color: T.darkBlue, letterSpacing: '-0.01em',
          }}>{title}</div>
          <button onClick={onClose} style={{
            background: 'transparent', border: 'none', padding: 4, cursor: 'pointer',
            color: T.ink3, display: 'inline-flex',
          }}><X size={18}/></button>
        </div>
        <div style={{ padding: '16px 20px', overflowY: 'auto' }}>
          {children}
        </div>
      </div>
    </div>
  );
}

/* ============================================================================
   LOGIN SCREEN — production wires Cognito SDK; mockup uses local user list
   ============================================================================ */

function LoginScreen({ onLogin }) {
  // Two-step Cognito-backed sign-in flow.
  // Step 1: credentials (email + password). Calls signIn() from auth.js.
  //   - On success, calls onLogin(user, tokens) and we're done.
  //   - On force-password-change, transitions to step 2.
  // Step 2: newpassword (new password + confirm). Calls
  //   completeNewPassword() from auth.js. On success, calls onLogin().
  // No mockup users array; Cognito is the authority.
  const [step, setStep]                       = useState('credentials');
  const [email, setEmail]                     = useState('');
  const [password, setPassword]               = useState('');
  const [newPassword, setNewPassword]         = useState('');
  const [newPasswordConfirm, setNewPasswordConfirm] = useState('');
  const [error, setError]                     = useState(null);
  const [submitting, setSubmitting]           = useState(false);
  const [pendingUser, setPendingUser]         = useState(null);
  const [pendingAttributes, setPendingAttributes] = useState({});

  const handleSubmitCredentials = async () => {
    setError(null);
    const trimmed = email.trim().toLowerCase();
    if (!trimmed)              { setError('Enter your email to continue.'); return; }
    if (!trimmed.includes('@')){ setError("That doesn't look like an email address."); return; }
    if (!password)             { setError('Enter your password.'); return; }
    setSubmitting(true);
    try {
      const result = await signIn(trimmed, password);
      if (result.status === 'success') {
        if (result.user.status === 'deactivated') {
          setError('This account has been deactivated. Contact an admin.');
          setSubmitting(false);
          return;
        }
        if (result.user.status === 'pending') {
          setError('This account is pending activation. Contact an admin to approve the invitation.');
          setSubmitting(false);
          return;
        }
        onLogin(result.user, result.tokens);
      } else if (result.status === 'NEW_PASSWORD_REQUIRED') {
        setPendingUser(result.cognitoUser);
        setPendingAttributes(result.userAttributes);
        setStep('newpassword');
        setSubmitting(false);
      }
    } catch (err) {
      setError(friendlyAuthError(err));
      setSubmitting(false);
    }
  };

  const handleSubmitNewPassword = async () => {
    setError(null);
    if (!newPassword)                          { setError('Enter a new password.'); return; }
    if (newPassword.length < 8)                { setError('Password must be at least 8 characters.'); return; }
    if (newPassword !== newPasswordConfirm)    { setError('Passwords do not match.'); return; }
    setSubmitting(true);
    try {
      const result = await completeNewPassword(pendingUser, newPassword, pendingAttributes);
      if (result.user.status === 'deactivated') {
        setError('This account has been deactivated. Contact an admin.');
        setSubmitting(false);
        return;
      }
      if (result.user.status === 'pending') {
        setError('This account is pending activation. Contact an admin.');
        setSubmitting(false);
        return;
      }
      onLogin(result.user, result.tokens);
    } catch (err) {
      setError(friendlyAuthError(err));
      setSubmitting(false);
    }
  };

  return (
    <div style={{
      minHeight: '100%',
      background: `linear-gradient(165deg, ${T.darkBlue} 0%, ${T.navy} 60%, #0A2A47 100%)`,
      display: 'flex', flexDirection: 'column',
      paddingTop: 48, paddingBottom: 24,
    }}>
      {/* Logo + brand — white logo directly on the background (no box) */}
      <div style={{ padding: '0 28px', textAlign: 'center', marginBottom: 32 }}>
        <div style={{
          display: 'inline-flex', marginBottom: 18,
        }}>
          <WhiteLogo height={92}/>
        </div>
        <div style={{
          fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 700,
          color: T.lightTeal, letterSpacing: '0.18em', textTransform: 'uppercase',
          marginBottom: 4, opacity: 0.9,
        }}>{DST_CONFIG.org.toolName}</div>
        <div style={{
          fontFamily: '"Zilla Slab", serif', fontSize: 22, fontWeight: 600,
          color: '#fff', letterSpacing: '-0.01em', lineHeight: 1.15,
        }}>
          {step === 'credentials' ? 'Sign in to continue' : 'Set a new password'}
        </div>
      </div>

      {/* Card */}
      <div style={{ margin: '0 20px', padding: '22px 20px', background: '#fff' }}>

        {step === 'credentials' && (
          <>
            <div style={{
              fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 700,
              letterSpacing: '0.14em', textTransform: 'uppercase', color: T.ink3,
              marginBottom: 6,
            }}>Email Address</div>
            <input
              type="email"
              value={email}
              onChange={e => setEmail(e.target.value)}
              onKeyDown={e => e.key === 'Enter' && !submitting && handleSubmitCredentials()}
              autoFocus
              placeholder={`you@${DST_CONFIG.org.emailDomain}`}
              autoCapitalize="none"
              autoCorrect="off"
              disabled={submitting}
              style={{
                width: '100%', padding: '12px 14px', boxSizing: 'border-box',
                fontFamily: 'Poppins, sans-serif', fontSize: 14, color: T.ink,
                border: `1.5px solid ${T.rule}`, outline: 'none', marginBottom: 14,
              }}/>

            <div style={{
              fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 700,
              letterSpacing: '0.14em', textTransform: 'uppercase', color: T.ink3,
              marginBottom: 6,
            }}>Password</div>
            <input
              type="password"
              value={password}
              onChange={e => setPassword(e.target.value)}
              onKeyDown={e => e.key === 'Enter' && !submitting && handleSubmitCredentials()}
              placeholder="Your password"
              autoComplete="current-password"
              disabled={submitting}
              style={{
                width: '100%', padding: '12px 14px', boxSizing: 'border-box',
                fontFamily: 'Poppins, sans-serif', fontSize: 14, color: T.ink,
                border: `1.5px solid ${T.rule}`, outline: 'none', marginBottom: 14,
              }}/>

            {error && (
              <div style={{
                marginBottom: 12, padding: '8px 10px',
                background: T.criticalSoft, border: `1px solid ${T.critical}`,
                fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink,
              }}>{error}</div>
            )}

            <button onClick={handleSubmitCredentials} disabled={submitting} style={{
              width: '100%', padding: '13px',
              background: submitting ? T.ink3 : T.darkBlue,
              color: '#fff', border: 'none',
              cursor: submitting ? 'wait' : 'pointer',
              fontFamily: 'Poppins, sans-serif', fontSize: 11, fontWeight: 700,
              letterSpacing: '0.12em', textTransform: 'uppercase',
            }}>{submitting ? 'Signing in...' : 'Sign In'}</button>

            <div style={{
              marginTop: 14,
              fontFamily: 'Poppins, sans-serif', fontSize: 10, color: T.ink3,
              lineHeight: 1.5, textAlign: 'center',
            }}>
              {DST_CONFIG.copy.acceptableUseNotice}
            </div>
            <div style={{
              marginTop: 6,
              fontFamily: 'Poppins, sans-serif', fontSize: 10, color: T.ink3,
              lineHeight: 1.5, textAlign: 'center',
            }}>
              Forgot your password? Contact an administrator.
            </div>
            <div style={{
              marginTop: 10, textAlign: 'center',
            }}>
              <a
                href={DST_CONFIG.overviewPdf}
                target="_blank"
                rel="noopener noreferrer"
                style={{
                  fontFamily: 'Poppins, sans-serif', fontSize: 11, fontWeight: 600,
                  color: T.teal, textDecoration: 'underline', cursor: 'pointer',
                }}
              >Click Here for an Overview and Instructions</a>
            </div>
          </>
        )}

        {step === 'newpassword' && (
          <>
            <div style={{
              padding: '8px 10px', background: T.surfaceAlt, border: `1px solid ${T.lightTeal}`,
              fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink2,
              marginBottom: 14, lineHeight: 1.45,
            }}>
              Your administrator created your account with a temporary password.
              Set a new password now to continue.
            </div>

            <div style={{
              fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 700,
              letterSpacing: '0.14em', textTransform: 'uppercase', color: T.ink3,
              marginBottom: 6,
            }}>New Password</div>
            <input
              type="password"
              value={newPassword}
              onChange={e => setNewPassword(e.target.value)}
              onKeyDown={e => e.key === 'Enter' && !submitting && handleSubmitNewPassword()}
              autoFocus
              autoComplete="new-password"
              disabled={submitting}
              style={{
                width: '100%', padding: '12px 14px', boxSizing: 'border-box',
                fontFamily: 'Poppins, sans-serif', fontSize: 14, color: T.ink,
                border: `1.5px solid ${T.rule}`, outline: 'none', marginBottom: 14,
              }}/>

            <div style={{
              fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 700,
              letterSpacing: '0.14em', textTransform: 'uppercase', color: T.ink3,
              marginBottom: 6,
            }}>Confirm New Password</div>
            <input
              type="password"
              value={newPasswordConfirm}
              onChange={e => setNewPasswordConfirm(e.target.value)}
              onKeyDown={e => e.key === 'Enter' && !submitting && handleSubmitNewPassword()}
              autoComplete="new-password"
              disabled={submitting}
              style={{
                width: '100%', padding: '12px 14px', boxSizing: 'border-box',
                fontFamily: 'Poppins, sans-serif', fontSize: 14, color: T.ink,
                border: `1.5px solid ${T.rule}`, outline: 'none', marginBottom: 14,
              }}/>

            {error && (
              <div style={{
                marginBottom: 12, padding: '8px 10px',
                background: T.criticalSoft, border: `1px solid ${T.critical}`,
                fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink,
              }}>{error}</div>
            )}

            <button onClick={handleSubmitNewPassword} disabled={submitting} style={{
              width: '100%', padding: '13px',
              background: submitting ? T.ink3 : T.darkBlue,
              color: '#fff', border: 'none',
              cursor: submitting ? 'wait' : 'pointer',
              fontFamily: 'Poppins, sans-serif', fontSize: 11, fontWeight: 700,
              letterSpacing: '0.12em', textTransform: 'uppercase',
            }}>{submitting ? 'Setting password...' : 'Set Password'}</button>

            <div style={{
              marginTop: 12, padding: '8px',
              background: T.bgAlt, border: `1px dashed ${T.rule}`,
              fontFamily: 'Poppins, sans-serif', fontSize: 10, color: T.ink3,
              lineHeight: 1.5, textAlign: 'center',
            }}>
              Password policy: 8+ characters, mixed case, at least one number and one symbol.
            </div>
          </>
        )}

      </div>

      {/* Footer */}
      <div style={{
        marginTop: 'auto', padding: '20px 24px 0',
        textAlign: 'center',
        fontFamily: 'Poppins, sans-serif', fontSize: 10, color: '#fff',
        opacity: 0.65, letterSpacing: '0.08em',
      }}>
        {DST_CONFIG.copy.portFooter}
      </div>
    </div>
  );
}

/* ============================================================================
   HOME
   ============================================================================ */

function Home({ onNavigate, scenarioCount, onOpenScenario, onOpenMap, onOpenContacts, onOpenMyScenarios, savedCount = 0, currentUser, onOpenAdmin, onOpenUserMenu, onLogout }) {
  // Map category iconKey strings to actual lucide-react components
  const ICON_MAP = { Activity, Server, Building2 };
  // Map category type to live count from current data
  const COUNT_MAP = {
    Process:  PROCESSES.length,
    System:   SYSTEMS.length,
    Facility: FACILITIES.length,
  };
  const cats = DST_CONFIG.categories.map(c => ({
    key:   c.key,
    label: c.label,
    desc:  c.desc,
    count: COUNT_MAP[c.type] || 0,
    Icon:  ICON_MAP[c.iconKey] || Activity,
  }));

  return (
    <>
      <TopNav
        title={DST_CONFIG.org.homeTitle}
        scenarioCount={scenarioCount}
        onScenarioTap={onOpenScenario}
        action={currentUser ? (
          <button onClick={onOpenUserMenu} style={{
            background: 'transparent', border: `1px solid ${T.rule}`,
            padding: '5px 8px', cursor: 'pointer',
            display: 'inline-flex', alignItems: 'center', gap: 5,
            fontFamily: 'Poppins, sans-serif', fontSize: 10, fontWeight: 700,
            color: T.darkBlue, letterSpacing: '0.04em',
          }}>
            <div style={{
              width: 18, height: 18,
              background: currentUser.role === 'admin' ? '#7A1F12' : T.darkBlue,
              color: '#fff',
              display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
              fontFamily: '"Zilla Slab", serif', fontSize: 10, fontWeight: 700,
            }}>{(currentUser.name || currentUser.email).charAt(0).toUpperCase()}</div>
            <ChevronDown size={11} strokeWidth={2}/>
          </button>
        ) : null}
      />
      <div style={{ padding: '14px 20px 18px' }}>
        {/* Logo + Title block — horizontal layout, equal heights */}
        <div style={{
          display: 'flex', alignItems: 'stretch', gap: 16,
          paddingBottom: 12, height: 80,
        }}>
          <div style={{ display: 'flex', alignItems: 'center' }}>
            <PCCALogo height={80} showWordmark={true}/>
          </div>
          <div style={{
            flex: 1, minWidth: 0,
            display: 'flex', flexDirection: 'column', justifyContent: 'center',
            fontFamily: '"Zilla Slab", serif', fontSize: 22, fontWeight: 600,
            color: T.darkBlue, letterSpacing: '-0.015em', lineHeight: 1.05,
          }}>
            <div>Decision</div>
            <div>Support</div>
            <div>Tool</div>
          </div>
        </div>
        <div style={{
          fontFamily: 'Poppins, sans-serif', fontSize: 11.5, color: T.ink2,
          fontWeight: 400, lineHeight: 1.45, marginBottom: 16,
        }}>{DST_CONFIG.org.tagline}</div>

        {/* Section label */}
        <div style={{
          fontFamily: 'Poppins, sans-serif', fontSize: 10, color: T.ink3,
          letterSpacing: '0.16em', textTransform: 'uppercase',
          marginBottom: 8, fontWeight: 600,
        }}>Select the disrupted asset type</div>

        {/* Category cards */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 1, background: T.rule }}>
          {cats.map(({ key, label, count, Icon, desc }) => (
            <button key={key} onClick={() => onNavigate(key)} style={{
              background: T.surface, border: 'none', padding: '14px 16px',
              textAlign: 'left', cursor: 'pointer',
              display: 'flex', alignItems: 'center', gap: 16,
              fontFamily: 'inherit',
              borderLeft: `3px solid ${T.teal}`,
            }}>
              <Icon size={26} strokeWidth={1.5} color={T.darkBlue} />
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{
                  fontFamily: '"Zilla Slab", serif', fontWeight: 600, fontSize: 17,
                  color: T.darkBlue, letterSpacing: '-0.01em', marginBottom: 2,
                }}>{label}</div>
                <div style={{
                  fontFamily: 'Poppins, sans-serif', fontSize: 12, color: T.ink2,
                  fontWeight: 400, lineHeight: 1.4,
                }}>{desc}</div>
              </div>
              <div style={{
                fontFamily: '"Zilla Slab", serif', fontWeight: 700, fontSize: 30,
                color: T.darkBlue, lineHeight: 1, letterSpacing: '-0.02em', marginRight: 4,
              }}>{count}</div>
              <ChevronRight size={16} color={T.teal} />
            </button>
          ))}
        </div>

        {/* TOOL TILES — Row 1: Scenario Builder · PCCA Map · Critical Contacts (always 3) */}
        <div style={{
          marginTop: 14,
          fontFamily: 'Poppins, sans-serif', fontSize: 10, color: T.ink3,
          letterSpacing: '0.16em', textTransform: 'uppercase',
          marginBottom: 8, fontWeight: 600,
        }}>Tools</div>

        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 8 }}>
          {/* Scenario Builder — Primary Dark Blue */}
          <button onClick={onOpenScenario} style={{
            background: T.darkBlue, border: 'none', cursor: 'pointer',
            padding: '12px 8px', textAlign: 'center',
            display: 'flex', flexDirection: 'column', alignItems: 'center',
            justifyContent: 'center', gap: 8, minHeight: 88,
            fontFamily: 'inherit',
          }}>
            <ClipboardList size={22} color="#fff" strokeWidth={1.5}/>
            <div style={{
              fontFamily: '"Zilla Slab", serif', fontSize: 13, fontWeight: 600,
              color: '#fff', lineHeight: 1.15, letterSpacing: '-0.005em',
            }}>Scenario<br/>Builder</div>
          </button>

          {/* Map tile — Bright Green */}
          <button onClick={onOpenMap} style={{
            background: '#5A8E3F', border: 'none', cursor: 'pointer',
            padding: '12px 8px', textAlign: 'center',
            display: 'flex', flexDirection: 'column', alignItems: 'center',
            justifyContent: 'center', gap: 8, minHeight: 88,
            fontFamily: 'inherit',
          }}>
            <MapIcon size={22} color="#fff" strokeWidth={1.5}/>
            <div style={{
              fontFamily: '"Zilla Slab", serif', fontSize: 13, fontWeight: 600,
              color: '#fff', lineHeight: 1.15, letterSpacing: '-0.005em',
            }}>{DST_CONFIG.org.shortName}<br/>Map / Weather</div>
          </button>

          {/* Critical Contacts — Light Teal */}
          <button onClick={onOpenContacts} style={{
            background: T.lightTeal, border: 'none', cursor: 'pointer',
            padding: '12px 8px', textAlign: 'center',
            display: 'flex', flexDirection: 'column', alignItems: 'center',
            justifyContent: 'center', gap: 8, minHeight: 88,
            fontFamily: 'inherit',
          }}>
            <Phone size={22} color={T.darkBlue} strokeWidth={1.5}/>
            <div style={{
              fontFamily: '"Zilla Slab", serif', fontSize: 13, fontWeight: 600,
              color: T.darkBlue, lineHeight: 1.15, letterSpacing: '-0.005em',
            }}>Critical<br/>Contacts</div>
          </button>
        </div>

        {/* Row 2: Current Scenario · My Scenarios · Admin Portal (admin only) */}
        {(() => {
          const isAdmin = currentUser?.role === 'admin';
          const showMy = savedCount > 0;
          // Column count: Current always shown; My when savedCount>0; Admin when admin
          const cols = 1 + (showMy ? 1 : 0) + (isAdmin ? 1 : 0);
          return (
            <div style={{
              marginTop: 8, display: 'grid',
              gridTemplateColumns: `repeat(${cols}, 1fr)`,
              gap: 8,
            }}>
              {/* Current Scenario — Gray */}
              <button onClick={onOpenScenario} style={{
                padding: '14px 12px',
                background: T.gray, color: '#fff', border: 'none', cursor: 'pointer',
                display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center',
                gap: 4, minHeight: 88,
                fontFamily: 'inherit', textAlign: 'center',
              }}>
                <div style={{
                  fontFamily: 'Poppins, sans-serif', fontSize: 9, letterSpacing: '0.14em',
                  textTransform: 'uppercase', color: '#fff', opacity: 0.85, fontWeight: 600,
                }}>Current Scenario</div>
                <div style={{
                  fontFamily: '"Zilla Slab", serif', fontSize: 28, fontWeight: 700,
                  color: '#fff', letterSpacing: '-0.02em', lineHeight: 1,
                }}>{scenarioCount}</div>
                <div style={{
                  fontFamily: 'Poppins, sans-serif', fontSize: 10, color: '#fff', opacity: 0.85, fontWeight: 400,
                }}>{scenarioCount === 0 ? 'no assets' : (scenarioCount === 1 ? 'asset' : 'assets')}</div>
              </button>
              {/* My Scenarios — Dark Blue (only when there are saved scenarios) */}
              {showMy && (
                <button onClick={onOpenMyScenarios} style={{
                  padding: '14px 12px',
                  background: T.darkBlue, color: '#fff', border: 'none', cursor: 'pointer',
                  display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center',
                  gap: 4, minHeight: 88,
                  fontFamily: 'inherit', textAlign: 'center',
                }}>
                  <div style={{
                    fontFamily: 'Poppins, sans-serif', fontSize: 9, letterSpacing: '0.14em',
                    textTransform: 'uppercase', color: '#fff', opacity: 0.85, fontWeight: 600,
                  }}>My Scenarios</div>
                  <div style={{
                    fontFamily: '"Zilla Slab", serif', fontSize: 28, fontWeight: 700,
                    color: '#fff', letterSpacing: '-0.02em', lineHeight: 1,
                  }}>{savedCount}</div>
                  <div style={{
                    fontFamily: 'Poppins, sans-serif', fontSize: 10, color: '#fff', opacity: 0.85, fontWeight: 400,
                  }}>saved</div>
                </button>
              )}
              {/* Admin Portal — Navy (admin only) */}
              {isAdmin && (
                <button onClick={onOpenAdmin} style={{
                  padding: '14px 12px',
                  background: T.navy, color: '#fff', border: 'none', cursor: 'pointer',
                  display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center',
                  gap: 6, minHeight: 88,
                  fontFamily: 'inherit', textAlign: 'center',
                }}>
                  <UserCog size={22} color="#fff" strokeWidth={1.5}/>
                  <div style={{
                    fontFamily: '"Zilla Slab", serif', fontSize: 13, fontWeight: 600,
                    color: '#fff', lineHeight: 1.15, letterSpacing: '-0.005em',
                  }}>Admin<br/>Portal</div>
                </button>
              )}
            </div>
          );
        })()}

        {/* Row 3: Instructions — full width, only as tall as needed */}
        <button onClick={() => window.open(DST_CONFIG.overviewPdf, '_blank', 'noopener,noreferrer')} style={{
          marginTop: 8, width: '100%',
          background: T.surfaceAlt, border: `1px solid ${T.rule}`, cursor: 'pointer',
          padding: '10px 14px',
          display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8,
          fontFamily: 'inherit',
        }}>
          <FileText size={16} color={T.darkBlue} strokeWidth={1.5}/>
          <span style={{
            fontFamily: '"Zilla Slab", serif', fontSize: 13, fontWeight: 600,
            color: T.darkBlue, letterSpacing: '-0.005em',
          }}>Overview &amp; Instructions</span>
        </button>
      </div>

      {/* Footer with version/status/logout */}
      <div style={{
        borderTop: `1px solid ${T.rule}`, padding: '12px 20px',
        display: 'flex', justifyContent: 'space-between', alignItems: 'center',
        background: T.bgAlt, gap: 8,
      }}>
        <div style={{
          fontFamily: 'Poppins, sans-serif', fontSize: 10, color: T.ink3,
          letterSpacing: '0.1em', textTransform: 'uppercase', fontWeight: 600,
        }}>{DISPLAY_VERSION}</div>
        <div style={{
          display: 'inline-flex', alignItems: 'center', gap: 6,
          fontFamily: 'Poppins, sans-serif', fontSize: 10, color: T.low,
          letterSpacing: '0.1em', textTransform: 'uppercase', fontWeight: 600,
        }}>
          <span style={{ width: 7, height: 7, background: T.low, borderRadius: '50%' }}/>
          Offline Ready
        </div>
        {currentUser && (
          <button onClick={onLogout} style={{
            background: 'transparent', border: 'none', cursor: 'pointer',
            color: T.ink3, padding: 0,
            fontFamily: 'Poppins, sans-serif', fontSize: 10, fontWeight: 600,
            letterSpacing: '0.1em', textTransform: 'uppercase',
            display: 'inline-flex', alignItems: 'center', gap: 4,
          }}>
            <LogOut size={11}/> Sign Out
          </button>
        )}
      </div>
    </>
  );
}

/* ============================================================================
   LIST
   ============================================================================ */

function CategoryList({ category, items, onOpen, onBack, scenarioCount, scenario, addToScenario, onScenarioTap, onHome }) {
  const [query, setQuery] = useState('');
  const [sortBy, setSortBy] = useState('score');
  const [deptFilter, setDeptFilter] = useState('All');
  const [deptOpen, setDeptOpen] = useState(false);
  const [multiSelect, setMultiSelect] = useState(false);
  const [picked, setPicked] = useState([]);

  const depts = useMemo(() => ['All', ...new Set(items.map(i => i.dept))].sort(), [items]);

  const filtered = useMemo(() => {
    let r = items;
    if (query) {
      const q = query.toLowerCase();
      r = r.filter(i =>
        i.name.toLowerCase().includes(q) || i.dept.toLowerCase().includes(q));
    }
    if (deptFilter && deptFilter !== 'All') r = r.filter(i => i.dept === deptFilter);
    r = [...r];
    if (sortBy === 'score') r.sort((a, b) => b.restorationScore - a.restorationScore);
    if (sortBy === 'name') r.sort((a, b) => a.name.localeCompare(b.name));
    if (sortBy === 'dept') r.sort((a, b) => a.dept.localeCompare(b.dept));
    return r;
  }, [items, query, sortBy, deptFilter]);

  // Category labels and type-strings derived from config
  const titles = Object.fromEntries(
    DST_CONFIG.categories.map(c => [c.key, c.label])
  );
  const typeWord = Object.fromEntries(
    DST_CONFIG.categories.map(c => [c.key, c.type])
  )[category];

  const toggleMulti = () => {
    setMultiSelect(m => !m);
    setPicked([]);
  };
  const togglePick = (id) => {
    setPicked(p => p.includes(id) ? p.filter(x => x !== id) : [...p, id]);
  };
  const commitPicks = () => {
    picked.forEach(id => addToScenario(id));
    setMultiSelect(false);
    setPicked([]);
  };

  return (
    <>
      <TopNav
        back={onBack} title={titles[category]} sub={DST_CONFIG.org.homeTitle}
        scenarioCount={scenarioCount}
        onScenarioTap={onScenarioTap}
        action={
          <button onClick={toggleMulti} style={{
            background: multiSelect ? T.darkBlue : 'transparent',
            color: multiSelect ? '#fff' : T.darkBlue,
            border: `1px solid ${T.darkBlue}`,
            padding: '5px 10px', cursor: 'pointer',
            fontFamily: 'Poppins, sans-serif', fontSize: 10, fontWeight: 700,
            letterSpacing: '0.08em', textTransform: 'uppercase',
          }}>{multiSelect ? 'Done' : 'Multi-select'}</button>
        }
      />
      <div style={{ padding: '12px 16px 88px' }}>
        {/* Search */}
        <div style={{
          display: 'flex', alignItems: 'center', gap: 8, padding: '8px 12px',
          border: `1px solid ${T.rule}`, background: T.surface, marginBottom: 10,
        }}>
          <Search size={14} color={T.ink3} />
          <input
            value={query} onChange={e => setQuery(e.target.value)}
            placeholder="Search…"
            style={{
              border: 'none', outline: 'none', flex: 1,
              fontFamily: 'Poppins, sans-serif', fontSize: 13,
              color: T.ink, background: 'transparent',
            }}
          />
          {query && <button onClick={() => setQuery('')} style={{
            background: 'none', border: 'none', cursor: 'pointer',
            color: T.ink3, padding: 0, display: 'inline-flex',
          }}><X size={14}/></button>}
        </div>

        {/* Sort */}
        <div style={{ display: 'flex', justifyContent: 'space-between', gap: 10, marginBottom: 10 }}>
          <div style={{
            display: 'inline-flex', border: `1px solid ${T.rule}`, background: T.surface,
          }}>
            {[
              { k: 'score', label: 'Score' },
              { k: 'name', label: 'A–Z' },
              { k: 'dept', label: 'Dept' },
            ].map(({ k, label }) => (
              <button key={k} onClick={() => setSortBy(k)} style={{
                padding: '7px 12px', border: 'none', cursor: 'pointer',
                fontFamily: 'Poppins, sans-serif', fontSize: 10, fontWeight: 600,
                letterSpacing: '0.08em', textTransform: 'uppercase',
                background: sortBy === k ? T.darkBlue : 'transparent',
                color: sortBy === k ? '#fff' : T.ink2,
              }}>{label}</button>
            ))}
          </div>

          {/* Department dropdown */}
          <div style={{ position: 'relative' }}>
            <button onClick={() => setDeptOpen(o => !o)} style={{
              padding: '7px 10px', border: `1px solid ${T.rule}`,
              background: T.surface, color: T.ink, cursor: 'pointer',
              fontFamily: 'Poppins, sans-serif', fontSize: 11, fontWeight: 500,
              display: 'inline-flex', alignItems: 'center', gap: 6,
            }}>
              <span style={{ fontWeight: 600, fontSize: 9, letterSpacing: '0.08em', textTransform: 'uppercase', color: T.ink3 }}>Dept</span>
              {deptFilter}
              <ChevronDown size={12} />
            </button>
            {deptOpen && (
              <div style={{
                position: 'absolute', top: '100%', right: 0, marginTop: 4,
                background: T.surface, border: `1px solid ${T.rule}`,
                minWidth: 200, maxHeight: 280, overflowY: 'auto', zIndex: 30,
                boxShadow: '0 8px 24px rgba(14,30,51,0.12)',
              }}>
                {depts.map(d => (
                  <button key={d} onClick={() => { setDeptFilter(d); setDeptOpen(false); }} style={{
                    display: 'block', width: '100%', textAlign: 'left',
                    padding: '10px 14px', border: 'none', cursor: 'pointer',
                    background: deptFilter === d ? T.surfaceAlt : 'transparent',
                    fontFamily: 'Poppins, sans-serif', fontSize: 12, fontWeight: 500,
                    color: deptFilter === d ? T.darkBlue : T.ink, borderBottom: `1px solid ${T.ruleSoft}`,
                  }}>{d}</button>
                ))}
              </div>
            )}
          </div>
        </div>

        <div style={{
          display: 'flex', justifyContent: 'space-between', alignItems: 'baseline',
          padding: '4px 0 8px', borderBottom: `1px solid ${T.darkBlue}`,
          fontFamily: 'Poppins, sans-serif', fontSize: 10, color: T.ink3,
          letterSpacing: '0.1em', textTransform: 'uppercase', fontWeight: 600,
        }}>
          <span>Showing {filtered.length} of {items.length}</span>
          {multiSelect && <span style={{ color: T.teal }}>{picked.length} selected</span>}
        </div>

        {/* List */}
        {filtered.map(item => {
          const isPicked = picked.includes(item.id);
          const inScenario = scenario.includes(item.id);
          return (
            <button
              key={item.id}
              onClick={() => multiSelect ? togglePick(item.id) : onOpen(item.id)}
              style={{
                width: '100%', display: 'flex', gap: 12, alignItems: 'center',
                padding: '14px 6px', textAlign: 'left', cursor: 'pointer',
                borderBottom: `1px solid ${T.ruleSoft}`,
                background: isPicked ? T.surfaceAlt : T.surface,
                border: 0, borderBottomWidth: 1, borderBottomStyle: 'solid',
                borderBottomColor: T.ruleSoft, fontFamily: 'inherit',
              }}
            >
              {multiSelect && (
                <div style={{
                  width: 22, height: 22, borderRadius: 4,
                  border: `2px solid ${isPicked ? T.darkBlue : T.rule}`,
                  background: isPicked ? T.darkBlue : 'transparent',
                  display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
                  flexShrink: 0,
                }}>
                  {isPicked && <Check size={14} color="#fff" strokeWidth={3}/>}
                </div>
              )}
              <ScoreTile score={item.restorationScore} type={item.type} small />
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{
                  fontFamily: 'Poppins, sans-serif', fontSize: 10, color: T.ink3,
                  letterSpacing: '0.04em', fontWeight: 600, marginBottom: 3,
                  textTransform: 'uppercase',
                }}>{typeWord} - {item.id} · Priority {item.priority}</div>
                <div style={{
                  fontFamily: '"Zilla Slab", serif', fontSize: 14, fontWeight: 600,
                  color: T.darkBlue, letterSpacing: '-0.005em', marginBottom: 4, lineHeight: 1.2,
                }}>{item.name}</div>
                <DeptChip name={item.dept} tiny />
              </div>
              {!multiSelect && (
                inScenario
                  ? <Check size={14} color={T.teal} strokeWidth={3} />
                  : <ChevronRight size={14} color={T.ink3} />
              )}
            </button>
          );
        })}
        {filtered.length === 0 && (
          <div style={{
            padding: 32, textAlign: 'center', fontFamily: 'Poppins, sans-serif',
            color: T.ink3, fontSize: 13,
          }}>No results.</div>
        )}
      </div>

      {/* Multi-select action bar */}
      {multiSelect && picked.length > 0 && (
        <div style={{
          position: 'absolute', bottom: 0, left: 0, right: 0,
          padding: '12px 16px', background: T.darkBlue,
          display: 'flex', alignItems: 'center', gap: 12, zIndex: 40,
          boxShadow: '0 -4px 20px rgba(0,0,0,0.15)',
        }}>
          <div style={{ flex: 1, color: '#fff' }}>
            <div style={{
              fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 600,
              letterSpacing: '0.1em', textTransform: 'uppercase', opacity: 0.7,
            }}>Adding to scenario</div>
            <div style={{
              fontFamily: '"Zilla Slab", serif', fontSize: 17, fontWeight: 600,
            }}>{picked.length} {picked.length === 1 ? 'asset' : 'assets'}</div>
          </div>
          <button onClick={commitPicks} style={{
            padding: '10px 18px', background: T.teal, color: '#fff',
            border: 'none', cursor: 'pointer',
            fontFamily: 'Poppins, sans-serif', fontSize: 11, fontWeight: 700,
            letterSpacing: '0.1em', textTransform: 'uppercase',
            display: 'inline-flex', alignItems: 'center', gap: 6,
          }}>
            <Plus size={14}/> Add to Scenario
          </button>
        </div>
      )}
      <BottomNav onPrevious={onBack} onHome={onHome} />
    </>
  );
}

/* ============================================================================
   DETAIL — 3 tabs only; Dependencies is a separate screen
   ============================================================================ */

const TYPE_ICON = {
  process: Activity, system: Server, facility: Building2,
  workforce: Users, vendor: Package, dept: Layers,
};
const TYPE_LABEL = {
  process: 'Process', system: 'System', facility: 'Facility',
  workforce: 'Workforce', vendor: 'Vendor', dept: 'Dept',
};

function DepRow({ dep, onOpen }) {
  const Icon = TYPE_ICON[dep.type] || Activity;
  const linked = !!dep.id && !!lookup[dep.id];
  const content = (
    <div style={{
      display: 'flex', gap: 10, alignItems: 'center', padding: '10px 4px',
      borderBottom: `1px solid ${T.ruleSoft}`,
    }}>
      <Icon size={14} color={T.darkBlue} strokeWidth={1.5}/>
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{
          fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 600,
          color: T.ink3, letterSpacing: '0.1em', textTransform: 'uppercase',
          marginBottom: 2,
        }}>{TYPE_LABEL[dep.type]}</div>
        <div style={{
          fontFamily: 'Poppins, sans-serif', fontSize: 13, color: T.ink,
          fontWeight: linked ? 500 : 400,
        }}>{dep.name}</div>
      </div>
      {linked && <ChevronRight size={13} color={T.teal} />}
    </div>
  );
  if (linked) return <div onClick={() => onOpen(dep.id)} style={{ cursor: 'pointer' }}>{content}</div>;
  return content;
}

function Detail({ id, onOpen, onBack, onOpenDeps, inScenario, toggleScenario, scenarioCount, onScenarioTap, onHome }) {
  const item = lookup[id];
  const [tab, setTab] = useState('overview');
  const [scoreInfoOpen, setScoreInfoOpen] = useState(false);
  const [priorityInfoOpen, setPriorityInfoOpen] = useState(false);
  const [contactOpen, setContactOpen] = useState(false);
  const isDesktop = useIsDesktop();

  useEffect(() => { setTab('overview'); }, [id]);
  // If the user crosses into the desktop breakpoint while sitting on the
  // standalone Short-Term tab, hop them to the Critical Questions tab where
  // the same content is now visible in the right column. Without this, the
  // tabs array would no longer contain 'short-term' and the page would
  // render no tab content at all.
  useEffect(() => {
    if (isDesktop && tab === 'short-term') setTab('questions');
  }, [isDesktop, tab]);
  if (!item) return null;

  const poc = getPOC(item);
  const isFacility = item.type === 'Facility';
  const hasMapData = isFacility && item.lat && item.lng;
  // Tab list. On desktop the Critical Questions tab is relabeled to reflect
  // that it now surfaces short-term content in its right column, and the
  // standalone Short-Term tab is hidden because that content is already
  // visible alongside the questions (avoids redundant nav).
  const tabs = [
    { k: 'overview',   label: 'Overview' },
    { k: 'questions',  label: isDesktop ? 'Critical Questions / Short-Term Options' : 'Critical Questions' },
    ...(isDesktop ? [] : [{ k: 'short-term', label: 'Short-Term' }]),
    ...(isFacility ? [{ k: 'info', label: 'Info' }] : []),
  ];
  const typeWord = item.type;

  // -----------------------------------------------------------------------
  // Reusable content blocks (Session 1.7)
  //
  // The Short-Term content needs to render in two places on desktop: in its
  // own tab (Short-Term) AND in the right column of the Critical Questions
  // tab. Defining it once here avoids duplicating the phase-banner markup.
  // -----------------------------------------------------------------------
  const shortTermBlock = (
    <div>
      <div style={{
        fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink3,
        fontStyle: 'italic', margin: '0 0 16px 0', fontWeight: 400, lineHeight: 1.4,
      }}>Workarounds identified through department interviews. Reminders, not prescriptive playbooks.</div>
      {item.shortTerm.map((s, i) => (
        <div key={i} style={{
          marginBottom: 16, border: `1px solid ${T.ruleSoft}`,
        }}>
          {/* Phase banner header */}
          <div style={{
            background: T.surfaceAlt, padding: '10px 14px',
            fontFamily: 'Poppins, sans-serif', fontSize: 11, fontWeight: 700,
            color: T.ink2, letterSpacing: '0.14em', textTransform: 'uppercase',
            borderBottom: `1px solid ${T.ruleSoft}`,
          }}>{s.head}</div>
          {/* Action items with amber custom bullets */}
          <ul style={{
            listStyle: 'none', padding: '12px 14px', margin: 0,
            fontFamily: 'Poppins, sans-serif', fontSize: 13, lineHeight: 1.5,
            color: T.ink, fontWeight: 400,
          }}>
            {s.body.map((b, j) => (
              <li key={j} style={{
                display: 'flex', gap: 10, alignItems: 'flex-start',
                padding: '4px 0',
              }}>
                <span style={{
                  color: T.teal, fontSize: 16, lineHeight: 1.2,
                  flexShrink: 0, marginTop: -1, fontWeight: 700,
                }}>•</span>
                <span>{b}</span>
              </li>
            ))}
          </ul>
        </div>
      ))}
    </div>
  );

  // CSS for the two-column grid used on desktop. Mobile gets an empty object
  // so the children stack naturally as block elements.
  const twoColGrid = isDesktop
    ? { display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 28 }
    : {};

  return (
    <>
      <TopNav back={onBack} title={item.name} sub={`${typeWord} - ${item.id}`} scenarioCount={scenarioCount} onScenarioTap={onScenarioTap} />
      <div style={{ padding: '14px 16px 24px' }}>
        {/* Hero */}
        <div style={{ marginBottom: 14 }}>
          <div style={{
            fontFamily: 'Poppins, sans-serif', fontSize: 10, color: T.teal,
            letterSpacing: '0.14em', textTransform: 'uppercase', fontWeight: 700, marginBottom: 6,
          }}>{item.opCategory}</div>
          <h1 style={{
            fontFamily: '"Zilla Slab", serif', fontWeight: 600, fontSize: 26,
            color: T.darkBlue, margin: 0, letterSpacing: '-0.015em', lineHeight: 1.05,
          }}>{item.name}</h1>
        </div>

        {/* Score + meta + Contact */}
        <div style={{ display: 'flex', gap: 12, alignItems: 'stretch', marginBottom: 14 }}>
          <ScoreTile score={item.restorationScore} type={item.type} onTap={() => setScoreInfoOpen(true)} />
          <div style={{
            flex: 1, display: 'flex', flexDirection: 'column', justifyContent: 'space-between', gap: 6,
          }}>
            <DeptChip name={item.dept} />
            {item.programOffice && (
              <div style={{
                fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink2,
                fontWeight: 500,
              }}>Program Office · {item.programOffice}</div>
            )}
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 8 }}>
              <button onClick={() => setPriorityInfoOpen(true)} style={{
                padding: '4px 10px 4px 8px', border: `1px solid ${T.ink2}`, color: T.ink2,
                background: 'transparent', cursor: 'pointer',
                fontFamily: 'Poppins, sans-serif', fontSize: 10, fontWeight: 700,
                letterSpacing: '0.06em', textTransform: 'uppercase',
                display: 'inline-flex', alignItems: 'center', gap: 5,
              }}>
                <Info size={11} strokeWidth={2}/>
                Priority {item.priority}
              </button>
              {poc && (
                <button onClick={() => setContactOpen(true)} style={{
                  padding: '4px 10px', background: T.teal, color: '#fff',
                  border: 'none', cursor: 'pointer',
                  fontFamily: 'Poppins, sans-serif', fontSize: 10, fontWeight: 700,
                  letterSpacing: '0.08em', textTransform: 'uppercase',
                  display: 'inline-flex', alignItems: 'center', gap: 5,
                }}>
                  <Phone size={11} strokeWidth={2}/> Contact
                </button>
              )}
            </div>
          </div>
        </div>

        {/* Add to Scenario */}
        <button onClick={toggleScenario} style={{
          width: '100%', padding: '12px', fontFamily: 'Poppins, sans-serif',
          fontSize: 11, fontWeight: 700, letterSpacing: '0.12em', textTransform: 'uppercase',
          background: inScenario ? T.darkBlue : T.teal, color: '#fff',
          border: 'none', cursor: 'pointer', marginBottom: 16,
          display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: 6,
        }}>
          {inScenario ? <><Check size={13}/> In Scenario</> : <><Plus size={13}/> Add to Scenario</>}
        </button>

        {/* Tab strip — adapts to 3 or 4 tabs (Info added for facilities) */}
        <div style={{
          display: 'flex', borderBottom: `1px solid ${T.rule}`, marginBottom: 16,
          overflowX: 'auto', msOverflowStyle: 'none', scrollbarWidth: 'none',
        }}>
          {tabs.map(({ k, label }) => (
            <button key={k} onClick={() => setTab(k)} style={{
              flex: tabs.length <= 3 ? 1 : '0 0 auto',
              padding: tabs.length <= 3 ? '10px 6px' : '10px 14px',
              background: 'transparent', border: 'none',
              borderBottom: tab === k ? `2px solid ${T.darkBlue}` : '2px solid transparent',
              cursor: 'pointer', fontFamily: 'Poppins, sans-serif', fontSize: 10,
              fontWeight: 700, letterSpacing: '0.06em', textTransform: 'uppercase',
              color: tab === k ? T.darkBlue : T.ink3, marginBottom: -1,
              whiteSpace: 'nowrap',
            }}>{label}</button>
          ))}
        </div>

        {/* OVERVIEW TAB
            Mobile: single column, all four sections stacked.
            Desktop: two columns. Left = Description + Impacts.
                     Right = Downstream + Upstream dependency blocks. */}
        {tab === 'overview' && (
          <div style={twoColGrid}>
            {/* Left column (or top stack on mobile): textual content */}
            <div>
              <SectionLabel>Description</SectionLabel>
              <p style={{
                fontFamily: 'Poppins, sans-serif', fontSize: 13, lineHeight: 1.55,
                color: T.ink, fontWeight: 400, margin: '0 0 22px 0',
              }}>{item.description}</p>

              <SectionLabel accent>Impacts from Disruption</SectionLabel>
              <p style={{
                fontFamily: 'Poppins, sans-serif', fontSize: 13, lineHeight: 1.6,
                color: T.ink, fontWeight: 400, margin: '0 0 24px 0',
              }}>{item.impacts}</p>
            </div>

            {/* Right column (or bottom stack on mobile): dependency blocks */}
            <div>
              <div onClick={onOpenDeps} style={{
                cursor: 'pointer', marginBottom: 10, border: `1px solid ${T.darkBlue}`,
              }}>
                <div style={{
                  background: T.darkBlue, color: '#fff',
                  padding: '10px 14px',
                  fontFamily: '"Zilla Slab", serif', fontSize: 13, fontWeight: 600,
                  letterSpacing: '0.02em',
                  display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                }}>
                  <span style={{ display: 'inline-flex', alignItems: 'center', gap: 6 }}>
                    <ArrowDown size={13}/>
                    Downstream Dependencies
                  </span>
                  <ChevronRight size={14}/>
                </div>
                <div style={{
                  display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)',
                  background: T.darkBlue, gap: 1,
                }}>
                  {[
                    { label: 'Direct',   value: item.direct },
                    { label: 'Indirect', value: item.indirect },
                    { label: 'Total',    value: item.total },
                  ].map(({ label, value }) => (
                    <div key={label} style={{
                      background: T.surfaceAlt, padding: '14px 10px', textAlign: 'center',
                    }}>
                      <div style={{
                        fontFamily: '"Zilla Slab", serif', fontSize: 26, fontWeight: 700,
                        color: T.darkBlue, lineHeight: 1, letterSpacing: '-0.02em',
                      }}>{value}</div>
                      <div style={{
                        fontFamily: 'Poppins, sans-serif', fontSize: 9, color: T.ink2,
                        letterSpacing: '0.12em', textTransform: 'uppercase', fontWeight: 600,
                        marginTop: 6,
                      }}>{label}</div>
                    </div>
                  ))}
                </div>
              </div>

              <div onClick={onOpenDeps} style={{
                cursor: 'pointer', marginBottom: 10, border: `1px solid ${T.darkBlue}`,
              }}>
                <div style={{
                  background: T.darkBlue, color: '#fff',
                  padding: '10px 14px',
                  fontFamily: '"Zilla Slab", serif', fontSize: 13, fontWeight: 600,
                  letterSpacing: '0.02em',
                  display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                }}>
                  <span style={{ display: 'inline-flex', alignItems: 'center', gap: 6 }}>
                    <ArrowUp size={13}/>
                    Upstream Dependencies
                  </span>
                  <ChevronRight size={14}/>
                </div>
                <div style={{ background: T.surfaceAlt, padding: '14px 10px', textAlign: 'center' }}>
                  <div style={{
                    fontFamily: '"Zilla Slab", serif', fontSize: 30, fontWeight: 700,
                    color: T.darkBlue, lineHeight: 1, letterSpacing: '-0.02em',
                  }}>{item.upstream.length}</div>
                  <div style={{
                    fontFamily: 'Poppins, sans-serif', fontSize: 9, color: T.ink2,
                    letterSpacing: '0.12em', textTransform: 'uppercase', fontWeight: 600,
                    marginTop: 6,
                  }}>Total</div>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* CRITICAL QUESTIONS TAB
            Mobile: just the per-asset Critical Questions (falls back to the
            global CRITICAL_QUESTIONS for assets without their own list).
            Desktop: two columns. Left = Critical Questions. Right = the
            same Short-Term content as the Short-Term tab, so leaders can
            read questions and answers side-by-side. */}
        {tab === 'questions' && (
          <div style={twoColGrid}>
            <div>
              <div style={{
                fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink3,
                fontStyle: 'italic', margin: '0 0 12px 0', fontWeight: 400, lineHeight: 1.4,
              }}>Ground situational awareness before committing to action.</div>
              <ol style={{ listStyle: 'none', padding: 0, margin: 0 }}>
                {((item.criticalQuestions && item.criticalQuestions.length)
                    ? item.criticalQuestions
                    : CRITICAL_QUESTIONS).map((q, i) => (
                  <li key={i} style={{
                    display: 'flex', gap: 10, padding: '8px 0',
                    borderBottom: `1px solid ${T.ruleSoft}`,
                    alignItems: 'flex-start',
                  }}>
                    <div style={{
                      fontFamily: '"Zilla Slab", serif', fontSize: 18, fontWeight: 700,
                      color: T.teal, letterSpacing: '-0.02em', lineHeight: 1.1, minWidth: 26,
                      paddingTop: 1,
                    }}>{String(i + 1).padStart(2, '0')}</div>
                    <div style={{
                      fontFamily: 'Poppins, sans-serif', fontSize: 12, lineHeight: 1.4,
                      color: T.ink, fontWeight: 400,
                    }}>{q}</div>
                  </li>
                ))}
              </ol>
            </div>
            {/* Right column: Short-Term content (desktop only). Empty wrapper
                on mobile would leave a phantom grid cell, so we omit the
                element entirely. */}
            {isDesktop && (
              <div>{shortTermBlock}</div>
            )}
          </div>
        )}

        {/* SHORT-TERM TAB
            Phases sourced from process_details.csv Phase column ("First 30
            minutes", "First 2 hours", "First 24 hours"). Rendered identically
            at both breakpoints; the same JSX block is also referenced from
            the Critical Questions tab's right column on desktop. */}
        {tab === 'short-term' && shortTermBlock}

        {/* INFO TAB — Facilities only */}
        {tab === 'info' && isFacility && (
          <div>
            <SectionLabel>Address</SectionLabel>
            <div style={{
              padding: '12px 14px', background: T.surfaceAlt, border: `1px solid ${T.lightTeal}`,
              marginBottom: 16, display: 'flex', gap: 12, alignItems: 'flex-start',
            }}>
              <MapPin size={18} color={T.teal} strokeWidth={2} style={{ flexShrink: 0, marginTop: 2 }}/>
              <div style={{
                fontFamily: 'Poppins, sans-serif', fontSize: 13, color: T.ink,
                fontWeight: 500, lineHeight: 1.45,
              }}>
                {item.address && <div>{item.address}</div>}
                {(item.city || item.state || item.zip) && (
                  <div style={{ color: T.ink2, fontWeight: 400 }}>
                    {[item.city, item.state, item.zip].filter(Boolean).join(', ').replace(/,\s*$/, '')}
                  </div>
                )}
                {!item.address && (
                  <div style={{ color: T.ink3, fontStyle: 'italic' }}>Address not on file</div>
                )}
              </div>
            </div>

            <SectionLabel>Phone</SectionLabel>
            {item.phone ? (
              <a href={`tel:${item.phone}`} style={{
                display: 'flex', gap: 12, alignItems: 'center',
                padding: '12px 14px', background: T.surfaceAlt, border: `1px solid ${T.lightTeal}`,
                marginBottom: 16, color: T.darkBlue, textDecoration: 'none',
              }}>
                <Phone size={18} color={T.teal} strokeWidth={2}/>
                <div style={{
                  fontFamily: '"Zilla Slab", serif', fontSize: 16, fontWeight: 600,
                  color: T.darkBlue, letterSpacing: '0',
                }}>{item.phone}</div>
                <div style={{ marginLeft: 'auto' }}>
                  <span style={{
                    fontFamily: 'Poppins, sans-serif', fontSize: 9, color: T.teal,
                    letterSpacing: '0.1em', textTransform: 'uppercase', fontWeight: 700,
                  }}>Tap to Call</span>
                </div>
              </a>
            ) : (
              <div style={{
                padding: '12px 14px', background: T.surfaceAlt, border: `1px solid ${T.rule}`,
                marginBottom: 16, color: T.ink3, fontStyle: 'italic',
                fontFamily: 'Poppins, sans-serif', fontSize: 13,
              }}>Phone not on file</div>
            )}

            <SectionLabel>Location</SectionLabel>
            {hasMapData ? (
              <>
                <FacilityMap
                  centerLat={item.lat} centerLng={item.lng}
                  currentId={item.id} currentName={item.name}
                  onPinTap={(p) => { if (lookup[p.id]) onOpen(p.id); }}
                />
                <div style={{
                  marginTop: 8, display: 'flex', gap: 6, alignItems: 'center',
                  fontFamily: 'Poppins, sans-serif', fontSize: 10, color: T.ink3,
                  fontWeight: 500, letterSpacing: '0.04em',
                }}>
                  <Navigation size={11} strokeWidth={2}/>
                  <span>{item.lat.toFixed(5)}, {item.lng.toFixed(5)}</span>
                  <span style={{ marginLeft: 'auto', color: T.teal, fontWeight: 700 }}>
                    Tap a pin to view that facility →
                  </span>
                </div>
              </>
            ) : (
              <div style={{
                padding: '20px 14px', background: T.surfaceAlt, border: `1px solid ${T.rule}`,
                color: T.ink3, fontStyle: 'italic', textAlign: 'center',
                fontFamily: 'Poppins, sans-serif', fontSize: 13,
              }}>Location coordinates not available for this facility.</div>
            )}
          </div>
        )}
      </div>

      {/* SCORE INFO SHEET */}
      <Sheet open={scoreInfoOpen} onClose={() => setScoreInfoOpen(false)} title="Restoration Score">
        <div style={{ display: 'flex', alignItems: 'flex-start', gap: 14, marginBottom: 16 }}>
          <ScoreTile score={item.restorationScore} type={item.type} />
          <div style={{ flex: 1 }}>
            <div style={{
              fontFamily: '"Zilla Slab", serif', fontSize: 16, fontWeight: 600,
              color: T.darkBlue, marginBottom: 4,
            }}>{item.name}</div>
            <div style={{ fontFamily: 'Poppins, sans-serif', fontSize: 12, color: T.ink2 }}>
              {band(item.restorationScore, item.type).label} priority for restoration
            </div>
          </div>
        </div>
        <p style={{
          fontFamily: 'Poppins, sans-serif', fontSize: 13, color: T.ink, lineHeight: 1.55, margin: 0,
        }}>
          Operational Category, Priority, and Restoration Score are used when processes or systems are
          disrupted to help guide allocation of effort and resources. The Restoration Score combines
          multiple factors, including operational category, priority within the category, and the
          number of downstream dependencies. <strong>In general, processes or systems with a higher
          Restoration Score will be addressed first.</strong>
        </p>
        <div style={{
          marginTop: 16, padding: 12, background: T.surfaceAlt,
          fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink2, lineHeight: 1.5,
        }}>
          Bands are calculated within each asset type (Process, System, Facility) so a CRITICAL
          process is comparable to a CRITICAL system even though raw score ranges differ.
        </div>
      </Sheet>

      {/* PRIORITY INFO SHEET */}
      <Sheet open={priorityInfoOpen} onClose={() => setPriorityInfoOpen(false)} title="Priority">
        <div style={{
          fontFamily: '"Zilla Slab", serif', fontSize: 32, fontWeight: 700,
          color: T.darkBlue, marginBottom: 4, letterSpacing: '-0.02em',
        }}>Priority {item.priority}</div>
        <div style={{
          fontFamily: 'Poppins, sans-serif', fontSize: 12, color: T.teal,
          letterSpacing: '0.1em', textTransform: 'uppercase', fontWeight: 700, marginBottom: 16,
        }}>{item.opCategory}</div>
        <p style={{
          fontFamily: 'Poppins, sans-serif', fontSize: 13, color: T.ink, lineHeight: 1.55, margin: '0 0 14px 0',
        }}>
          Operational Category, Priority, and Restoration Score are used when processes or systems are
          disrupted to help guide allocation of effort and resources.
        </p>
        <div style={{
          fontFamily: 'Poppins, sans-serif', fontSize: 11, fontWeight: 600,
          color: T.ink3, letterSpacing: '0.12em', textTransform: 'uppercase', marginBottom: 8,
        }}>Operational Categories</div>
        {(DST_CONFIG.opCategoryLegend || [
          { n: 1, l: 'Life Safety' },
          { n: 2, l: 'Critical Operations' },
          { n: 3, l: 'Critical Admin' },
          { n: 4, l: 'Other' },
        ]).map(({ n, l }) => (
          <div key={n} style={{
            display: 'flex', gap: 12, padding: '8px 0',
            borderBottom: `1px solid ${T.ruleSoft}`, alignItems: 'baseline',
          }}>
            <span style={{
              fontFamily: '"Zilla Slab", serif', fontSize: 16, fontWeight: 700,
              color: T.teal, minWidth: 24,
            }}>{n}</span>
            <span style={{
              fontFamily: 'Poppins, sans-serif', fontSize: 13, color: T.ink, fontWeight: 500,
            }}>{l}</span>
          </div>
        ))}
        <div style={{
          marginTop: 16, padding: 12, background: T.surfaceAlt,
          fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink2, lineHeight: 1.5,
        }}>
          Priority is the rank order <em>within</em> the operational category. Lower numbers are addressed first.
        </div>
      </Sheet>

      {/* CONTACT SHEET */}
      <Sheet open={contactOpen} onClose={() => setContactOpen(false)} title="Department Contact">
        {poc && (
          <>
            <div style={{
              fontFamily: 'Poppins, sans-serif', fontSize: 10, color: T.ink3,
              letterSpacing: '0.1em', textTransform: 'uppercase', fontWeight: 600, marginBottom: 4,
            }}>{item.dept}</div>
            <div style={{
              fontFamily: '"Zilla Slab", serif', fontSize: 22, fontWeight: 600,
              color: T.darkBlue, letterSpacing: '-0.01em', marginBottom: 4,
            }}>{poc.name}</div>
            <div style={{
              fontFamily: 'Poppins, sans-serif', fontSize: 13, color: T.ink2,
              fontWeight: 500, marginBottom: 18,
            }}>{poc.title}</div>

            <a href={`tel:${poc.phone}`} style={{
              display: 'flex', alignItems: 'center', gap: 12, padding: '12px 14px',
              background: T.surfaceAlt, color: T.darkBlue, textDecoration: 'none',
              marginBottom: 8, border: `1px solid ${T.lightTeal}`,
            }}>
              <Phone size={16} color={T.teal} strokeWidth={2}/>
              <div>
                <div style={{
                  fontFamily: 'Poppins, sans-serif', fontSize: 9, color: T.ink3,
                  letterSpacing: '0.1em', textTransform: 'uppercase', fontWeight: 600,
                }}>Phone</div>
                <div style={{
                  fontFamily: '"Zilla Slab", serif', fontSize: 16, fontWeight: 600,
                  color: T.darkBlue, letterSpacing: '0',
                }}>{poc.phone}</div>
              </div>
            </a>

            <a href={`mailto:${poc.email}`} style={{
              display: 'flex', alignItems: 'center', gap: 12, padding: '12px 14px',
              background: T.surfaceAlt, color: T.darkBlue, textDecoration: 'none',
              border: `1px solid ${T.lightTeal}`,
            }}>
              <Mail size={16} color={T.teal} strokeWidth={2}/>
              <div>
                <div style={{
                  fontFamily: 'Poppins, sans-serif', fontSize: 9, color: T.ink3,
                  letterSpacing: '0.1em', textTransform: 'uppercase', fontWeight: 600,
                }}>Email</div>
                <div style={{
                  fontFamily: 'Poppins, sans-serif', fontSize: 14, fontWeight: 500,
                  color: T.darkBlue, wordBreak: 'break-all',
                }}>{poc.email}</div>
              </div>
            </a>

            <div style={{
              marginTop: 16, padding: 12, background: T.bgAlt, border: `1px dashed ${T.rule}`,
              fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink2, lineHeight: 1.5,
            }}>
              {DST_CONFIG.copy.contactsSourceNote}
            </div>
          </>
        )}
      </Sheet>
      <BottomNav onPrevious={onBack} onHome={onHome} />
    </>
  );
}

const SectionLabel = ({ children, accent }) => (
  <div style={{
    fontFamily: 'Poppins, sans-serif', fontSize: 10, fontWeight: 700,
    letterSpacing: '0.16em', textTransform: 'uppercase',
    color: accent ? T.teal : T.ink3,
    marginBottom: 10, paddingBottom: 5,
    borderBottom: `1px solid ${accent ? T.teal : T.rule}`,
  }}>{children}</div>
);

/* ============================================================================
   MAPBOX MAP (Sprint 2) — Real interactive basemap via Mapbox GL JS

   A single reusable map component used by both the full-screen map
   (PortMapScreen) and the inline facility mini-map (FacilityMap). It renders
   real Mapbox tiles with a marker per facility, auto-fits to the markers,
   and (in full mode) offers a Streets/Satellite style toggle.

   Props:
     facilities   - array of facility records with lat/lng to place as markers
     currentId    - optional: a facility to emphasize and center on (mini-map)
     onMarkerTap  - callback(facility) when a marker is tapped
     height       - CSS height of the map container
     interactive  - whether pan/zoom is enabled (false for static mini-maps)
     showStyleToggle - whether to render the Streets/Satellite layers button
     fitToCurrentOnly - mini-map mode: tight zoom around currentId only

   The Mapbox token and style URLs come from dst.config.js (the `mapbox`
   section). If the token is empty, callers should render the
   <MapNeedsToken/> placeholder instead of this component.
   ============================================================================ */

const MAPBOX_CFG = DST_CONFIG.mapbox || {};

function MapboxMap({
  facilities,
  currentId = null,
  onMarkerTap,
  height = 480,
  interactive = true,
  showStyleToggle = true,
  showWeather = false,
  showSpatialSelect = false,
  scenario = [],
  onAddFacilities,
  onAddGeometry,
  fitToCurrentOnly = false,
}) {
  const isDesktop = useIsDesktop();
  const containerRef = useRef(null);
  const mapRef = useRef(null);
  const markersRef = useRef([]);
  const [styleKey, setStyleKey] = useState(MAPBOX_CFG.defaultStyle || 'streets');
  const [styleMenuOpen, setStyleMenuOpen] = useState(false);

  // --- Radar (weather) state ------------------------------------------------
  // radarOn: whether the radar overlay + controls are showing.
  // frames: array of epoch-ms timestamps spanning the service's window.
  // frameIdx: which frame is currently displayed.
  // playing: whether the loop is auto-advancing.
  const RADAR_CFG = (DST_CONFIG.weather && DST_CONFIG.weather.radar) || {};
  const radarEnabled = showWeather && !!RADAR_CFG.enabled;
  const [radarOn, setRadarOn] = useState(false);
  const [frames, setFrames] = useState([]);
  const [frameIdx, setFrameIdx] = useState(0);
  const [playing, setPlaying] = useState(false);
  const [radarLoading, setRadarLoading] = useState(false);
  const playTimerRef = useRef(null);
  const refreshTimerRef = useRef(null);
  // Tracks the per-frame layer/source ids currently added to the map, so the
  // animation can flip visibility between them without refetching tiles.
  const radarLayersRef = useRef([]);

  // --- Alerts (NWS watch/warning polygons) state ---------------------------
  const ALERTS_CFG = (DST_CONFIG.weather && DST_CONFIG.weather.alerts) || {};
  const alertsEnabled = showWeather && !!ALERTS_CFG.enabled;
  const [alertsOn, setAlertsOn] = useState(!!ALERTS_CFG.defaultOn);
  const [alerts, setAlerts] = useState([]);          // filtered alert features
  const alertsRefreshRef = useRef(null);
  // Mirror of `alerts` so the once-registered map click handler always reads
  // the current features without re-registering on every data change.
  const alertsDataRef = useRef([]);

  // --- Spatial selection (draw a radius or polygon, find facilities inside) --
  // drawMode:  whether draw mode is armed at all.
  // shapeMode: 'radius' | 'polygon' — which drawing tool is active.
  // selCenter / selRadiusMi: radius-mode circle (center + miles).
  // polyPts:   polygon-mode vertices, array of {lat,lng}, while building/locked.
  // polyClosed: whether the polygon has been closed (locked).
  // selChecked: which found facilities are checked for adding.
  const [drawMode, setDrawMode] = useState(false);
  const [shapeMode, setShapeMode] = useState('radius');   // 'radius' | 'polygon'
  const [selCenter, setSelCenter] = useState(null);
  const [selRadiusMi, setSelRadiusMi] = useState(0);
  const [polyPts, setPolyPts] = useState([]);
  const [polyClosed, setPolyClosed] = useState(false);
  const [selChecked, setSelChecked] = useState({});   // {facilityId: true}
  const [panelExpanded, setPanelExpanded] = useState(false);  // mobile sheet expand
  const selDragRef = useRef(false);
  const selCenterRef = useRef(null);     // mirror for map event handlers
  const shapeModeRef = useRef('radius'); // mirror for map event handlers
  const polyPtsRef = useRef([]);         // mirror for map event handlers
  const polyClosedRef = useRef(false);

  const styleUrls = MAPBOX_CFG.styles || {
    streets:   'mapbox://styles/mapbox/streets-v12',
    satellite: 'mapbox://styles/mapbox/satellite-streets-v12',
  };

  // Facilities that actually have coordinates. Guards against bad/missing data.
  const pins = useMemo(
    () => (facilities || []).filter(f => typeof f.lat === 'number' && typeof f.lng === 'number'),
    [facilities]
  );

  // Initialize the map once on mount.
  useEffect(() => {
    if (!containerRef.current || mapRef.current) return;
    if (!MAPBOX_CFG.token) return;          // caller should show placeholder

    mapboxgl.accessToken = MAPBOX_CFG.token;

    const map = new mapboxgl.Map({
      container: containerRef.current,
      style: styleUrls[styleKey] || styleUrls.streets,
      center: [pins[0]?.lng ?? 0, pins[0]?.lat ?? 0],
      zoom: 11,
      interactive,
      attributionControl: true,
    });
    mapRef.current = map;

    if (interactive) {
      map.addControl(new mapboxgl.NavigationControl({ showCompass: false }), 'top-left');
    }

    map.on('load', () => {
      addMarkers(map);
      fitToPins(map);
      // Register alert polygon tap once. Reads current features from the ref.
      // Tapping a polygon opens a Mapbox popup at the tap point with the alert
      // details (the weather-app pattern), rather than a separate card.
      map.on('click', ALERTS_FILL, (e) => {
        const idx = e.features?.[0]?.properties?.idx;
        const feats = alertsDataRef.current;
        const p = (idx != null && feats[idx]) ? feats[idx].properties : null;
        if (!p) return;
        const sev = [p.severity, p.certainty, p.urgency].filter(Boolean).join(' · ');
        const until = p.expires
          ? new Date(p.expires).toLocaleString([], { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' })
          : '';
        const esc = (s) => (s || '').replace(/[&<>"]/g, c => ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;' }[c]));
        const html =
          `<div style="font-family: Poppins, sans-serif; max-width: 260px;">` +
            `<div style="font-family: 'Zilla Slab', serif; font-size: 15px; font-weight: 700; color: #B91C1C; line-height: 1.15; margin-bottom: 4px;">${esc(p.event)}</div>` +
            (sev ? `<div style="font-size: 9px; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; color: #64748B; margin-bottom: 6px;">${esc(sev)}</div>` : '') +
            (p.areaDesc ? `<div style="font-size: 11px; color: #334155; line-height: 1.4; margin-bottom: 6px;">${esc(p.areaDesc)}</div>` : '') +
            (until ? `<div style="font-size: 11px; font-weight: 600; color: #1E293B; margin-bottom: 6px;">In effect until ${esc(until)}</div>` : '') +
            (p.headline ? `<div style="font-size: 11px; color: #475569; line-height: 1.45; padding-top: 6px; border-top: 1px solid #E2E8F0;">${esc(p.headline)}</div>` : '') +
          `</div>`;
        new mapboxgl.Popup({ offset: 8, maxWidth: '280px' })
          .setLngLat(e.lngLat)
          .setHTML(html)
          .addTo(map);
      });
      map.on('mouseenter', ALERTS_FILL, () => { map.getCanvas().style.cursor = 'pointer'; });
      map.on('mouseleave', ALERTS_FILL, () => { map.getCanvas().style.cursor = ''; });
    });

    return () => {
      markersRef.current.forEach(m => m.remove());
      markersRef.current = [];
      map.remove();
      mapRef.current = null;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Re-add markers and re-fit when the pin set changes.
  useEffect(() => {
    const map = mapRef.current;
    if (!map || !map.isStyleLoaded()) return;
    addMarkers(map);
    fitToPins(map);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [pins, currentId]);

  // Swap the basemap style when the toggle changes. Markers are HTML elements
  // (Mapbox Marker), which survive a setStyle call, so we don't re-add them.
  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;
    map.setStyle(styleUrls[styleKey] || styleUrls.streets);
    // A style change drops custom sources/layers (radar frames included).
    // Rebuild the whole radar frame stack once the new style loads, if on.
    const reAddRadar = () => { if (radarOn && frames.length) buildRadarFrames(map, frames, frameIdx); };
    map.once('styledata', reAddRadar);
    const reAddAlerts = () => { if (alertsOn && alerts.length) drawAlerts(map, alerts); };
    map.once('styledata', reAddAlerts);
    const reAddSel = () => {
      if (shapeModeRef.current === 'radius' && selCenter && selRadiusMi > 0) drawSelection(map);
      else if (shapeModeRef.current === 'polygon' && polyClosedRef.current && polyPtsRef.current.length >= 3) drawPolygonPreview(map, polyPtsRef.current, null, true);
    };
    map.once('styledata', reAddSel);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [styleKey]);

  // -------------------------------------------------------------------------
  // Radar frames. Rather than guessing timestamps (which mostly miss NOAA's
  // real data ticks and return blank 451-byte tiles), query the ImageServer's
  // raster catalog for the actual validtimes it currently holds, and animate
  // exactly those. Returns a promise of an ascending array of epoch-ms times.
  // Falls back to a single "latest" frame if the query fails.
  // -------------------------------------------------------------------------
  function queryEndpointFromWms() {
    // Derive the REST /query URL from the configured WMS base by swapping the
    // service path. e.g. .../services/.../ImageServer/WMSServer -> .../query
    // via the /rest/ services directory.
    const wms = RADAR_CFG.wmsBase || '';
    // wms looks like: https://host/eventdriven/services/radar/<svc>/ImageServer/WMSServer
    // REST query is:  https://host/eventdriven/rest/services/radar/<svc>/ImageServer/query
    return wms
      .replace('/services/', '/rest/services/')
      .replace(/\/WMSServer\/?$/, '/query');
  }

  async function fetchFrames() {
    const windowHours = RADAR_CFG.windowHours || 4;
    const now = Date.now();
    const since = now - windowHours * 60 * 60 * 1000;
    // Time-aware ImageServer layers reject a raw epoch compared against a date
    // field in `where` (yields HTTP 400). The correct approach is where=1=1
    // plus the dedicated `time` parameter as a start,end epoch-ms range.
    const url = queryEndpointFromWms()
      + '?where=' + encodeURIComponent('1=1')
      + '&time=' + `${since},${now}`
      + '&outFields=idp_validtime'
      + '&returnGeometry=false'
      + '&returnIdsOnly=false'
      + '&orderByFields=' + encodeURIComponent('idp_validtime ASC')
      + '&f=json';
    try {
      const resp = await fetch(url);
      const data = await resp.json();
      if (data && data.error) return [];   // server-side query error -> fallback
      const times = (data.features || [])
        .map(f => f.attributes && f.attributes.idp_validtime)
        .filter(t => typeof t === 'number')
        .sort((a, b) => a - b);
      const uniq = [...new Set(times)].filter(t => t >= since);
      if (!uniq.length) return [];

      // The MRMS mosaic reports many per-site validtimes a few seconds apart,
      // clustered around each ~5-minute data cycle. Collapse each cluster to a
      // single representative frame so the animation is evenly spaced and we
      // don't preload dozens of near-duplicate tiles. Anything within
      // clusterGapMs of the previous kept frame is treated as the same cycle.
      const clusterGapMs = 150 * 1000;   // 2.5 min: safely between 5-min cycles
      const collapsed = [];
      for (const t of uniq) {
        if (!collapsed.length || t - collapsed[collapsed.length - 1] >= clusterGapMs) {
          collapsed.push(t);
        } else {
          // keep the latest time within the cluster (freshest mosaic)
          collapsed[collapsed.length - 1] = t;
        }
      }
      if (collapsed.length) return collapsed;
    } catch (e) {
      // fall through to single-latest fallback
    }
    return [];   // empty signals "use latest-only" fallback
  }

  // Build a WMS GetMap tile URL template for a given frame time (epoch ms).
  // Mapbox substitutes {bbox-epsg-3857} per tile. TIME is ISO-8601 UTC.
  // isLatest: when true, TIME is omitted so the service returns its most
  // recent image (the most reliable way to guarantee a current frame).
  function radarTileUrl(timeMs, isLatest = false) {
    const base = RADAR_CFG.wmsBase;
    const layer = RADAR_CFG.layer || 'radar_base_reflectivity_time';
    const params = [
      'service=WMS',
      'request=GetMap',
      'version=1.3.0',
      `layers=${encodeURIComponent(layer)}`,
      'styles=',
      'format=image/png',
      'transparent=true',
      'crs=EPSG:3857',
      'width=256',
      'height=256',
      'bbox={bbox-epsg-3857}',
    ];
    if (!isLatest && timeMs) {
      params.push(`time=${encodeURIComponent(new Date(timeMs).toISOString())}`);
    }
    return `${base}?${params.join('&')}`;
  }

  const radarSrcId = (i) => `dst-radar-src-${i}`;
  const radarLyrId = (i) => `dst-radar-lyr-${i}`;

  // Remove every radar frame source/layer currently on the map.
  function clearRadarFrames(map) {
    if (!map) return;
    radarLayersRef.current.forEach(({ src, lyr }) => {
      if (map.getLayer(lyr)) map.removeLayer(lyr);
      if (map.getSource(src)) map.removeSource(src);
    });
    radarLayersRef.current = [];
  }

  // Build one persistent source+layer per frame, all hidden except activeIdx.
  // Because every frame stays added, animating later is just a visibility
  // flip (instant, no tile refetch). Tiles load once and Mapbox caches them.
  //
  // Frame times come from NOAA's actual catalog (fetchFrames), so each TIME
  // matches real data and returns echoes rather than a blank tile. When
  // latestOnly is true we have a single synthetic frame: omit TIME so the
  // service returns its most-recent image.
  function buildRadarFrames(map, frameList, activeIdx, latestOnly = false) {
    if (!map || !map.isStyleLoaded() || !frameList.length) return;
    clearRadarFrames(map);

    const opacity = RADAR_CFG.opacity != null ? RADAR_CFG.opacity : 0.65;
    const newLayers = [];

    frameList.forEach((t, i) => {
      const src = radarSrcId(i);
      const lyr = radarLyrId(i);
      // In latest-only fallback, omit TIME (isLatest=true). Otherwise request
      // the exact validtime for this frame.
      map.addSource(src, {
        type: 'raster',
        tiles: [radarTileUrl(t, latestOnly)],
        tileSize: 256,
        attribution: 'Radar: NOAA/NWS',
      });
      map.addLayer({
        id: lyr,
        type: 'raster',
        source: src,
        layout: { visibility: i === activeIdx ? 'visible' : 'none' },
        paint: { 'raster-opacity': opacity },
      });
      newLayers.push({ src, lyr });
    });
    radarLayersRef.current = newLayers;
  }

  // Show exactly one frame by flipping visibility. Instant; no network.
  function showRadarFrame(map, idx) {
    if (!map) return;
    radarLayersRef.current.forEach(({ lyr }, i) => {
      if (map.getLayer(lyr)) {
        map.setLayoutProperty(lyr, 'visibility', i === idx ? 'visible' : 'none');
      }
    });
  }

  // Toggle radar on/off. On enable: query NOAA for the actual frame validtimes,
  // build the persistent frame stack from them, show a loading gate until tiles
  // are in, then play from the latest.
  async function toggleRadar() {
    const map = mapRef.current;
    if (!map) return;
    if (radarOn) {
      setPlaying(false);
      setRadarLoading(false);
      clearRadarFrames(map);
      setRadarOn(false);
      return;
    }

    // Enabling: show the loading gate immediately, then fetch real frame times.
    setRadarOn(true);
    setRadarLoading(true);
    setPlaying(false);

    const real = await fetchFrames();
    // If the query failed/returned nothing, fall back to a single latest frame
    // (TIME omitted), which reliably renders the most recent radar image.
    const f = real.length ? real : [Date.now()];
    const startIdx = f.length - 1;
    const latestOnly = real.length === 0;

    setFrames(f);
    setFrameIdx(startIdx);
    buildRadarFrames(map, f, startIdx, latestOnly);

    const startPlaying = () => {
      setRadarLoading(false);
      setPlaying(f.length > 1);          // only animate if we have multiple frames
      map.off('idle', startPlaying);
    };
    map.once('idle', startPlaying);
    setTimeout(() => {
      map.off('idle', startPlaying);
      setRadarLoading(false);
      setPlaying(f.length > 1);
    }, 6000);
  }

  // When the displayed frame index changes while radar is on, flip visibility.
  useEffect(() => {
    const map = mapRef.current;
    if (!map || !radarOn || !radarLayersRef.current.length) return;
    showRadarFrame(map, frameIdx);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [frameIdx, radarOn]);

  // Playback loop: advance frameIdx on an interval while playing (and not
  // still loading). Visibility flips are instant so this stays smooth.
  useEffect(() => {
    if (!playing || !radarOn || radarLoading || frames.length < 2) return;
    playTimerRef.current = setInterval(() => {
      setFrameIdx(i => (i + 1) % frames.length);
    }, RADAR_CFG.frameMs || 600);
    return () => clearInterval(playTimerRef.current);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [playing, radarOn, radarLoading, frames]);

  // Periodically refresh the frame list so a long-open map stays current with
  // NOAA's newest data (the window keeps moving). Re-queries real validtimes
  // and rebuilds the frame stack.
  useEffect(() => {
    if (!radarOn) return;
    const cadence = (RADAR_CFG.stepMinutes || 10) * 60 * 1000;
    refreshTimerRef.current = setInterval(async () => {
      const map = mapRef.current;
      if (!map) return;
      const real = await fetchFrames();
      if (!real.length) return;          // keep current frames if query fails
      const parkedAtLatest = frameIdx >= frames.length - 1;
      const newIdx = parkedAtLatest ? real.length - 1 : Math.min(frameIdx, real.length - 1);
      setFrames(real);
      setFrameIdx(newIdx);
      buildRadarFrames(map, real, newIdx, false);
    }, cadence);
    return () => clearInterval(refreshTimerRef.current);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [radarOn, frames.length, frameIdx]);

  // Format a frame timestamp for the readout (local time, HH:MM).
  function frameLabel(timeMs) {
    if (!timeMs) return '';
    return new Date(timeMs).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  }

  // -------------------------------------------------------------------------
  // ALERTS — fetch active NWS watch/warning polygons for the facility area,
  // keep only the configured polygon-bearing warning events, and draw them as
  // GeoJSON fill+line layers. Tapping a polygon selects it for a detail card.
  // -------------------------------------------------------------------------
  const ALERTS_SRC = 'dst-alerts-src';
  const ALERTS_FILL = 'dst-alerts-fill';
  const ALERTS_LINE = 'dst-alerts-line';

  function alertCentroid() {
    const valid = pins.filter(p => typeof p.lat === 'number' && typeof p.lng === 'number');
    if (!valid.length) return null;
    const lat = valid.reduce((s, p) => s + p.lat, 0) / valid.length;
    const lng = valid.reduce((s, p) => s + p.lng, 0) / valid.length;
    return { lat: Math.round(lat * 1e4) / 1e4, lng: Math.round(lng * 1e4) / 1e4 };
  }

  // Great-circle distance between two lat/lng points, in miles (haversine).
  function milesBetween(lat1, lng1, lat2, lng2) {
    const R = 3958.8; // earth radius in miles
    const toRad = (d) => (d * Math.PI) / 180;
    const dLat = toRad(lat2 - lat1);
    const dLng = toRad(lng2 - lng1);
    const a = Math.sin(dLat / 2) ** 2 +
      Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLng / 2) ** 2;
    return 2 * R * Math.asin(Math.sqrt(a));
  }

  // Minimum distance (miles) from a point to any vertex of an alert geometry.
  // An approximation: tests the polygon's vertices rather than every edge, which
  // is plenty for a ~25-mile proximity trigger at warning-polygon scale. Also
  // returns 0 if the point is inside the polygon (ray-casting).
  function milesPointToGeometry(lat, lng, geometry) {
    if (!geometry) return Infinity;
    const rings = geometry.type === 'Polygon'
      ? geometry.coordinates
      : geometry.type === 'MultiPolygon'
        ? geometry.coordinates.flat()
        : [];
    let min = Infinity;
    let inside = false;
    for (const ring of rings) {
      // Point-in-polygon (ray cast) on the outer ring(s).
      for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
        const xi = ring[i][0], yi = ring[i][1];
        const xj = ring[j][0], yj = ring[j][1];
        const intersect = ((yi > lat) !== (yj > lat)) &&
          (lng < ((xj - xi) * (lat - yi)) / (yj - yi) + xi);
        if (intersect) inside = !inside;
        // Distance to this vertex.
        const d = milesBetween(lat, lng, yi, xi);
        if (d < min) min = d;
      }
    }
    return inside ? 0 : min;
  }

  async function fetchAlerts() {
    const base = ALERTS_CFG.apiBase || 'https://api.weather.gov';
    const events = ALERTS_CFG.events || [];
    const hasPolygon = (f) => f.geometry &&
      (f.geometry.type === 'Polygon' || f.geometry.type === 'MultiPolygon');
    const isWanted = (f) => events.some(ev => (f.properties?.event || '').includes(ev));

    try {
      if (ALERTS_CFG.testMode) {
        // TEST MODE: pull active warnings nationwide (filtered to our events),
        // keep those with polygons, recenter the map on the first one so it's
        // visible. Sandbox demo aid only — disable before the PCCA port.
        const resp = await fetch(`${base}/alerts/active?status=actual&message_type=alert`, {
          headers: { 'Accept': 'application/geo+json' },
        });
        if (!resp.ok) return [];
        const data = await resp.json();
        const matches = (data.features || []).filter(f => hasPolygon(f) && isWanted(f));
        if (matches.length && mapRef.current) {
          const geom = matches[0].geometry;
          const ring = geom.type === 'Polygon' ? geom.coordinates[0] : geom.coordinates[0][0];
          if (ring && ring.length) {
            const lng = ring.reduce((s, c) => s + c[0], 0) / ring.length;
            const lat = ring.reduce((s, c) => s + c[1], 0) / ring.length;
            mapRef.current.easeTo({ center: [lng, lat], zoom: 8, duration: 800 });
          }
        }
        return matches;
      }

      // NORMAL: query the configured area (returns full polygon geometry,
      // which the point query can omit), then keep only qualifying warnings
      // whose polygon comes within proximityMiles of the facility centroid.
      const c = alertCentroid();
      if (!c) return [];
      const area = ALERTS_CFG.area;
      const url = area
        ? `${base}/alerts/active?area=${encodeURIComponent(area)}`
        : `${base}/alerts/active?point=${c.lat},${c.lng}`;
      const resp = await fetch(url, { headers: { 'Accept': 'application/geo+json' } });
      if (!resp.ok) return [];
      const data = await resp.json();
      const radius = ALERTS_CFG.proximityMiles || 25;
      return (data.features || [])
        .filter(f => hasPolygon(f) && isWanted(f))
        .filter(f => milesPointToGeometry(c.lat, c.lng, f.geometry) <= radius);
    } catch (e) {
      return [];
    }
  }

  // Draw (or clear) the alert polygons on the map from the current `alerts`.
  function drawAlerts(map, features) {
    if (!map || !map.isStyleLoaded()) return;
    // Remove prior layers/source.
    if (map.getLayer(ALERTS_LINE)) map.removeLayer(ALERTS_LINE);
    if (map.getLayer(ALERTS_FILL)) map.removeLayer(ALERTS_FILL);
    if (map.getSource(ALERTS_SRC)) map.removeSource(ALERTS_SRC);
    if (!features || !features.length) return;

    const colors = ALERTS_CFG.severityColors || {};
    // Tag each feature with a fill color derived from severity for data-driven
    // styling.
    const fc = {
      type: 'FeatureCollection',
      features: features.map((f, i) => ({
        type: 'Feature',
        id: i,
        geometry: f.geometry,
        properties: {
          color: colors[f.properties?.severity] || colors.Unknown || '#F59E0B',
          idx: i,
        },
      })),
    };

    map.addSource(ALERTS_SRC, { type: 'geojson', data: fc });
    map.addLayer({
      id: ALERTS_FILL,
      type: 'fill',
      source: ALERTS_SRC,
      paint: { 'fill-color': ['get', 'color'], 'fill-opacity': 0.25 },
    });
    map.addLayer({
      id: ALERTS_LINE,
      type: 'line',
      source: ALERTS_SRC,
      paint: { 'line-color': ['get', 'color'], 'line-width': 2 },
    });

    // In test mode (testPoint set), the alert is likely far from the facility
    // view, so fit the map to the alert polygons to make them visible. In
    // normal operation we leave the view fitted to the facilities.
    if (ALERTS_CFG.testPoint) {
      try {
        const b = new mapboxgl.LngLatBounds();
        features.forEach(f => {
          const geom = f.geometry;
          const rings = geom.type === 'MultiPolygon'
            ? geom.coordinates.flat() : geom.coordinates;
          rings.forEach(ring => ring.forEach(([lng, lat]) => b.extend([lng, lat])));
        });
        if (!b.isEmpty()) map.fitBounds(b, { padding: 40, maxZoom: 9, duration: 600 });
      } catch (e) { /* non-fatal */ }
    }
    // Note: tap/hover handlers for ALERTS_FILL are registered once on map load
    // (see the load handler), not here, so repeated redraws don't stack them.
  }

  function clearAlerts(map) {
    if (!map) return;
    if (map.getLayer(ALERTS_LINE)) map.removeLayer(ALERTS_LINE);
    if (map.getLayer(ALERTS_FILL)) map.removeLayer(ALERTS_FILL);
    if (map.getSource(ALERTS_SRC)) map.removeSource(ALERTS_SRC);
  }

  // Load alerts on enable / mount, redraw when they change, refresh on cadence.
  useEffect(() => {
    if (!alertsEnabled) return;
    let cancelled = false;
    const run = async () => {
      const f = await fetchAlerts();
      if (!cancelled) setAlerts(f);
    };
    run();
    const mins = ALERTS_CFG.refreshMinutes || 5;
    alertsRefreshRef.current = setInterval(run, mins * 60 * 1000);
    return () => { cancelled = true; clearInterval(alertsRefreshRef.current); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [alertsEnabled]);

  // Redraw whenever alerts data or the on/off toggle changes.
  useEffect(() => {
    const map = mapRef.current;
    alertsDataRef.current = alerts;     // keep ref current for the click handler
    if (!map) return;
    if (alertsOn && alerts.length) drawAlerts(map, alerts);
    else clearAlerts(map);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [alerts, alertsOn]);

  // -------------------------------------------------------------------------
  // SPATIAL SELECTION — draw a radius circle, find facilities inside it, and
  // let the user pick which to add to the scenario. Reuses milesBetween() for
  // distance; no external geometry library needed. (Polygon/freehand drawing
  // is a planned follow-on; the same in-shape -> facility-set -> add flow will
  // feed from a drawn polygon exactly as it does from this circle.)
  // -------------------------------------------------------------------------
  const SEL_SRC = 'dst-sel-src';
  const SEL_FILL = 'dst-sel-fill';
  const SEL_LINE = 'dst-sel-line';
  // Live-preview layers (pin, tether line, distance label) shown while sizing.
  const SEL_PIN_SRC = 'dst-sel-pin-src';
  const SEL_PIN_LAYER = 'dst-sel-pin-layer';
  const SEL_TETHER_SRC = 'dst-sel-tether-src';
  const SEL_TETHER_LAYER = 'dst-sel-tether-layer';
  const SEL_LABEL_SRC = 'dst-sel-label-src';
  const SEL_LABEL_LAYER = 'dst-sel-label-layer';

  // Build a GeoJSON circle polygon (64 points) around a center at a mile radius.
  function circlePolygon(centerLat, centerLng, radiusMi, steps = 64) {
    if (!centerLat || !radiusMi) return null;
    const coords = [];
    const latRad = (centerLat * Math.PI) / 180;
    // Degrees per mile: latitude ~1/69; longitude scales by cos(lat).
    const dLat = radiusMi / 69.0;
    const dLng = radiusMi / (69.0 * Math.cos(latRad) || 1);
    for (let i = 0; i <= steps; i++) {
      const theta = (i / steps) * 2 * Math.PI;
      coords.push([centerLng + dLng * Math.cos(theta), centerLat + dLat * Math.sin(theta)]);
    }
    return { type: 'Polygon', coordinates: [coords] };
  }

  // Create the preview layers once (idempotent). Empty sources to start.
  function ensurePreviewLayers(map) {
    if (!map || !map.isStyleLoaded()) return;
    const empty = { type: 'FeatureCollection', features: [] };
    if (!map.getSource(SEL_TETHER_SRC)) {
      map.addSource(SEL_TETHER_SRC, { type: 'geojson', data: empty });
      map.addLayer({ id: SEL_TETHER_LAYER, type: 'line', source: SEL_TETHER_SRC,
        paint: { 'line-color': T.teal, 'line-width': 2, 'line-dasharray': [2, 1.5] } });
    }
    if (!map.getSource(SEL_SRC)) {
      map.addSource(SEL_SRC, { type: 'geojson', data: empty });
      map.addLayer({ id: SEL_FILL, type: 'fill', source: SEL_SRC,
        paint: { 'fill-color': T.teal, 'fill-opacity': 0.14 } });
      map.addLayer({ id: SEL_LINE, type: 'line', source: SEL_SRC,
        paint: { 'line-color': T.teal, 'line-width': 2 } });
    }
    if (!map.getSource(SEL_PIN_SRC)) {
      map.addSource(SEL_PIN_SRC, { type: 'geojson', data: empty });
      map.addLayer({ id: SEL_PIN_LAYER, type: 'circle', source: SEL_PIN_SRC,
        paint: { 'circle-radius': 5, 'circle-color': T.teal, 'circle-stroke-color': '#fff', 'circle-stroke-width': 2 } });
    }
    if (!map.getSource(SEL_LABEL_SRC)) {
      map.addSource(SEL_LABEL_SRC, { type: 'geojson', data: empty });
      map.addLayer({ id: SEL_LABEL_LAYER, type: 'symbol', source: SEL_LABEL_SRC,
        layout: {
          'text-field': ['get', 'label'],
          'text-size': 13,
          'text-font': ['DIN Offc Pro Medium', 'Arial Unicode MS Bold'],
          'text-offset': [0, -1.2],
          'text-anchor': 'bottom',
          'text-allow-overlap': true,
        },
        paint: {
          'text-color': T.darkBlue,
          'text-halo-color': '#fff',
          'text-halo-width': 2,
        },
      });
    }
  }

  // Update the live preview (pin + tether + distance label + circle) in place
  // as the cursor moves. Center is {lat,lng}; cursor is a Mapbox LngLat.
  function updatePreview(map, center, cursorLngLat) {
    if (!map || !map.isStyleLoaded() || !center) return;
    ensurePreviewLayers(map);
    const r = milesBetween(center.lat, center.lng, cursorLngLat.lat, cursorLngLat.lng);

    // Pin at center.
    const pinSrc = map.getSource(SEL_PIN_SRC);
    if (pinSrc) pinSrc.setData({ type: 'Feature', geometry: { type: 'Point', coordinates: [center.lng, center.lat] }, properties: {} });

    // Tether line center -> cursor.
    const tSrc = map.getSource(SEL_TETHER_SRC);
    if (tSrc) tSrc.setData({ type: 'Feature', geometry: { type: 'LineString', coordinates: [[center.lng, center.lat], [cursorLngLat.lng, cursorLngLat.lat]] }, properties: {} });

    // Distance label at the cursor.
    const lSrc = map.getSource(SEL_LABEL_SRC);
    if (lSrc) lSrc.setData({ type: 'Feature', geometry: { type: 'Point', coordinates: [cursorLngLat.lng, cursorLngLat.lat] }, properties: { label: `${r.toFixed(1)} mi` } });

    // Growing circle.
    const geom = circlePolygon(center.lat, center.lng, Math.max(0.05, r));
    const cSrc = map.getSource(SEL_SRC);
    if (cSrc && geom) cSrc.setData({ type: 'Feature', geometry: geom, properties: {} });
  }

  // Remove just the moving tether + label (keep the locked circle + pin).
  function clearTether(map) {
    if (!map) return;
    const t = map.getSource(SEL_TETHER_SRC);
    if (t) t.setData({ type: 'FeatureCollection', features: [] });
    const l = map.getSource(SEL_LABEL_SRC);
    if (l) l.setData({ type: 'FeatureCollection', features: [] });
  }

  // Screen-pixel distance between two lng/lat points (for "click near first
  // vertex to close" hit-testing, which should be in screen space, not miles).
  function pixelDist(map, a, b) {
    const pa = map.project([a.lng, a.lat]);
    const pb = map.project([b.lng, b.lat]);
    return Math.hypot(pa.x - pb.x, pa.y - pb.y);
  }

  // Draw the polygon-in-progress preview: vertex dots (pin source), the edges
  // so far plus an optional rubber-band edge to the cursor (tether source), and
  // once closed, a filled polygon (SEL_SRC). All via setData, in place.
  function drawPolygonPreview(map, pts, cursorLngLat, closed) {
    if (!map || !map.isStyleLoaded() || !pts.length) return;
    ensurePreviewLayers(map);

    // Vertex dots.
    const pinSrc = map.getSource(SEL_PIN_SRC);
    if (pinSrc) pinSrc.setData({
      type: 'FeatureCollection',
      features: pts.map(p => ({ type: 'Feature', geometry: { type: 'Point', coordinates: [p.lng, p.lat] }, properties: {} })),
    });

    // Edge line: the path through the vertices, plus a rubber-band segment to
    // the cursor while still open.
    const line = pts.map(p => [p.lng, p.lat]);
    if (!closed && cursorLngLat) line.push([cursorLngLat.lng, cursorLngLat.lat]);
    const tSrc = map.getSource(SEL_TETHER_SRC);
    if (tSrc) tSrc.setData({ type: 'Feature', geometry: { type: 'LineString', coordinates: line }, properties: {} });

    // Filled polygon once closed.
    const cSrc = map.getSource(SEL_SRC);
    if (cSrc) {
      if (closed && pts.length >= 3) {
        const ring = [...pts.map(p => [p.lng, p.lat]), [pts[0].lng, pts[0].lat]];
        cSrc.setData({ type: 'Feature', geometry: { type: 'Polygon', coordinates: [ring] }, properties: {} });
      } else {
        cSrc.setData({ type: 'FeatureCollection', features: [] });
      }
    }
  }

  // Close the polygon: mark closed, fill it, drop the rubber-band, and let the
  // facilities-in-shape query pick up the finished ring.
  function closePolygon(map) {
    const pts = polyPtsRef.current;
    if (pts.length < 3) return;
    polyClosedRef.current = true;
    setPolyClosed(true);
    setPolyPts([...pts]);   // commit to state for the query
    drawPolygonPreview(map, pts, null, true);
  }

  // Ray-cast point-in-polygon test. ring is an array of {lat,lng}.
  function pointInRing(lat, lng, ring) {
    let inside = false;
    for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
      const xi = ring[i].lng, yi = ring[i].lat;
      const xj = ring[j].lng, yj = ring[j].lat;
      const intersect = ((yi > lat) !== (yj > lat)) &&
        (lng < ((xj - xi) * (lat - yi)) / (yj - yi) + xi);
      if (intersect) inside = !inside;
    }
    return inside;
  }

  // Facilities inside the current selection shape (radius circle OR closed
  // polygon), tagged with a display distance, nearest first. This is the single
  // "in-shape -> facility set" query that both tools feed, and the same one a
  // future saved-geometry feature would reuse.
  const facilitiesInShape = useMemo(() => {
    if (shapeMode === 'radius') {
      if (!selCenter || !selRadiusMi) return [];
      return pins
        .map(f => ({ f, d: milesBetween(selCenter.lat, selCenter.lng, f.lat, f.lng) }))
        .filter(x => x.d <= selRadiusMi)
        .sort((a, b) => a.d - b.d)
        .map(x => ({ ...x.f, _distMi: x.d }));
    }
    // polygon
    if (!polyClosed || polyPts.length < 3) return [];
    // Centroid for a display distance.
    const cLat = polyPts.reduce((s, p) => s + p.lat, 0) / polyPts.length;
    const cLng = polyPts.reduce((s, p) => s + p.lng, 0) / polyPts.length;
    return pins
      .filter(f => pointInRing(f.lat, f.lng, polyPts))
      .map(f => ({ ...f, _distMi: milesBetween(cLat, cLng, f.lat, f.lng) }))
      .sort((a, b) => a._distMi - b._distMi);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [shapeMode, selCenter && selCenter.lat, selCenter && selCenter.lng, selRadiusMi, polyClosed, polyPts, pins]);

  // When the found set changes, default every found facility to checked
  // (but keep any the user already unchecked this session).
  useEffect(() => {
    setSelChecked(prev => {
      const next = {};
      facilitiesInShape.forEach(f => {
        next[f.id] = (f.id in prev) ? prev[f.id] : true;
      });
      return next;
    });
    // Start collapsed (summary bar); the user taps to open the list. Reset to
    // collapsed whenever the selection changes so a fresh draw shows the summary.
    setPanelExpanded(false);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [facilitiesInShape]);

  // Draw or update the LOCKED selection circle (after sizing ends). Updates the
  // shared SEL_SRC in place so the picker's circle matches the locked radius.
  function drawSelection(map) {
    if (!map || !map.isStyleLoaded()) return;
    ensurePreviewLayers(map);
    const geom = circlePolygon(selCenter?.lat, selCenter?.lng, selRadiusMi);
    const cSrc = map.getSource(SEL_SRC);
    if (cSrc) cSrc.setData(geom ? { type: 'Feature', geometry: geom, properties: {} } : { type: 'FeatureCollection', features: [] });
    // Keep the center pin visible on the locked circle.
    const pinSrc = map.getSource(SEL_PIN_SRC);
    if (pinSrc && selCenter) pinSrc.setData({ type: 'Feature', geometry: { type: 'Point', coordinates: [selCenter.lng, selCenter.lat] }, properties: {} });
  }

  function clearSelectionLayer(map) {
    if (!map) return;
    [SEL_LINE, SEL_FILL, SEL_PIN_LAYER, SEL_TETHER_LAYER, SEL_LABEL_LAYER].forEach(id => {
      if (map.getLayer(id)) map.removeLayer(id);
    });
    [SEL_SRC, SEL_PIN_SRC, SEL_TETHER_SRC, SEL_LABEL_SRC].forEach(id => {
      if (map.getSource(id)) map.removeSource(id);
    });
  }

  // Reset the whole selection (radius + polygon + checks) and clear drawing.
  function resetSelection() {
    selCenterRef.current = null;
    setSelCenter(null);
    setSelRadiusMi(0);
    polyPtsRef.current = [];
    polyClosedRef.current = false;
    setPolyPts([]);
    setPolyClosed(false);
    selDragRef.current = false;
    setSelChecked({});
    const map = mapRef.current;
    if (map) clearSelectionLayer(map);
  }

  // Toggle draw mode. Turning it off also clears any in-progress selection.
  function toggleDrawMode() {
    setDrawMode(dm => {
      const next = !dm;
      if (!next) resetSelection();
      return next;
    });
  }

  // Switch between radius and polygon tools, clearing any in-progress shape so
  // the two don't visually collide.
  function switchShapeMode(mode) {
    if (mode === shapeMode) return;
    resetSelection();
    shapeModeRef.current = mode;
    setShapeMode(mode);
  }

  // Redraw the LOCKED circle when the locked radius changes. While actively
  // sizing (selDragRef true), the preview is driven imperatively by
  // updatePreview, so this effect must not clear or redraw then. Only acts in
  // radius mode so it never clobbers a polygon drawing.
  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;
    if (shapeMode !== 'radius') return;
    if (selDragRef.current) return;           // sizing in progress; leave preview alone
    if (selCenter && selRadiusMi > 0) drawSelection(map);
    else if (!selCenter) clearSelectionLayer(map);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selCenter && selCenter.lat, selCenter && selCenter.lng, selRadiusMi, shapeMode]);

  // Wire the map interactions for draw mode. Branches by shapeMode.
  //   RADIUS:  click center -> move to size (live tether+label+circle) -> click lock.
  //   POLYGON: click to add each vertex (live rubber-band edge to cursor);
  //            click near the first vertex or double-click to close the shape.
  // Uses refs so the once-registered handlers read live state.
  useEffect(() => {
    const map = mapRef.current;
    if (!map || !drawMode) return;

    const onClick = (e) => {
      if (shapeModeRef.current === 'radius') {
        if (!selCenterRef.current) {
          const c = { lat: e.lngLat.lat, lng: e.lngLat.lng };
          selCenterRef.current = c;
          selDragRef.current = true;
          setSelCenter(c);
          setSelRadiusMi(0);
          updatePreview(map, c, e.lngLat);
        } else if (selDragRef.current) {
          const c = selCenterRef.current;
          const r = Math.max(0.1, milesBetween(c.lat, c.lng, e.lngLat.lat, e.lngLat.lng));
          selDragRef.current = false;
          setSelRadiusMi(r);
          clearTether(map);
        } else {
          const c = { lat: e.lngLat.lat, lng: e.lngLat.lng };
          selCenterRef.current = c;
          selDragRef.current = true;
          setSelCenter(c);
          setSelRadiusMi(0);
          updatePreview(map, c, e.lngLat);
        }
        return;
      }

      // POLYGON mode
      if (polyClosedRef.current) {
        // A closed polygon exists; a fresh click starts a new one.
        polyPtsRef.current = [];
        polyClosedRef.current = false;
        setPolyClosed(false);
      }
      const pt = { lat: e.lngLat.lat, lng: e.lngLat.lng };
      const pts = polyPtsRef.current;
      // If clicking near the first vertex with >=3 points, close the polygon.
      if (pts.length >= 3) {
        const first = pts[0];
        const distToFirstPx = pixelDist(map, first, pt);
        if (distToFirstPx <= 14) {
          closePolygon(map);
          return;
        }
      }
      const next = [...pts, pt];
      polyPtsRef.current = next;
      setPolyPts(next);
      drawPolygonPreview(map, next, e.lngLat, false);
    };

    const onMove = (e) => {
      if (shapeModeRef.current === 'radius') {
        if (!selCenterRef.current || !selDragRef.current) return;
        updatePreview(map, selCenterRef.current, e.lngLat);
        return;
      }
      // POLYGON: show a rubber-band edge from the last vertex to the cursor.
      if (polyClosedRef.current) return;
      const pts = polyPtsRef.current;
      if (pts.length === 0) return;
      drawPolygonPreview(map, pts, e.lngLat, false);
    };

    const onDblClick = (e) => {
      if (shapeModeRef.current !== 'polygon') return;
      if (polyPtsRef.current.length >= 3) {
        e.preventDefault();
        closePolygon(map);
      }
    };

    map.on('click', onClick);
    map.on('mousemove', onMove);
    map.on('dblclick', onDblClick);
    return () => {
      map.off('click', onClick);
      map.off('mousemove', onMove);
      map.off('dblclick', onDblClick);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [drawMode]);

  // Keep the shapeMode ref synced for the map event handlers.
  useEffect(() => { shapeModeRef.current = shapeMode; }, [shapeMode]);

  // Disable Mapbox's native double-click-zoom while drawing a polygon, so the
  // double-click-to-close gesture doesn't also zoom the map. Restore on exit.
  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;
    if (drawMode && shapeMode === 'polygon') {
      map.doubleClickZoom.disable();
    } else {
      map.doubleClickZoom.enable();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [drawMode, shapeMode]);

  // Ensure the crosshair cursor wins over Mapbox's default canvas cursor by
  // setting it on the canvas container too, and toggling a class.
  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;
    const canvas = map.getCanvas();
    const container = map.getCanvasContainer();
    if (drawMode) {
      canvas.style.cursor = 'crosshair';
      if (container) container.style.cursor = 'crosshair';
    } else {
      canvas.style.cursor = '';
      if (container) container.style.cursor = '';
      // Leaving draw mode: tidy up any in-progress preview.
      clearTether(map);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [drawMode]);

  function addr_selectedFacilities() {
    const ids = facilitiesInShape.filter(f => selChecked[f.id]).map(f => f.id);
    if (ids.length && onAddFacilities) onAddFacilities(ids);
    // Capture the drawn shape onto the scenario for the report.
    if (onAddGeometry) {
      if (shapeMode === 'radius' && selCenter && selRadiusMi > 0) {
        onAddGeometry({ kind: 'radius', center: { lat: selCenter.lat, lng: selCenter.lng }, radiusMi: selRadiusMi });
      } else if (shapeMode === 'polygon' && polyClosed && polyPts.length >= 3) {
        onAddGeometry({ kind: 'polygon', points: polyPts.map(p => ({ lat: p.lat, lng: p.lng })) });
      }
    }
    // After adding, exit draw mode and clear the shape for a clean slate.
    setDrawMode(false);
    resetSelection();
  }

  function addMarkers(map) {
    // Clear any existing markers first.
    markersRef.current.forEach(m => m.remove());
    markersRef.current = [];

    pins.forEach(f => {
      const isCurrent = currentId && f.id === currentId;

      // Build a small pin element. Current facility is larger and accented.
      const el = document.createElement('div');
      el.style.cssText = `
        width: ${isCurrent ? 18 : 14}px;
        height: ${isCurrent ? 18 : 14}px;
        border-radius: 50%;
        background: ${isCurrent ? T.teal : T.darkBlue};
        border: 2px solid #fff;
        box-shadow: 0 1px 4px rgba(0,0,0,0.4);
        cursor: pointer;
      `;
      el.setAttribute('aria-label', f.name || f.id);

      const marker = new mapboxgl.Marker({ element: el })
        .setLngLat([f.lng, f.lat])
        .addTo(map);

      // A lightweight popup on hover/tap with the name; click invokes callback.
      const popup = new mapboxgl.Popup({ offset: 16, closeButton: false })
        .setHTML(
          `<div style="font-family: Poppins, sans-serif; font-size: 12px; font-weight: 600; color: ${T.darkBlue};">${(f.name || f.id)}</div>` +
          `<div style="font-family: Poppins, sans-serif; font-size: 10px; color: #555;">${f.type || 'Facility'} · ${f.id}</div>`
        );
      marker.setPopup(popup);

      el.addEventListener('click', (e) => {
        e.stopPropagation();
        if (onMarkerTap) onMarkerTap(f);
      });
      el.addEventListener('mouseenter', () => popup.addTo(map).setLngLat([f.lng, f.lat]));
      el.addEventListener('mouseleave', () => popup.remove());

      markersRef.current.push(marker);
    });
  }

  function fitToPins(map) {
    if (!pins.length) return;

    if (fitToCurrentOnly && currentId) {
      const cur = pins.find(p => p.id === currentId);
      if (cur) {
        map.easeTo({ center: [cur.lng, cur.lat], zoom: 14, duration: 0 });
        return;
      }
    }

    if (pins.length === 1) {
      map.easeTo({ center: [pins[0].lng, pins[0].lat], zoom: 13, duration: 0 });
      return;
    }

    const bounds = new mapboxgl.LngLatBounds();
    pins.forEach(p => bounds.extend([p.lng, p.lat]));
    map.fitBounds(bounds, { padding: 60, maxZoom: 15, duration: 0 });
  }

  return (
    <div style={{ position: 'relative', width: '100%', height, overflow: 'hidden' }}>
      <div ref={containerRef} style={{ position: 'absolute', inset: 0 }}/>

      {/* Style toggle (layers button). Expands to Streets / Satellite. */}
      {showStyleToggle && MAPBOX_CFG.token && (
        <div style={{ position: 'absolute', top: 10, right: 10, zIndex: 2 }}>
          <button
            onClick={() => setStyleMenuOpen(o => !o)}
            aria-label="Change map style"
            style={{
              width: 36, height: 36, background: '#fff',
              border: `1px solid ${T.rule}`, borderRadius: 4, cursor: 'pointer',
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              boxShadow: '0 1px 4px rgba(0,0,0,0.2)', color: T.darkBlue,
            }}
          >
            <Layers size={18} strokeWidth={2}/>
          </button>
          {styleMenuOpen && (
            <div style={{
              position: 'absolute', top: 42, right: 0, background: '#fff',
              border: `1px solid ${T.rule}`, borderRadius: 4, overflow: 'hidden',
              boxShadow: '0 2px 10px rgba(0,0,0,0.2)', minWidth: 110,
            }}>
              {[
                { k: 'streets',   label: 'Streets' },
                { k: 'satellite', label: 'Satellite' },
              ].map(opt => (
                <button
                  key={opt.k}
                  onClick={() => { setStyleKey(opt.k); setStyleMenuOpen(false); }}
                  style={{
                    display: 'block', width: '100%', textAlign: 'left',
                    padding: '9px 12px', border: 'none', cursor: 'pointer',
                    background: styleKey === opt.k ? T.surfaceAlt : '#fff',
                    color: styleKey === opt.k ? T.darkBlue : T.ink2,
                    fontFamily: 'Poppins, sans-serif', fontSize: 12,
                    fontWeight: styleKey === opt.k ? 700 : 500,
                  }}
                >{opt.label}</button>
              ))}
            </div>
          )}
        </div>
      )}

      {/* Weather (radar) button — separate from the layers button. Sits just
          below it. Toggles the animated NOAA radar overlay + playback bar. */}
      {radarEnabled && MAPBOX_CFG.token && (
        <div style={{ position: 'absolute', top: showStyleToggle ? 54 : 10, right: 10, zIndex: 2 }}>
          <button
            onClick={toggleRadar}
            aria-label="Toggle weather radar"
            title="Weather radar"
            style={{
              width: 36, height: 36,
              background: radarOn ? T.darkBlue : '#fff',
              border: `1px solid ${radarOn ? T.darkBlue : T.rule}`, borderRadius: 4, cursor: 'pointer',
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              boxShadow: '0 1px 4px rgba(0,0,0,0.2)',
              color: radarOn ? '#fff' : T.darkBlue,
            }}
          >
            <CloudRain size={18} strokeWidth={2}/>
          </button>
        </div>
      )}

      {/* Spatial selection button — toggles draw mode. Sits below the radar
          button (or the layers button if radar is off). In draw mode the user
          taps the map to place a center, then drags to size a radius. */}
      {showSpatialSelect && MAPBOX_CFG.token && (
        <div style={{
          position: 'absolute',
          top: (showStyleToggle ? 54 : 10) + (radarEnabled ? 44 : 0),
          right: 10, zIndex: 2,
        }}>
          <button
            onClick={toggleDrawMode}
            aria-label="Select facilities by area"
            title="Select facilities by area"
            style={{
              width: 36, height: 36,
              background: drawMode ? T.teal : '#fff',
              border: `1px solid ${drawMode ? T.teal : T.rule}`, borderRadius: 4, cursor: 'pointer',
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              boxShadow: '0 1px 4px rgba(0,0,0,0.2)',
              color: drawMode ? '#fff' : T.darkBlue,
            }}
          >
            <Target size={18} strokeWidth={2}/>
          </button>
        </div>
      )}

      {/* Alerts button — appears ONLY when there are active warnings (the
          button's presence is itself the alert indicator). It flashes to draw
          attention. Tapping toggles polygon visibility on the map; the data
          and this indicator persist so warnings can't be fully dismissed. */}
      {alertsEnabled && MAPBOX_CFG.token && alerts.length > 0 && (
        <div style={{
          position: 'absolute',
          top: (showStyleToggle ? 54 : 10) + (radarEnabled ? 44 : 0) + (showSpatialSelect ? 44 : 0),
          right: 10, zIndex: 2,
        }}>
          <button
            onClick={() => setAlertsOn(o => !o)}
            aria-label="Weather alerts active — toggle polygons"
            title={`${alerts.length} active weather alert${alerts.length === 1 ? '' : 's'}`}
            className="dst-alert-flash"
            style={{
              position: 'relative',
              width: 36, height: 36,
              background: alertsOn ? '#DC2626' : '#fff',
              border: `1px solid #DC2626`,
              borderRadius: 4, cursor: 'pointer',
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              boxShadow: '0 1px 4px rgba(0,0,0,0.2)',
              color: alertsOn ? '#fff' : '#DC2626',
            }}
          >
            <AlertTriangle size={18} strokeWidth={2}/>
            <span style={{
              position: 'absolute', top: -6, right: -6,
              minWidth: 16, height: 16, padding: '0 4px',
              background: '#fff', color: '#DC2626',
              border: '1px solid #DC2626', borderRadius: 8,
              fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 700,
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              lineHeight: 1,
            }}>{alerts.length}</span>
          </button>
          <style>{`
            @keyframes dstAlertFlash {
              0%, 100% { box-shadow: 0 1px 4px rgba(0,0,0,0.2), 0 0 0 0 rgba(220,38,38,0.6); }
              50%      { box-shadow: 0 1px 4px rgba(0,0,0,0.2), 0 0 0 6px rgba(220,38,38,0); }
            }
            .dst-alert-flash { animation: dstAlertFlash 1.4s ease-in-out infinite; }
          `}</style>
        </div>
      )}

      {/* Spatial selection: instruction hint (before a circle exists) and the
          in-radius facility picker (once a circle is drawn). */}
      {showSpatialSelect && drawMode && ((shapeMode === 'radius' && (!selCenter || selDragRef.current || selRadiusMi === 0)) || (shapeMode === 'polygon' && !polyClosed)) && (
        <div style={{
          position: 'absolute', left: 10, right: 10, bottom: 10, zIndex: 3,
          background: 'rgba(255,255,255,0.97)', border: `1px solid ${T.teal}`,
          borderRadius: 6, boxShadow: '0 2px 10px rgba(0,0,0,0.18)',
          padding: '10px 14px',
          fontFamily: 'Poppins, sans-serif', fontSize: 12, color: T.ink2,
        }}>
          {/* Radius / Polygon mode toggle */}
          <div style={{ display: 'flex', gap: 0, marginBottom: 9, border: `1px solid ${T.rule}`, borderRadius: 6, overflow: 'hidden', width: 'fit-content' }}>
            {[['radius', 'Radius'], ['polygon', 'Polygon']].map(([m, label]) => (
              <button
                key={m}
                onClick={() => switchShapeMode(m)}
                style={{
                  background: shapeMode === m ? T.teal : '#fff',
                  color: shapeMode === m ? '#fff' : T.ink2,
                  border: 'none', cursor: 'pointer',
                  padding: '5px 14px', fontFamily: 'Poppins, sans-serif',
                  fontSize: 11, fontWeight: 600,
                }}
              >{label}</button>
            ))}
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
            <Target size={16} strokeWidth={2} style={{ color: T.teal, flexShrink: 0 }}/>
            <span>
              {shapeMode === 'radius'
                ? 'Click the map to drop a center pin, move the cursor to size the radius, then click again to lock it.'
                : (polyPts.length === 0
                    ? 'Click the map to start drawing an area. Add points around the facilities you want.'
                    : 'Keep clicking to add points. Click the first point, or double-click, to close the area.')}
            </span>
          </div>
        </div>
      )}

      {showSpatialSelect && drawMode && ((shapeMode === 'radius' && selCenter && !selDragRef.current && selRadiusMi > 0) || (shapeMode === 'polygon' && polyClosed)) && (() => {
        // Both layouts use the same collapsible pattern: a summary bar that
        // taps open to reveal the list. Desktop = fixed-width card anchored
        // bottom-right (clear of the control buttons); mobile = bottom sheet
        // spanning the width. Both default collapsed.
        const showBody = panelExpanded;
        const containerStyle = isDesktop
          ? {
              // Anchored to the bottom-right corner. Collapsed = summary bar at
              // the bottom; expanded grows UPWARD, capped so its top stops just
              // under the alert-icon cluster (top-right), scrolling for longer
              // lists.
              position: 'absolute', bottom: 10, right: 10, zIndex: 3,
              width: 340, maxHeight: panelExpanded ? 'calc(100% - 160px)' : 'auto',
              background: '#fff', border: `2px solid ${T.teal}`,
              borderRadius: 8, boxShadow: '0 3px 14px rgba(0,0,0,0.22)',
              display: 'flex', flexDirection: 'column', overflow: 'hidden',
            }
          : {
              position: 'absolute', left: 10, right: 10, bottom: 10, zIndex: 3,
              maxHeight: panelExpanded ? '46%' : 'auto',
              background: '#fff', border: `2px solid ${T.teal}`,
              borderRadius: 8, boxShadow: '0 3px 14px rgba(0,0,0,0.22)',
              display: 'flex', flexDirection: 'column', overflow: 'hidden',
            };
        return (
        <div style={containerStyle}>
          {/* Header doubles as the tap-to-expand summary bar on both layouts. */}
          <div
            onClick={() => setPanelExpanded(x => !x)}
            style={{
              padding: '10px 14px', borderBottom: showBody ? `1px solid ${T.rule}` : 'none',
              display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 10,
              cursor: 'pointer',
            }}
          >
            <div style={{ minWidth: 0 }}>
              <div style={{
                fontFamily: '"Zilla Slab", serif', fontSize: 15, fontWeight: 700, color: T.darkBlue,
              }}>{facilitiesInShape.length} facilit{facilitiesInShape.length === 1 ? 'y' : 'ies'} {shapeMode === 'radius' ? `in ${selRadiusMi.toFixed(1)} mi radius` : 'in drawn area'}</div>
              <div style={{
                fontFamily: 'Poppins, sans-serif', fontSize: 10.5, color: T.ink3, marginTop: 1,
              }}>{panelExpanded ? 'Tap here to collapse. Check the ones to add.' : 'Tap to review and add.'}</div>
            </div>
            <div style={{ display: 'flex', alignItems: 'center', gap: 6, flexShrink: 0 }}>
              <button
                onClick={(e) => { e.stopPropagation(); resetSelection(); }}
                aria-label="Clear selection"
                style={{
                  background: 'transparent', border: `1px solid ${T.rule}`,
                  borderRadius: 5, cursor: 'pointer', color: T.ink2, padding: '5px 9px',
                  fontFamily: 'Poppins, sans-serif', fontSize: 11, fontWeight: 600,
                  display: 'inline-flex', alignItems: 'center', gap: 5,
                }}
              ><Trash2 size={12}/> Clear</button>
              <ChevronDown size={18} style={{
                color: T.ink3,
                transform: panelExpanded ? 'rotate(180deg)' : 'none',
                transition: 'transform .15s',
              }}/>
            </div>
          </div>

          {showBody && (<>
          {/* Facility list with checkboxes */}
          <div style={{ overflowY: 'auto', padding: '4px 0', flex: 1 }}>
            {facilitiesInShape.length === 0 ? (
              <div style={{
                padding: '18px 14px', textAlign: 'center',
                fontFamily: 'Poppins, sans-serif', fontSize: 12, color: T.ink3,
              }}>No facilities inside this {shapeMode === 'radius' ? 'radius' : 'area'}. {shapeMode === 'radius' ? 'Make it larger.' : 'Draw a different shape.'}</div>
            ) : facilitiesInShape.map(f => {
              const checked = !!selChecked[f.id];
              const already = scenario.includes(f.id);
              return (
                <button
                  key={f.id}
                  onClick={() => setSelChecked(s => ({ ...s, [f.id]: !s[f.id] }))}
                  style={{
                    width: '100%', textAlign: 'left', background: 'transparent',
                    border: 'none', borderBottom: `1px solid ${T.ruleSoft}`, cursor: 'pointer',
                    padding: '9px 14px', display: 'flex', alignItems: 'center', gap: 10,
                  }}
                >
                  {checked
                    ? <CheckSquare size={17} strokeWidth={2} style={{ color: T.teal, flexShrink: 0 }}/>
                    : <Square size={17} strokeWidth={2} style={{ color: T.ink3, flexShrink: 0 }}/>}
                  <span style={{ flex: 1, minWidth: 0 }}>
                    <span style={{
                      display: 'block', fontFamily: 'Poppins, sans-serif', fontSize: 12.5,
                      fontWeight: 600, color: T.ink, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
                    }}>{f.name || f.id}</span>
                    <span style={{
                      display: 'block', fontFamily: 'Poppins, sans-serif', fontSize: 10.5, color: T.ink3,
                    }}>{f._distMi.toFixed(1)} mi from {shapeMode === 'radius' ? 'center' : 'area center'}{already ? ' · already in scenario' : ''}</span>
                  </span>
                </button>
              );
            })}
          </div>

          {/* Add action */}
          {(() => {
            const toAdd = facilitiesInShape.filter(f => selChecked[f.id] && !scenario.includes(f.id));
            const checkedCount = facilitiesInShape.filter(f => selChecked[f.id]).length;
            return (
              <div style={{ padding: '10px 14px', borderTop: `1px solid ${T.rule}` }}>
                <button
                  onClick={addr_selectedFacilities}
                  disabled={checkedCount === 0}
                  style={{
                    width: '100%', padding: '11px',
                    fontFamily: 'Poppins, sans-serif', fontSize: 11.5, fontWeight: 700,
                    letterSpacing: '0.1em', textTransform: 'uppercase',
                    background: checkedCount === 0 ? T.rule : T.darkBlue,
                    color: '#fff', border: 'none', borderRadius: 5,
                    cursor: checkedCount === 0 ? 'default' : 'pointer',
                    display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: 7,
                  }}
                >
                  <Plus size={15}/>
                  {toAdd.length > 0
                    ? `Add ${toAdd.length} to scenario`
                    : checkedCount > 0
                      ? 'All checked already in scenario'
                      : 'Check facilities to add'}
                </button>
              </div>
            );
          })()}
          </>)}
        </div>
        );
      })()}

      {/* Radar playback bar — only while radar is on. Shows a loading state
          during the initial frame preload, then play/pause, scrubber, and the
          timestamp of the displayed frame. */}
      {radarEnabled && radarOn && frames.length > 0 && (
        <div style={{
          position: 'absolute', left: 10, right: 10, bottom: 10, zIndex: 2,
          background: 'rgba(255,255,255,0.96)', border: `1px solid ${T.rule}`,
          borderRadius: 6, boxShadow: '0 2px 10px rgba(0,0,0,0.18)',
          padding: '8px 12px', display: 'flex', alignItems: 'center', gap: 10,
        }}>
          {radarLoading ? (
            <div style={{
              flex: 1, display: 'flex', alignItems: 'center', gap: 8,
              fontFamily: 'Poppins, sans-serif', fontSize: 12, color: T.ink2, fontWeight: 600,
            }}>
              <CloudRain size={14} strokeWidth={2} style={{ color: T.teal }} className="dst-radar-pulse"/>
              <span>Loading radar frames…</span>
              <style>{`
                @keyframes dstRadarPulse { 0%,100% { opacity: 0.4; } 50% { opacity: 1; } }
                .dst-radar-pulse { animation: dstRadarPulse 1s ease-in-out infinite; }
              `}</style>
            </div>
          ) : (
            <>
              <button
                onClick={() => setPlaying(p => !p)}
                aria-label={playing ? 'Pause radar' : 'Play radar'}
                style={{
                  width: 30, height: 30, flexShrink: 0,
                  background: T.darkBlue, color: '#fff', border: 'none', borderRadius: 4,
                  cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center',
                }}
              >
                {playing ? <Pause size={15}/> : <Play size={15}/>}
              </button>

              <input
                type="range"
                min={0}
                max={frames.length - 1}
                value={frameIdx}
                onChange={e => { setPlaying(false); setFrameIdx(Number(e.target.value)); }}
                aria-label="Radar time"
                style={{ flex: 1, accentColor: T.darkBlue, cursor: 'pointer' }}
              />

              <div style={{
                flexShrink: 0, minWidth: 92, textAlign: 'right',
                fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink2, fontWeight: 600,
              }}>
                <CloudRain size={11} strokeWidth={2} style={{ verticalAlign: 'text-top', marginRight: 4, color: T.teal }}/>
                {frameLabel(frames[frameIdx])}
                {frameIdx === frames.length - 1 && (
                  <span style={{ color: T.teal, marginLeft: 4 }}>· now</span>
                )}
              </div>
            </>
          )}
        </div>
      )}
    </div>
  );
}

// Placeholder shown when no Mapbox token is configured, so the app degrades
// gracefully instead of rendering a broken/blank map box.
function MapNeedsToken({ height = 480 }) {
  return (
    <div style={{
      width: '100%', height, border: `1px dashed ${T.rule}`,
      background: T.surfaceAlt, display: 'flex', flexDirection: 'column',
      alignItems: 'center', justifyContent: 'center', gap: 8, textAlign: 'center',
      padding: 20,
    }}>
      <MapIcon size={28} color={T.ink3} strokeWidth={1.5}/>
      <div style={{
        fontFamily: 'Poppins, sans-serif', fontSize: 13, fontWeight: 600, color: T.ink2,
      }}>Map unavailable</div>
      <div style={{
        fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink3,
        maxWidth: 280, lineHeight: 1.4,
      }}>
        No Mapbox access token is configured. Add a public token to the
        <code style={{ fontFamily: 'monospace' }}> mapbox.token </code>
        field in dst.config.js to enable the map.
      </div>
    </div>
  );
}

/* ============================================================================
   WEATHER FORECAST (Sprint 2.5) — Current conditions + multi-horizon forecast
   strip below the full map, from NWS api.weather.gov.

   One "Current" card shows live MEASURED conditions from the nearest station
   (with an "as of" time), visually set apart from the FORECAST horizon cards
   that follow it. All data is derived at runtime from facility coordinates,
   so the component is org-agnostic: it computes a centroid from whatever
   facilities it's given. Built centroid-first but structured so a future
   multi-point version (for geographically spread orgs) is a small change.

   Resilience: the NWS chain is several calls; any failure degrades to a
   clear "unavailable" state rather than breaking the page. Per-field nulls in
   observations are simply not rendered (NWS frequently nulls some fields).
   ============================================================================ */

const WX_CFG = (DST_CONFIG.weather && DST_CONFIG.weather.forecast) || {};

// Compute the centroid of facilities that have coordinates. Returns null if
// none do. (Multi-point future: return an array of representative points and
// fan out the fetch; the render layer already maps over horizon data.)
function facilitiesCentroid(facilities) {
  const pts = (facilities || []).filter(
    f => typeof f.lat === 'number' && typeof f.lng === 'number'
  );
  if (!pts.length) return null;
  const lat = pts.reduce((s, f) => s + f.lat, 0) / pts.length;
  const lng = pts.reduce((s, f) => s + f.lng, 0) / pts.length;
  // NWS rejects > 4 decimal places.
  return { lat: Math.round(lat * 1e4) / 1e4, lng: Math.round(lng * 1e4) / 1e4 };
}

// --- Unit conversions (NWS observations are SI; forecast is already US) -----
const cToF = (c) => (c == null ? null : Math.round((c * 9) / 5 + 32));
const kmhToMph = (k) => (k == null ? null : Math.round(k * 0.621371));
const degToCompass = (deg) => {
  if (deg == null) return null;
  const dirs = ['N','NNE','NE','ENE','E','ESE','SE','SSE','S','SSW','SW','WSW','W','WNW','NW','NNW'];
  return dirs[Math.round(deg / 22.5) % 16];
};

// Build a short human summary line for a horizon window from its hourly slice.
// Heuristic: call out the dominant condition and any precip onset/clearing.
function summarizeWindow(periods) {
  if (!periods || !periods.length) return '';
  const maxPop = Math.max(...periods.map(p => (p.probabilityOfPrecipitation?.value ?? 0)));
  const onsetIdx = periods.findIndex(p => (p.probabilityOfPrecipitation?.value ?? 0) >= 50);
  const temps = periods.map(p => p.temperature).filter(t => typeof t === 'number');
  const hi = temps.length ? Math.max(...temps) : null;
  const lo = temps.length ? Math.min(...temps) : null;

  const counts = {};
  periods.forEach(p => { const c = (p.shortForecast || '').trim(); if (c) counts[c] = (counts[c]||0)+1; });
  const dominant = Object.entries(counts).sort((a,b) => b[1]-a[1])[0]?.[0] || '';

  const fmtHour = (iso) => {
    try { return new Date(iso).toLocaleTimeString([], { hour: 'numeric' }); } catch { return ''; }
  };

  if (maxPop >= 50 && onsetIdx > 0) {
    return dominant + ' developing around ' + fmtHour(periods[onsetIdx].startTime);
  }
  if (maxPop >= 50 && onsetIdx === 0) {
    const clearIdx = periods.findIndex(p => (p.probabilityOfPrecipitation?.value ?? 0) < 30);
    if (clearIdx > 0) return dominant + ' early, easing by ' + fmtHour(periods[clearIdx].startTime);
    return dominant + ' likely through the window';
  }
  if (hi != null && lo != null && hi - lo >= 8) {
    return dominant + ', ' + lo + '\u00B0 to ' + hi + '\u00B0';
  }
  return dominant ? (dominant + ', near ' + (hi != null ? hi + '\u00B0' : '')).trim().replace(/,\s*$/, '') : '';
}

// Standalone weather fetch, shared by the live component and the report. Given
// facilities, returns { current, horizons, updatedAt } using the same NWS chain.
// Fetches independently so the report captures conditions at generation time.
async function fetchWeatherData(facilities) {
  const centroid = facilitiesCentroid(facilities);
  if (!centroid) throw new Error('No facility coordinates');
  const base = WX_CFG.apiBase || 'https://api.weather.gov';
  const headers = {
    'User-Agent': WX_CFG.userAgent || 'DST (contact@example.com)',
    'Accept': 'application/geo+json',
  };

  const ptResp = await fetch(base + '/points/' + centroid.lat + ',' + centroid.lng, { headers });
  if (!ptResp.ok) throw new Error('points ' + ptResp.status);
  const pt = await ptResp.json();
  const hourlyUrl = pt.properties && pt.properties.forecastHourly;
  const stationsUrl = pt.properties && pt.properties.observationStations;

  const hourlyData = hourlyUrl
    ? await fetch(hourlyUrl, { headers }).then(r => r.ok ? r.json() : null)
    : null;
  const periods = (hourlyData && hourlyData.properties && hourlyData.properties.periods) || [];

  const horizons = (WX_CFG.horizons || []).map(h => {
    const slice = periods.slice(0, h.hours);
    const temps = slice.map(p => p.temperature).filter(t => typeof t === 'number');
    const maxPop = slice.length ? Math.max(...slice.map(p => (p.probabilityOfPrecipitation && p.probabilityOfPrecipitation.value) || 0)) : null;
    const first = slice[0] || {};
    return {
      key: h.key, label: h.label,
      hi: temps.length ? Math.max(...temps) : null,
      lo: temps.length ? Math.min(...temps) : null,
      tempNow: first.temperature != null ? first.temperature : null,
      pop: maxPop,
      wind: first.windSpeed || null,
      windDir: first.windDirection || null,
      icon: first.icon || null,
      shortForecast: first.shortForecast || '',
      summary: summarizeWindow(slice),
    };
  });

  let current = null;
  try {
    const stData = stationsUrl ? await fetch(stationsUrl, { headers }).then(r => r.ok ? r.json() : null) : null;
    const stationId = (stData && stData.features && stData.features[0] && stData.features[0].properties && stData.features[0].properties.stationIdentifier)
                   || (stData && stData.observationStations && stData.observationStations[0] && stData.observationStations[0].split('/').pop());
    if (stationId) {
      const obsData = await fetch(base + '/stations/' + stationId + '/observations/latest', { headers })
        .then(r => r.ok ? r.json() : null);
      const p = obsData && obsData.properties;
      if (p) {
        current = {
          stationName: p.stationName || stationId,
          timestamp: p.timestamp || null,
          tempF: cToF(p.temperature && p.temperature.value),
          text: p.textDescription || '',
          icon: p.icon || null,
          windMph: kmhToMph(p.windSpeed && p.windSpeed.value),
          windDir: degToCompass(p.windDirection && p.windDirection.value),
          humidity: (p.relativeHumidity && p.relativeHumidity.value != null) ? Math.round(p.relativeHumidity.value) : null,
        };
      }
    }
  } catch (e) { /* observation optional */ }

  return { current, horizons, updatedAt: Date.now() };
}

// Report-side hook: fetch weather once when enabled (at report view time).
function useReportWeather(facilities, enabled) {
  const [wx, setWx] = useState({ status: 'idle', current: null, horizons: [], updatedAt: null });
  useEffect(() => {
    if (!enabled) return;
    let cancelled = false;
    setWx(w => ({ ...w, status: 'loading' }));
    fetchWeatherData(facilities)
      .then(data => { if (!cancelled) setWx({ status: 'ready', ...data }); })
      .catch(e => { if (!cancelled) setWx({ status: 'error', current: null, horizons: [], updatedAt: null, msg: String(e.message || e) }); });
    return () => { cancelled = true; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [enabled]);
  return wx;
}

function WeatherForecast({ facilities, showHeader = true, layout = 'row' }) {
  const enabled = !!WX_CFG.enabled;
  const [state, setState] = useState({ status: 'idle' });
  const [current, setCurrent] = useState(null);
  const [horizons, setHorizons] = useState([]);
  const [updatedAt, setUpdatedAt] = useState(null);
  const fetchTimerRef = useRef(null);

  const centroid = useMemo(() => facilitiesCentroid(facilities), [facilities]);

  const headers = useMemo(() => ({
    'User-Agent': WX_CFG.userAgent || 'DST (contact@example.com)',
    'Accept': 'application/geo+json',
  }), []);

  async function loadForecast() {
    if (!centroid) { setState({ status: 'error', msg: 'No facility coordinates' }); return; }
    setState({ status: 'loading' });
    try {
      const base = WX_CFG.apiBase || 'https://api.weather.gov';
      const ptResp = await fetch(base + '/points/' + centroid.lat + ',' + centroid.lng, { headers });
      if (!ptResp.ok) throw new Error('points ' + ptResp.status);
      const pt = await ptResp.json();
      const hourlyUrl = pt.properties && pt.properties.forecastHourly;
      const stationsUrl = pt.properties && pt.properties.observationStations;

      const hourlyData = hourlyUrl
        ? await fetch(hourlyUrl, { headers }).then(r => r.ok ? r.json() : null)
        : null;
      const periods = (hourlyData && hourlyData.properties && hourlyData.properties.periods) || [];

      const hz = (WX_CFG.horizons || []).map(h => {
        const slice = periods.slice(0, h.hours);
        const temps = slice.map(p => p.temperature).filter(t => typeof t === 'number');
        const maxPop = slice.length ? Math.max(...slice.map(p => (p.probabilityOfPrecipitation && p.probabilityOfPrecipitation.value) || 0)) : null;
        const first = slice[0] || {};
        return {
          key: h.key,
          label: h.label,
          hi: temps.length ? Math.max(...temps) : null,
          lo: temps.length ? Math.min(...temps) : null,
          tempNow: first.temperature != null ? first.temperature : null,
          pop: maxPop,
          wind: first.windSpeed || null,
          windDir: first.windDirection || null,
          icon: first.icon || null,
          shortForecast: first.shortForecast || '',
          summary: summarizeWindow(slice),
        };
      });
      setHorizons(hz);

      let obs = null;
      try {
        const stData = stationsUrl ? await fetch(stationsUrl, { headers }).then(r => r.ok ? r.json() : null) : null;
        const stationId = (stData && stData.features && stData.features[0] && stData.features[0].properties && stData.features[0].properties.stationIdentifier)
                       || (stData && stData.observationStations && stData.observationStations[0] && stData.observationStations[0].split('/').pop());
        if (stationId) {
          const obsData = await fetch(base + '/stations/' + stationId + '/observations/latest', { headers })
            .then(r => r.ok ? r.json() : null);
          const p = obsData && obsData.properties;
          if (p) {
            obs = {
              stationName: p.stationName || stationId,
              timestamp: p.timestamp || null,
              tempF: cToF(p.temperature && p.temperature.value),
              text: p.textDescription || '',
              icon: p.icon || null,
              windMph: kmhToMph(p.windSpeed && p.windSpeed.value),
              windDir: degToCompass(p.windDirection && p.windDirection.value),
              humidity: (p.relativeHumidity && p.relativeHumidity.value != null) ? Math.round(p.relativeHumidity.value) : null,
            };
          }
        }
      } catch (e) { /* observation optional */ }
      setCurrent(obs);

      setUpdatedAt(Date.now());
      setState({ status: 'ready' });
    } catch (e) {
      setState({ status: 'error', msg: String(e.message || e) });
    }
  }

  useEffect(() => {
    if (!enabled || !centroid) return;
    loadForecast();
    const mins = WX_CFG.refreshMinutes || 30;
    fetchTimerRef.current = setInterval(loadForecast, mins * 60 * 1000);
    return () => clearInterval(fetchTimerRef.current);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [enabled, centroid && centroid.lat, centroid && centroid.lng]);

  if (!enabled) return null;

  const asOf = (ts) => {
    if (!ts) return '';
    try { return new Date(ts).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' }); } catch { return ''; }
  };

  return (
    <div style={{ marginTop: showHeader ? 16 : 0 }}>
      {showHeader ? (
        <div style={{
          display: 'flex', justifyContent: 'space-between', alignItems: 'baseline',
          padding: '4px 0 8px', borderBottom: '1px solid ' + T.darkBlue, marginBottom: 12,
          fontFamily: 'Poppins, sans-serif', fontSize: 10, color: T.ink3,
          letterSpacing: '0.1em', textTransform: 'uppercase', fontWeight: 600,
        }}>
          <span>Conditions &amp; Forecast</span>
          {state.status === 'ready' && updatedAt && (
            <span style={{ textTransform: 'none', letterSpacing: 0 }}>Updated {asOf(updatedAt)}</span>
          )}
        </div>
      ) : (
        state.status === 'ready' && updatedAt && (
          <div style={{
            textAlign: 'right', marginBottom: 8,
            fontFamily: 'Poppins, sans-serif', fontSize: 10, color: T.ink3,
          }}>Updated {asOf(updatedAt)}</div>
        )
      )}

      {state.status === 'loading' && (
        <div style={{ padding: '20px', textAlign: 'center', fontFamily: 'Poppins, sans-serif', fontSize: 12, color: T.ink3 }}>
          <RefreshCw size={14} className="dst-wx-spin" style={{ verticalAlign: 'middle', marginRight: 6 }}/>
          Loading conditions and forecast…
          <style>{'@keyframes dstWxSpin{to{transform:rotate(360deg)}} .dst-wx-spin{display:inline-block;animation:dstWxSpin 1s linear infinite}'}</style>
        </div>
      )}

      {state.status === 'error' && (
        <div style={{ padding: '14px', background: T.surfaceAlt, border: '1px solid ' + T.rule, fontFamily: 'Poppins, sans-serif', fontSize: 12, color: T.ink2 }}>
          Forecast unavailable right now. The map and radar are unaffected.
        </div>
      )}

      {state.status === 'ready' && (() => {
        const stack = layout === 'stack';
        const containerStyle = stack
          ? { display: 'flex', flexDirection: 'column', gap: 8 }
          : { display: 'flex', gap: 10, overflowX: 'auto', paddingBottom: 4 };

        // CURRENT card -----------------------------------------------------
        const currentCard = (
          <div style={stack
            ? { padding: '12px 14px', background: T.darkBlue, color: '#fff', borderRadius: 8, border: '2px solid ' + T.teal, display: 'flex', alignItems: 'center', gap: 14 }
            : { flex: '0 0 auto', minWidth: 150, padding: '12px 14px', background: T.darkBlue, color: '#fff', borderRadius: 8, border: '2px solid ' + T.teal }
          }>
            {/* Left block: label + temp + condition */}
            <div style={stack ? { flex: 1, minWidth: 0 } : undefined}>
              <div style={{ fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 700, letterSpacing: '0.14em', textTransform: 'uppercase', color: T.teal, marginBottom: 6, display: 'flex', alignItems: 'center', gap: 4 }}>
                Current
                <span style={{ width: 6, height: 6, borderRadius: '50%', background: T.teal, display: 'inline-block' }}/>
              </div>
              {current ? (
                <>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                    {current.icon && (
                      <img src={current.icon} alt="" width={36} height={36} style={{ borderRadius: 4, flexShrink: 0 }} onError={(e) => { e.target.style.display = 'none'; }}/>
                    )}
                    <div style={{ fontFamily: '"Zilla Slab", serif', fontSize: 28, fontWeight: 700, lineHeight: 1 }}>{current.tempF != null ? current.tempF + '\u00B0' : '\u2014'}</div>
                  </div>
                  <div style={{ fontFamily: 'Poppins, sans-serif', fontSize: 12, fontWeight: 600, marginTop: 6 }}>{current.text || ''}</div>
                </>
              ) : (
                <div style={{ fontFamily: 'Poppins, sans-serif', fontSize: 11, color: 'rgba(255,255,255,0.8)', paddingTop: 6 }}>Observation unavailable</div>
              )}
            </div>
            {/* Right block: wind / humidity / as-of. In stack mode this sits to
                the right; in row mode it falls below. */}
            {current && (
              <div style={stack
                ? { textAlign: 'right', flexShrink: 0 }
                : { marginTop: 8 }
              }>
                <div style={{ fontFamily: 'Poppins, sans-serif', fontSize: 10, color: 'rgba(255,255,255,0.85)', lineHeight: 1.6 }}>
                  {current.windMph != null && (
                    <div><Wind size={10} style={{ verticalAlign: 'text-top', marginRight: 4 }}/>{current.windMph} mph {current.windDir || ''}</div>
                  )}
                  {current.humidity != null && (
                    <div><Droplets size={10} style={{ verticalAlign: 'text-top', marginRight: 4 }}/>{current.humidity}% humidity</div>
                  )}
                </div>
                {current.timestamp && (
                  <div style={{ fontFamily: 'Poppins, sans-serif', fontSize: 9, color: 'rgba(255,255,255,0.6)', marginTop: 8, display: 'flex', alignItems: 'center', gap: 3, justifyContent: stack ? 'flex-end' : 'flex-start' }}>
                    <Clock size={9}/> as of {asOf(current.timestamp)}
                  </div>
                )}
              </div>
            )}
          </div>
        );

        // HORIZON card -----------------------------------------------------
        const horizonCard = (h) => (
          <div key={h.key} style={stack
            ? { padding: '12px 14px', background: T.surface, border: '1px solid ' + T.rule, borderRadius: 8, display: 'flex', alignItems: 'center', gap: 14 }
            : { flex: '0 0 auto', minWidth: 150, padding: '12px 14px', background: T.surface, border: '1px solid ' + T.rule, borderRadius: 8 }
          }>
            {/* Left: label + temp + summary */}
            <div style={stack ? { flex: 1, minWidth: 0 } : undefined}>
              <div style={{ fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 700, letterSpacing: '0.14em', textTransform: 'uppercase', color: T.ink3, marginBottom: 6 }}>{h.label}</div>
              <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                {h.icon && (
                  <img src={h.icon} alt="" width={36} height={36} style={{ borderRadius: 4, flexShrink: 0 }} onError={(e) => { e.target.style.display = 'none'; }}/>
                )}
                <div style={{ fontFamily: '"Zilla Slab", serif', fontSize: 24, fontWeight: 700, color: T.darkBlue, lineHeight: 1 }}>
                  {h.key === '1h' ? (h.tempNow != null ? h.tempNow + '\u00B0' : '\u2014') : (h.hi != null ? h.lo + '\u00B0\u2013' + h.hi + '\u00B0' : '\u2014')}
                </div>
              </div>
              <div style={{ fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink2, marginTop: 6, fontWeight: 500, lineHeight: 1.35, minHeight: stack ? 0 : 30 }}>{h.summary || h.shortForecast}</div>
            </div>
            {/* Right: precip / wind — stacked vertically in both layouts.
                Text matches the summary line (size 11, ink2); icons keep their
                current colors (precip teal, wind pinned to ink3). */}
            <div style={stack
              ? { textAlign: 'right', flexShrink: 0, fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink2, lineHeight: 1.7 }
              : { fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink2, marginTop: 8, lineHeight: 1.7 }
            }>
              {h.pop != null && (
                <div><Droplets size={10} style={{ verticalAlign: 'text-top', marginRight: 3, color: T.teal }}/>{h.pop}%</div>
              )}
              {h.wind && (
                <div><Wind size={10} color={T.ink3} style={{ verticalAlign: 'text-top', marginRight: 3 }}/>{h.wind} {h.windDir || ''}</div>
              )}
            </div>
          </div>
        );

        return (
          <div style={containerStyle}>
            {currentCard}
            {horizons.map(horizonCard)}
          </div>
        );
      })()}
    </div>
  );
}

/* ============================================================================
   FACILITY MAP (Sprint 2) — Inline Mapbox mini-map on facility detail pages
   ============================================================================ */

function FacilityMap({ centerLat, centerLng, currentId, currentName, onPinTap }) {
  const hasToken = !!(DST_CONFIG.mapbox && DST_CONFIG.mapbox.token);
  const H = 240;

  if (!hasToken) {
    return <MapNeedsToken height={H}/>;
  }

  // Show all facilities as markers but center/zoom on the current one. Tapping
  // any other facility's marker navigates to it (preserved from the old SVG
  // behavior via onPinTap).
  return (
    <div style={{ border: `1px solid ${T.rule}` }}>
      <MapboxMap
        facilities={PCCA_FACILITY_PINS}
        currentId={currentId}
        onMarkerTap={(f) => { if (onPinTap) onPinTap(f); }}
        height={H}
        interactive={true}
        showStyleToggle={false}
        fitToCurrentOnly={true}
      />
    </div>
  );
}

/* ============================================================================
   PORT MAP SCREEN — Full Port of Corpus Christi map with all facility pins
   ============================================================================ */

function PortMapScreen({ onBack, onOpen, scenarioCount, scenario = [], addToScenario, onAddGeometry, onScenarioTap, onHome }) {
  const [selectedPin, setSelectedPin] = useState(null);
  const isDesktop = useIsDesktop();
  // Mobile shows Facility Map / Conditions & Forecast as tabs to save vertical
  // space (the facility card and future tools crowd a single scroll). Desktop
  // has room, so it stacks everything with no tabs.
  const [mapTab, setMapTab] = useState('map');   // 'map' | 'forecast'
  const hasToken = !!(DST_CONFIG.mapbox && DST_CONFIG.mapbox.token);

  // All facilities that have coordinates become map markers.
  const facilityPins = PCCA_FACILITY_PINS;

  // Resolve full facility detail from the lookup if present, else the pin's
  // own basic fields.
  const getFacilityDetail = (pinId) => {
    const detailItem = lookup[pinId];
    if (detailItem) return detailItem;
    return facilityPins.find(p => p.id === pinId);
  };

  // Map height: desktop keeps a tall map; mobile constrains to 4:5 (portrait)
  // of the viewport width, capped, to leave room for the facility card / tools.
  const [vpWidth, setVpWidth] = useState(
    typeof window !== 'undefined' ? window.innerWidth : 390
  );
  useEffect(() => {
    const onResize = () => setVpWidth(window.innerWidth);
    window.addEventListener('resize', onResize);
    return () => window.removeEventListener('resize', onResize);
  }, []);
  // Mobile content width ~= viewport minus the 16px horizontal padding each
  // side. 4:5 means height = width * 1.25, capped so very wide phones/tablets
  // in mobile layout don't get an enormous map.
  const mobileMapH = Math.min(Math.round((Math.min(vpWidth, 520) - 32) * 1.25), 460);
  const MAP_H = isDesktop ? 480 : mobileMapH;

  const tabs = [
    { k: 'map',      label: 'Facility Map' },
    { k: 'forecast', label: 'Conditions & Forecast' },
  ];
  // Which sections are visible depends on layout. Desktop: both. Mobile: the
  // active tab only.
  const showMapPanel      = isDesktop || mapTab === 'map';
  const showForecastPanel = isDesktop || mapTab === 'forecast';

  return (
    <>
      <TopNav back={onBack} title={`${DST_CONFIG.org.shortName} Map`} sub={DST_CONFIG.org.homeTitle} scenarioCount={scenarioCount} onScenarioTap={onScenarioTap} />
      <div style={{ padding: '12px 16px 24px' }}>
        {/* Pin counter */}
        <div style={{
          display: 'flex', justifyContent: 'space-between', alignItems: 'baseline',
          padding: '4px 0 8px', borderBottom: `1px solid ${T.darkBlue}`,
          marginBottom: 12,
          fontFamily: 'Poppins, sans-serif', fontSize: 10, color: T.ink3,
          letterSpacing: '0.1em', textTransform: 'uppercase', fontWeight: 600,
        }}>
          <span>{DST_CONFIG.copy.mapHeaderTitle}</span>
          <span>{facilityPins.length} Facilities</span>
        </div>

        {/* Mobile-only tab strip: Facility Map / Conditions & Forecast.
            Hidden on desktop, which stacks both panels. */}
        {!isDesktop && (
          <div style={{
            display: 'flex', borderBottom: `1px solid ${T.rule}`, marginBottom: 16,
            overflowX: 'auto', msOverflowStyle: 'none', scrollbarWidth: 'none',
          }}>
            {tabs.map(({ k, label }) => (
              <button key={k} onClick={() => setMapTab(k)} style={{
                flex: 1, padding: '10px 6px',
                background: 'transparent', border: 'none',
                borderBottom: mapTab === k ? `2px solid ${T.darkBlue}` : '2px solid transparent',
                cursor: 'pointer', fontFamily: 'Poppins, sans-serif', fontSize: 10,
                fontWeight: 700, letterSpacing: '0.06em', textTransform: 'uppercase',
                color: mapTab === k ? T.darkBlue : T.ink3, marginBottom: -1,
                whiteSpace: 'nowrap',
              }}>{label}</button>
            ))}
          </div>
        )}

        {/* Map (real Mapbox basemap, or a placeholder if no token configured) */}
        {showMapPanel && (!hasToken ? (
          <MapNeedsToken height={MAP_H}/>
        ) : facilityPins.length === 0 ? (
          <div style={{
            width: '100%', height: MAP_H, border: `1px solid ${T.rule}`,
            background: T.surfaceAlt, display: 'flex', alignItems: 'center',
            justifyContent: 'center', textAlign: 'center', padding: 20,
            fontFamily: 'Poppins, sans-serif', fontSize: 12, color: T.ink3,
          }}>
            No facilities have map coordinates yet.
          </div>
        ) : (
          <div style={{ border: `1px solid ${T.rule}` }}>
            <MapboxMap
              facilities={facilityPins}
              onMarkerTap={(f) => setSelectedPin(f)}
              height={MAP_H}
              interactive={true}
              showStyleToggle={true}
              showWeather={true}
              showSpatialSelect={true}
              scenario={scenario}
              onAddFacilities={(ids) => { if (addToScenario) ids.forEach(id => addToScenario(id)); }}
              onAddGeometry={onAddGeometry}
            />
          </div>
        ))}

        {/* Selected pin info card */}
        {showMapPanel && selectedPin && (() => {
          const detail = getFacilityDetail(selectedPin.id);
          const hasFullDetail = !!lookup[selectedPin.id];
          return (
            <div style={{
              marginTop: 14, padding: '14px 16px',
              border: `2px solid ${T.darkBlue}`, background: T.surface,
              position: 'relative',
            }}>
              <button onClick={() => setSelectedPin(null)} style={{
                position: 'absolute', top: 10, right: 10,
                background: 'transparent', border: 'none', cursor: 'pointer',
                color: T.ink3, padding: 4, display: 'inline-flex',
              }}><X size={16}/></button>

              <div style={{
                fontFamily: 'Poppins, sans-serif', fontSize: 9, color: T.teal,
                letterSpacing: '0.14em', textTransform: 'uppercase', fontWeight: 700,
                marginBottom: 4,
              }}>Facility · {selectedPin.id}</div>
              <div style={{
                fontFamily: '"Zilla Slab", serif', fontSize: 18, fontWeight: 600,
                color: T.darkBlue, letterSpacing: '-0.005em', lineHeight: 1.2,
                marginBottom: 8, paddingRight: 24,
              }}>{selectedPin.name}</div>

              {hasFullDetail && detail.address && (
                <div style={{
                  display: 'flex', gap: 8, marginBottom: 8, alignItems: 'flex-start',
                }}>
                  <MapPin size={14} color={T.teal} strokeWidth={2} style={{ marginTop: 2, flexShrink: 0 }}/>
                  <div style={{
                    fontFamily: 'Poppins, sans-serif', fontSize: 12, color: T.ink, lineHeight: 1.4,
                  }}>
                    {detail.address}<br/>
                    <span style={{ color: T.ink2 }}>
                      {[detail.city, detail.state, detail.zip].filter(Boolean).join(', ').replace(/,\s*$/, '')}
                    </span>
                  </div>
                </div>
              )}

              {hasFullDetail && detail.phone && (
                <a href={`tel:${detail.phone}`} style={{
                  display: 'flex', gap: 8, alignItems: 'center',
                  marginBottom: 12, color: T.darkBlue, textDecoration: 'none',
                }}>
                  <Phone size={14} color={T.teal} strokeWidth={2}/>
                  <span style={{
                    fontFamily: '"Zilla Slab", serif', fontSize: 14, fontWeight: 600,
                  }}>{detail.phone}</span>
                </a>
              )}

              <div style={{
                fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink3, fontWeight: 500,
                marginBottom: 12, letterSpacing: '0.04em',
              }}>
                <Navigation size={11} strokeWidth={2} style={{ verticalAlign: 'text-top', marginRight: 4 }}/>
                {selectedPin.lat.toFixed(5)}, {selectedPin.lng.toFixed(5)}
              </div>

              {hasFullDetail ? (
                <button onClick={() => onOpen(selectedPin.id)} style={{
                  width: '100%', padding: '10px',
                  fontFamily: 'Poppins, sans-serif', fontSize: 11, fontWeight: 700,
                  letterSpacing: '0.12em', textTransform: 'uppercase',
                  background: T.darkBlue, color: '#fff', border: 'none', cursor: 'pointer',
                  display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: 6,
                }}>
                  Open Facility Details <ChevronRight size={14}/>
                </button>
              ) : (
                <div style={{
                  padding: '8px 12px', background: T.surfaceAlt,
                  fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink2,
                  fontStyle: 'italic',
                }}>Detail page not yet built for this facility.</div>
              )}
            </div>
          );
        })()}

        {/* Legend — part of the Facility Map panel */}
        {showMapPanel && (
          <div style={{
            marginTop: 14, padding: '10px 14px',
            background: T.surfaceAlt, border: `1px solid ${T.rule}`,
            fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink2,
          }}>
            <div style={{
              fontSize: 9, fontWeight: 700, letterSpacing: '0.14em',
              textTransform: 'uppercase', color: T.ink3, marginBottom: 6,
            }}>Legend</div>
            <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
              <span style={{
                width: 10, height: 10, borderRadius: '50%', background: T.darkBlue,
                border: '1.5px solid #fff', boxShadow: '0 0 0 1px rgba(0,0,0,0.1)',
              }}/>
              <span>{DST_CONFIG.org.shortName} Facility — tap a marker to view details</span>
            </div>
          </div>
        )}

        {/* Conditions & forecast strip — current observed + forecast horizons
            for the facility area (centroid of facility coordinates). On mobile
            this is its own tab; on desktop it stacks below the map. */}
        {showForecastPanel && (
          <div style={{ marginTop: isDesktop ? 20 : 0 }}>
            <WeatherForecast facilities={facilityPins} showHeader={isDesktop} layout={isDesktop ? 'row' : 'stack'} />
          </div>
        )}
      </div>
      <BottomNav onPrevious={onBack} onHome={onHome} />
    </>
  );
}

/* ============================================================================
   CRITICAL CONTACTS SCREEN — All personnel records, sortable/filterable
   ============================================================================ */

function CriticalContactsScreen({ onBack, scenarioCount, onScenarioTap, onHome }) {
  const [query, setQuery] = useState('');
  const [sortBy, setSortBy] = useState('name');
  const [deptFilter, setDeptFilter] = useState('All');
  const [deptOpen, setDeptOpen] = useState(false);
  const [selectedPerson, setSelectedPerson] = useState(null);

  const depts = useMemo(() => ['All', ...new Set(PERSONNEL.map(p => p.dept))].sort(), []);

  const filtered = useMemo(() => {
    let r = PERSONNEL;
    if (query) {
      const q = query.toLowerCase();
      r = r.filter(p =>
        p.name.toLowerCase().includes(q) ||
        p.title.toLowerCase().includes(q) ||
        p.dept.toLowerCase().includes(q) ||
        (p.function || '').toLowerCase().includes(q));
    }
    if (deptFilter !== 'All') r = r.filter(p => p.dept === deptFilter);
    r = [...r];
    if (sortBy === 'name')  r.sort((a, b) => a.name.localeCompare(b.name));
    if (sortBy === 'dept')  r.sort((a, b) => a.dept.localeCompare(b.dept) || a.name.localeCompare(b.name));
    if (sortBy === 'title') r.sort((a, b) => a.title.localeCompare(b.title));
    return r;
  }, [query, sortBy, deptFilter]);

  // Get initials for avatar
  const initials = (name) => {
    // Name format is "Last, First M." — pick first letter of last and first
    const parts = name.split(',').map(s => s.trim());
    if (parts.length >= 2) {
      const last = parts[0][0] || '';
      const firstParts = parts[1].split(' ');
      const first = firstParts[0][0] || '';
      return (first + last).toUpperCase();
    }
    return name.slice(0, 2).toUpperCase();
  };

  return (
    <>
      <TopNav back={onBack} title="Critical Contacts" sub={DST_CONFIG.org.homeTitle} scenarioCount={scenarioCount} onScenarioTap={onScenarioTap} />
      <div style={{ padding: '12px 16px 24px' }}>
        {/* Search */}
        <div style={{
          display: 'flex', alignItems: 'center', gap: 8, padding: '8px 12px',
          border: `1px solid ${T.rule}`, background: T.surface, marginBottom: 10,
        }}>
          <Search size={14} color={T.ink3} />
          <input
            value={query} onChange={e => setQuery(e.target.value)}
            placeholder="Search name, title, or function…"
            style={{
              border: 'none', outline: 'none', flex: 1,
              fontFamily: 'Poppins, sans-serif', fontSize: 13,
              color: T.ink, background: 'transparent',
            }}
          />
          {query && <button onClick={() => setQuery('')} style={{
            background: 'none', border: 'none', cursor: 'pointer',
            color: T.ink3, padding: 0, display: 'inline-flex',
          }}><X size={14}/></button>}
        </div>

        {/* Sort + Dept filter */}
        <div style={{ display: 'flex', justifyContent: 'space-between', gap: 10, marginBottom: 10 }}>
          <div style={{
            display: 'inline-flex', border: `1px solid ${T.rule}`, background: T.surface,
          }}>
            {[
              { k: 'name', label: 'Name' },
              { k: 'dept', label: 'Dept' },
              { k: 'title', label: 'Title' },
            ].map(({ k, label }) => (
              <button key={k} onClick={() => setSortBy(k)} style={{
                padding: '7px 12px', border: 'none', cursor: 'pointer',
                fontFamily: 'Poppins, sans-serif', fontSize: 10, fontWeight: 600,
                letterSpacing: '0.08em', textTransform: 'uppercase',
                background: sortBy === k ? T.darkBlue : 'transparent',
                color: sortBy === k ? '#fff' : T.ink2,
              }}>{label}</button>
            ))}
          </div>

          <div style={{ position: 'relative' }}>
            <button onClick={() => setDeptOpen(o => !o)} style={{
              padding: '7px 10px', border: `1px solid ${T.rule}`,
              background: T.surface, color: T.ink, cursor: 'pointer',
              fontFamily: 'Poppins, sans-serif', fontSize: 11, fontWeight: 500,
              display: 'inline-flex', alignItems: 'center', gap: 6,
            }}>
              <span style={{ fontWeight: 600, fontSize: 9, letterSpacing: '0.08em', textTransform: 'uppercase', color: T.ink3 }}>Dept</span>
              <span style={{ maxWidth: 100, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{deptFilter}</span>
              <ChevronDown size={12} />
            </button>
            {deptOpen && (
              <div style={{
                position: 'absolute', top: '100%', right: 0, marginTop: 4,
                background: T.surface, border: `1px solid ${T.rule}`,
                minWidth: 220, maxHeight: 320, overflowY: 'auto', zIndex: 30,
                boxShadow: '0 8px 24px rgba(14,30,51,0.12)',
              }}>
                {depts.map(d => (
                  <button key={d} onClick={() => { setDeptFilter(d); setDeptOpen(false); }} style={{
                    display: 'block', width: '100%', textAlign: 'left',
                    padding: '10px 14px', border: 'none', cursor: 'pointer',
                    background: deptFilter === d ? T.surfaceAlt : 'transparent',
                    fontFamily: 'Poppins, sans-serif', fontSize: 12, fontWeight: 500,
                    color: deptFilter === d ? T.darkBlue : T.ink, borderBottom: `1px solid ${T.ruleSoft}`,
                  }}>{d}</button>
                ))}
              </div>
            )}
          </div>
        </div>

        {/* Counter */}
        <div style={{
          padding: '4px 0 8px', borderBottom: `1px solid ${T.darkBlue}`,
          fontFamily: 'Poppins, sans-serif', fontSize: 10, color: T.ink3,
          letterSpacing: '0.1em', textTransform: 'uppercase', fontWeight: 600,
        }}>
          Showing {filtered.length} of {PERSONNEL.length}
        </div>

        {/* List */}
        {filtered.map((p, idx) => {
          const c = DEPT_COLORS[p.dept] || T.ink2;
          return (
            <button key={`${p.email}-${idx}`} onClick={() => setSelectedPerson(p)} style={{
              width: '100%', display: 'flex', gap: 12, alignItems: 'center',
              padding: '12px 6px', textAlign: 'left', cursor: 'pointer',
              borderBottom: `1px solid ${T.ruleSoft}`, background: T.surface,
              border: 0, borderBottomWidth: 1, borderBottomStyle: 'solid',
              borderBottomColor: T.ruleSoft, fontFamily: 'inherit',
            }}>
              <div style={{
                width: 38, height: 38, background: c, color: '#fff',
                display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
                fontFamily: '"Zilla Slab", serif', fontSize: 13, fontWeight: 700,
                flexShrink: 0,
              }}>{initials(p.name)}</div>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{
                  fontFamily: '"Zilla Slab", serif', fontSize: 14, fontWeight: 600,
                  color: T.darkBlue, letterSpacing: '-0.005em', lineHeight: 1.2,
                  marginBottom: 2,
                }}>{p.name}</div>
                <div style={{
                  fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink2,
                  fontWeight: 500, marginBottom: 3,
                  overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
                }}>{p.title}</div>
                <DeptChip name={p.dept} tiny />
              </div>
              <ChevronRight size={14} color={T.ink3} />
            </button>
          );
        })}
        {filtered.length === 0 && (
          <div style={{
            padding: 32, textAlign: 'center', fontFamily: 'Poppins, sans-serif',
            color: T.ink3, fontSize: 13,
          }}>No results.</div>
        )}
      </div>

      {/* Contact detail sheet */}
      <Sheet open={!!selectedPerson} onClose={() => setSelectedPerson(null)} title="Contact Details">
        {selectedPerson && (() => {
          const c = DEPT_COLORS[selectedPerson.dept] || T.ink2;
          return (
            <>
              <div style={{ display: 'flex', gap: 14, alignItems: 'flex-start', marginBottom: 16 }}>
                <div style={{
                  width: 56, height: 56, background: c, color: '#fff',
                  display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
                  fontFamily: '"Zilla Slab", serif', fontSize: 18, fontWeight: 700,
                  flexShrink: 0,
                }}>{initials(selectedPerson.name)}</div>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{
                    fontFamily: '"Zilla Slab", serif', fontSize: 20, fontWeight: 600,
                    color: T.darkBlue, letterSpacing: '-0.01em', lineHeight: 1.15,
                    marginBottom: 4,
                  }}>{selectedPerson.name}</div>
                  <div style={{
                    fontFamily: 'Poppins, sans-serif', fontSize: 13, color: T.ink2,
                    fontWeight: 500, marginBottom: 6,
                  }}>{selectedPerson.title}</div>
                  <DeptChip name={selectedPerson.dept} />
                  {selectedPerson.office && (
                    <div style={{
                      marginTop: 4,
                      fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink3,
                    }}>{selectedPerson.office}</div>
                  )}
                </div>
              </div>

              {selectedPerson.function && (
                <div style={{
                  marginBottom: 16, padding: '10px 12px',
                  background: T.surfaceAlt, border: `1px solid ${T.lightTeal}`,
                }}>
                  <div style={{
                    fontFamily: 'Poppins, sans-serif', fontSize: 9, color: T.darkBlue,
                    letterSpacing: '0.12em', textTransform: 'uppercase', fontWeight: 700,
                    marginBottom: 4,
                  }}>Function / Expertise</div>
                  <div style={{
                    fontFamily: 'Poppins, sans-serif', fontSize: 12, color: T.ink,
                    lineHeight: 1.45,
                  }}>{selectedPerson.function}</div>
                </div>
              )}

              {selectedPerson.mobile && selectedPerson.mobile !== '0' && (
                <a href={`tel:${selectedPerson.mobile}`} style={{
                  display: 'flex', alignItems: 'center', gap: 12, padding: '12px 14px',
                  background: T.surfaceAlt, color: T.darkBlue, textDecoration: 'none',
                  marginBottom: 8, border: `1px solid ${T.lightTeal}`,
                }}>
                  <Phone size={16} color={T.teal} strokeWidth={2}/>
                  <div>
                    <div style={{
                      fontFamily: 'Poppins, sans-serif', fontSize: 9, color: T.ink3,
                      letterSpacing: '0.1em', textTransform: 'uppercase', fontWeight: 600,
                    }}>Mobile</div>
                    <div style={{
                      fontFamily: '"Zilla Slab", serif', fontSize: 16, fontWeight: 600,
                      color: T.darkBlue,
                    }}>{selectedPerson.mobile}</div>
                  </div>
                </a>
              )}

              {selectedPerson.officePhone && (
                <a href={`tel:${selectedPerson.officePhone}`} style={{
                  display: 'flex', alignItems: 'center', gap: 12, padding: '12px 14px',
                  background: T.surfaceAlt, color: T.darkBlue, textDecoration: 'none',
                  marginBottom: 8, border: `1px solid ${T.lightTeal}`,
                }}>
                  <Phone size={16} color={T.teal} strokeWidth={2}/>
                  <div>
                    <div style={{
                      fontFamily: 'Poppins, sans-serif', fontSize: 9, color: T.ink3,
                      letterSpacing: '0.1em', textTransform: 'uppercase', fontWeight: 600,
                    }}>Office</div>
                    <div style={{
                      fontFamily: '"Zilla Slab", serif', fontSize: 16, fontWeight: 600,
                      color: T.darkBlue,
                    }}>{selectedPerson.officePhone}</div>
                  </div>
                </a>
              )}

              {selectedPerson.email && (
                <a href={`mailto:${selectedPerson.email}`} style={{
                  display: 'flex', alignItems: 'center', gap: 12, padding: '12px 14px',
                  background: T.surfaceAlt, color: T.darkBlue, textDecoration: 'none',
                  border: `1px solid ${T.lightTeal}`,
                }}>
                  <Mail size={16} color={T.teal} strokeWidth={2}/>
                  <div style={{ minWidth: 0, flex: 1 }}>
                    <div style={{
                      fontFamily: 'Poppins, sans-serif', fontSize: 9, color: T.ink3,
                      letterSpacing: '0.1em', textTransform: 'uppercase', fontWeight: 600,
                    }}>Email</div>
                    <div style={{
                      fontFamily: 'Poppins, sans-serif', fontSize: 13, fontWeight: 500,
                      color: T.darkBlue, wordBreak: 'break-all',
                    }}>{selectedPerson.email}</div>
                  </div>
                </a>
              )}
            </>
          );
        })()}
      </Sheet>
      <BottomNav onPrevious={onBack} onHome={onHome} />
    </>
  );
}

/* ============================================================================
   SCENARIO BUILDER SCREEN — Active scenario list + aggregate stats
   ============================================================================ */

function ScenarioBuilderScreen({ scenario, scenarioStates = {}, scenarioName, scenarioNotes = [], onBack, onOpen, onRemove, onClear, onAddNew, onHome, onOpenCascade, onCycleState, onSetState, onResetStates, onGenerateReport, onSaveScenario, onOpenMyScenarios, onOpenNotes, onSetScenarioName, savedScenarios = [] }) {
  const items = scenario.map(id => lookup[id]).filter(Boolean);
  const [saveOpen, setSaveOpen] = useState(false);
  const [saveName, setSaveName] = useState('');
  const [saveOverwriteId, setSaveOverwriteId] = useState(null);
  const [savedFlash, setSavedFlash] = useState(false);
  const [editingName, setEditingName] = useState(false);
  const [nameDraft, setNameDraft] = useState(scenarioName || '');
  const [questionsOpen, setQuestionsOpen] = useState(false);
  const [actionsOpen, setActionsOpen] = useState(false);

  // Initial Actions for the current scenario — top short-term step from each asset,
  // ordered by Restoration Score (highest first). Mirrors what the report shows.
  // No state filtering: even Being Fixed and Manual Ops assets show their action
  // since the user may want to reference the original action plan anytime.
  const scenarioInitialActions = useMemo(() => {
    return [...items]
      .sort((a, b) => (b.restorationScore || 0) - (a.restorationScore || 0))
      .map(item => {
        const list = item.shortTerm || [];
        if (list.length === 0) return null;
        const top = list[0];
        const state = scenarioStates[item.id] || 'disrupted';
        return {
          assetId: item.id,
          assetName: item.name,
          assetType: item.type,
          assetScore: item.restorationScore,
          assetDept: item.dept,
          state,
          head: top.head,
          body: top.body || [],
        };
      })
      .filter(Boolean);
  }, [items, scenarioStates]);

  // Group scenario items by what-if state
  const itemsByState = useMemo(() => {
    const groups = { disrupted: [], unable: [], manual: [], fixing: [] };
    for (const item of items) {
      const state = scenarioStates[item.id] || 'disrupted';
      (groups[state] || groups.disrupted).push(item);
    }
    // Sort each group by restoration score
    for (const k of Object.keys(groups)) {
      groups[k].sort((a, b) => (b.restorationScore || 0) - (a.restorationScore || 0));
    }
    return groups;
  }, [items, scenarioStates]);

  // Active seeds = Disrupted + Unable to Repair (these contribute to cascade math)
  const activeSeeds = useMemo(() =>
    scenario.filter(id => {
      const s = scenarioStates[id] || 'disrupted';
      return STATE_META[s] && STATE_META[s].inCascade;
    }),
  [scenario, scenarioStates]);

  // Detect whether any item has been moved out of the default 'disrupted' state
  const whatIfActive = useMemo(() =>
    Object.values(scenarioStates).some(s => s && s !== 'disrupted'),
  [scenarioStates]);

  // Aggregate calculations — deduplicated via cascade traversal of ACTIVE seeds only
  const stats = useMemo(() => {
    if (items.length === 0) return null;
    const cascade = computeCascade(activeSeeds);
    const totalDirect = cascade.direct.size;
    const totalCascade = cascade.totalCascade.size;
    const totalIndirect = totalCascade - totalDirect;
    const activeItems = activeSeeds.map(id => lookup[id]).filter(Boolean);
    const maxDepth = activeItems.length > 0 ? Math.max(...activeItems.map(i => i.depth || 0)) : 0;
    const maxScore = activeItems.length > 0 ? Math.max(...activeItems.map(i => i.restorationScore || 0)) : 0;
    const prioritized = [...activeItems].sort((a, b) => (b.restorationScore || 0) - (a.restorationScore || 0));
    const depts = [...new Set(activeItems.map(i => i.dept))];
    // Naive sums computed on ACTIVE items (so dedup callout reflects what-if state)
    const naiveDirect = activeItems.reduce((s, i) => s + (i.direct || 0), 0);
    const naiveCascade = activeItems.reduce((s, i) => s + (i.total || 0), 0);
    // Baseline (all items as disrupted) — for the what-if comparison
    const baseline = computeCascade(scenario);
    return {
      totalDirect, totalIndirect, totalCascade,
      naiveDirect, naiveCascade,
      maxDepth, maxScore, prioritized, depts,
      directIds: [...cascade.direct],
      cascadeIds: [...cascade.totalCascade],
      byDepth: cascade.byDepth,
      activeCount: activeSeeds.length,
      baselineDirect: baseline.direct.size,
      baselineCascade: baseline.totalCascade.size,
    };
  }, [items, scenario, activeSeeds]);

  return (
    <>
      <TopNav
        back={onBack}
        title="Scenario Builder"
        sub={DST_CONFIG.org.homeTitle}
        scenarioCount={scenario.length}
        action={items.length > 0 ? (
          <button onClick={onClear} style={{
            background: 'transparent', border: `1px solid ${T.critical}`,
            color: T.critical, padding: '5px 8px', cursor: 'pointer',
            fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 700,
            letterSpacing: '0.08em', textTransform: 'uppercase',
            display: 'inline-flex', alignItems: 'center', gap: 4,
          }}>
            <Trash2 size={11} strokeWidth={2}/> Clear
          </button>
        ) : null}
      />
      {/* Scenario name strip — only when scenario has assets */}
      {items.length > 0 && (
        <div style={{
          padding: '10px 16px',
          background: T.surfaceAlt, borderBottom: `1px solid ${T.rule}`,
        }}>
          <div style={{
            fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 700,
            letterSpacing: '0.14em', textTransform: 'uppercase', color: T.ink3,
            marginBottom: 3,
          }}>Scenario Name</div>
          {editingName ? (
            <div style={{ display: 'flex', gap: 6, alignItems: 'center' }}>
              <input
                value={nameDraft}
                onChange={e => setNameDraft(e.target.value)}
                onBlur={() => {
                  const next = nameDraft.trim() || 'Untitled Scenario';
                  onSetScenarioName(next);
                  setEditingName(false);
                }}
                onKeyDown={e => {
                  if (e.key === 'Enter') {
                    const next = nameDraft.trim() || 'Untitled Scenario';
                    onSetScenarioName(next);
                    setEditingName(false);
                  } else if (e.key === 'Escape') {
                    setNameDraft(scenarioName || '');
                    setEditingName(false);
                  }
                }}
                autoFocus
                placeholder="Untitled Scenario"
                style={{
                  flex: 1, padding: '6px 10px',
                  border: `1.5px solid ${T.darkBlue}`, outline: 'none',
                  fontFamily: '"Zilla Slab", serif', fontSize: 16, fontWeight: 600,
                  color: T.darkBlue, background: '#fff',
                }}/>
              <button onClick={() => {
                const next = nameDraft.trim() || 'Untitled Scenario';
                onSetScenarioName(next);
                setEditingName(false);
              }} style={{
                padding: '6px 10px', background: T.teal, color: '#fff', border: 'none',
                cursor: 'pointer', fontFamily: 'Poppins, sans-serif',
                fontSize: 10, fontWeight: 700, letterSpacing: '0.08em',
              }}>SAVE</button>
            </div>
          ) : (
            <div style={{
              display: 'flex', alignItems: 'center', gap: 8,
            }}>
              <div style={{
                flex: 1, minWidth: 0,
                fontFamily: '"Zilla Slab", serif', fontSize: 17, fontWeight: 600,
                color: T.darkBlue, letterSpacing: '-0.005em', lineHeight: 1.2,
                overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
              }}>{scenarioName || 'Untitled Scenario'}</div>
              <button onClick={() => {
                setNameDraft(scenarioName === 'Untitled Scenario' ? '' : (scenarioName || ''));
                setEditingName(true);
              }} style={{
                background: 'transparent', border: 'none', cursor: 'pointer',
                color: T.teal, padding: 0,
                fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 700,
                letterSpacing: '0.1em', textTransform: 'uppercase',
              }}>Rename</button>
            </div>
          )}
        </div>
      )}
      <div style={{ padding: '14px 16px 24px' }}>
        {/* Empty state */}
        {items.length === 0 && (
          <>
            <div style={{
              padding: '32px 20px', textAlign: 'center',
              border: `2px dashed ${T.rule}`, background: T.surfaceAlt,
              marginBottom: 16,
            }}>
              <ClipboardList size={36} color={T.darkBlue} strokeWidth={1.25} style={{ marginBottom: 12 }}/>
              <div style={{
                fontFamily: '"Zilla Slab", serif', fontSize: 18, fontWeight: 600,
                color: T.darkBlue, marginBottom: 6, letterSpacing: '-0.01em',
              }}>No scenario yet</div>
              <div style={{
                fontFamily: 'Poppins, sans-serif', fontSize: 13, color: T.ink2,
                lineHeight: 1.5, fontWeight: 400, maxWidth: 280, margin: '0 auto',
              }}>
                Add affected processes, systems, or facilities to model a multi-disruption event
                and see prioritized actions.
              </div>
            </div>
            <button onClick={onAddNew} style={{
              width: '100%', padding: '14px',
              fontFamily: 'Poppins, sans-serif', fontSize: 11, fontWeight: 700,
              letterSpacing: '0.12em', textTransform: 'uppercase',
              background: T.darkBlue, color: '#fff', border: 'none', cursor: 'pointer',
              display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: 8,
            }}>
              <Plus size={14}/> Browse Assets to Add
            </button>
            {/* Load existing — visible whenever saved scenarios exist */}
            {savedScenarios.length > 0 && (
              <button onClick={onOpenMyScenarios} style={{
                width: '100%', marginTop: 8, padding: '12px',
                fontFamily: 'Poppins, sans-serif', fontSize: 11, fontWeight: 700,
                letterSpacing: '0.12em', textTransform: 'uppercase',
                background: 'transparent', color: T.darkBlue,
                border: `2px solid ${T.darkBlue}`, cursor: 'pointer',
                display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: 8,
              }}>
                <ClipboardList size={14}/> Load Saved Scenario
                <span style={{
                  padding: '1px 7px', background: T.teal, color: '#fff',
                  fontSize: 9, fontWeight: 700, marginLeft: 2,
                }}>{savedScenarios.length}</span>
              </button>
            )}
          </>
        )}

        {/* Active scenario */}
        {items.length > 0 && stats && (
          <>
            {/* Aggregate stats — 4 tiles */}
            <div style={{
              fontFamily: 'Poppins, sans-serif', fontSize: 10, color: T.ink3,
              letterSpacing: '0.16em', textTransform: 'uppercase',
              marginBottom: 8, fontWeight: 700,
            }}>Scenario Summary</div>

            <div style={{
              display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: 8, marginBottom: 10,
            }}>
              <StatTile label="Assets Affected" value={items.length} accent />
              <StatTile label="Departments" value={stats.depts.length} />
              <StatTile
                label="Direct Downstream"
                value={stats.totalDirect}
                sublabel={stats.naiveDirect > stats.totalDirect ? `Deduped from ${stats.naiveDirect}` : 'No overlap'}
                onTap={() => onOpenCascade('direct')}
              />
              <StatTile
                label="Total Cascade"
                value={stats.totalCascade}
                sublabel={stats.naiveCascade > stats.totalCascade ? `Deduped from ${stats.naiveCascade}` : 'No overlap'}
                onTap={() => onOpenCascade('cascade')}
              />
            </div>

            {/* Departments touched — moved up directly below scenario summary */}
            <div style={{
              padding: '10px 12px', background: T.surfaceAlt, border: `1px solid ${T.rule}`,
              marginBottom: 12,
            }}>
              <div style={{
                fontFamily: 'Poppins, sans-serif', fontSize: 9, color: T.ink3,
                letterSpacing: '0.12em', textTransform: 'uppercase', fontWeight: 700, marginBottom: 6,
              }}>Departments Touched</div>
              <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6 }}>
                {stats.depts.map(d => <DeptChip key={d} name={d} />)}
              </div>
            </div>

            {/* Quick-access action buttons: Critical Questions + Initial Actions
                These give users actionable response guidance without needing to
                generate a full report. Mirrors the report content. */}
            <div style={{
              display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8, marginBottom: 18,
            }}>
              <button onClick={() => setQuestionsOpen(true)} style={{
                padding: '10px 8px',
                fontFamily: 'Poppins, sans-serif', fontSize: 10, fontWeight: 700,
                letterSpacing: '0.08em', textTransform: 'uppercase',
                background: T.surface, color: T.darkBlue,
                border: `1.5px solid ${T.darkBlue}`, cursor: 'pointer',
                display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: 6,
                lineHeight: 1.2,
              }}>
                <Info size={13}/> Critical Questions
                <span style={{
                  padding: '1px 6px', background: T.darkBlue, color: '#fff',
                  fontSize: 9, fontWeight: 700,
                }}>{CRITICAL_QUESTIONS.length}</span>
              </button>
              <button onClick={() => setActionsOpen(true)} style={{
                padding: '10px 8px',
                fontFamily: 'Poppins, sans-serif', fontSize: 10, fontWeight: 700,
                letterSpacing: '0.08em', textTransform: 'uppercase',
                background: T.surface, color: T.teal,
                border: `1.5px solid ${T.teal}`, cursor: 'pointer',
                display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: 6,
                lineHeight: 1.2,
              }}>
                <ClipboardList size={13}/> Initial Actions
                {scenarioInitialActions.length > 0 && (
                  <span style={{
                    padding: '1px 6px', background: T.teal, color: '#fff',
                    fontSize: 9, fontWeight: 700,
                  }}>{scenarioInitialActions.length}</span>
                )}
              </button>
            </div>

            {/* What-if controls header */}
            <div style={{
              display: 'flex', justifyContent: 'space-between', alignItems: 'baseline',
              marginBottom: 4,
            }}>
              <span style={{
                fontFamily: 'Poppins, sans-serif', fontSize: 10, color: T.ink3,
                letterSpacing: '0.16em', textTransform: 'uppercase', fontWeight: 700,
              }}>What-If Analysis</span>
              {whatIfActive && (
                <button onClick={onResetStates} style={{
                  background: 'transparent', border: `1px solid ${T.rule}`,
                  color: T.ink2, padding: '4px 8px', cursor: 'pointer',
                  fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 700,
                  letterSpacing: '0.08em', textTransform: 'uppercase',
                }}>Reset All</button>
              )}
            </div>
            <div style={{
              fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink2,
              fontStyle: 'italic', marginBottom: 12, fontWeight: 400, lineHeight: 1.4,
            }}>Tap an item's state chip to choose its current state — Disrupted, Being Fixed, Manual Ops, or Unable to Repair.</div>

            {/* Section: DISRUPTED */}
            {itemsByState.disrupted.length > 0 && (
              <ScenarioSection
                state="disrupted"
                items={itemsByState.disrupted}
                onCycleState={onCycleState}
                onSetState={onSetState}
                onRemove={onRemove}
                onOpen={onOpen}
                showRank
                rankStartAt={1}
              />
            )}

            {/* Section: UNABLE TO REPAIR */}
            {itemsByState.unable.length > 0 && (
              <ScenarioSection
                state="unable"
                items={itemsByState.unable}
                onCycleState={onCycleState}
                onSetState={onSetState}
                onRemove={onRemove}
                onOpen={onOpen}
                showRank
                rankStartAt={itemsByState.disrupted.length + 1}
              />
            )}

            {/* Section: MANUAL OPS — moved out of active cascade */}
            {itemsByState.manual.length > 0 && (
              <ScenarioSection
                state="manual"
                items={itemsByState.manual}
                onCycleState={onCycleState}
                onSetState={onSetState}
                onRemove={onRemove}
                onOpen={onOpen}
              />
            )}

            {/* Section: BEING FIXED — moved out of active cascade */}
            {itemsByState.fixing.length > 0 && (
              <ScenarioSection
                state="fixing"
                items={itemsByState.fixing}
                onCycleState={onCycleState}
                onSetState={onSetState}
                onRemove={onRemove}
                onOpen={onOpen}
              />
            )}

            {/* Empty active cascade callout */}
            {stats.activeCount === 0 && (
              <div style={{
                marginTop: 12, padding: '14px 16px',
                background: T.lowSoft, border: `1px solid ${T.low}`,
                fontFamily: 'Poppins, sans-serif', fontSize: 12, color: T.ink,
                lineHeight: 1.5,
              }}>
                <strong style={{ color: T.low, fontFamily: '"Zilla Slab", serif', fontSize: 14 }}>Hypothetical clear.</strong> Every
                scenario asset is being fixed or running on manual ops. The active cascade is empty in this
                what-if scenario.
              </div>
            )}

            {/* Add more */}
            <button onClick={onAddNew} style={{
              width: '100%', marginTop: 16, padding: '12px',
              fontFamily: 'Poppins, sans-serif', fontSize: 11, fontWeight: 700,
              letterSpacing: '0.12em', textTransform: 'uppercase',
              background: 'transparent', color: T.darkBlue,
              border: `2px solid ${T.darkBlue}`, cursor: 'pointer',
              display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: 6,
            }}>
              <Plus size={14}/> Add More Assets
            </button>

            {/* View / Add Notes */}
            <button onClick={onOpenNotes} style={{
              width: '100%', marginTop: 8, padding: '12px',
              fontFamily: 'Poppins, sans-serif', fontSize: 11, fontWeight: 700,
              letterSpacing: '0.12em', textTransform: 'uppercase',
              background: 'transparent', color: T.darkBlue,
              border: `2px solid ${T.lightTeal}`, cursor: 'pointer',
              display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: 6,
            }}>
              <FileText size={14}/>
              {scenarioNotes.length > 0 ? 'View / Add Notes' : 'Add Notes'}
              {scenarioNotes.length > 0 && (
                <span style={{
                  padding: '1px 7px', background: T.teal, color: '#fff',
                  fontSize: 9, fontWeight: 700, marginLeft: 2,
                }}>{scenarioNotes.length}</span>
              )}
            </button>

            {/* Generate Report */}
            <button onClick={onGenerateReport} style={{
              width: '100%', marginTop: 8, padding: '12px',
              fontFamily: 'Poppins, sans-serif', fontSize: 11, fontWeight: 700,
              letterSpacing: '0.12em', textTransform: 'uppercase',
              background: 'transparent', color: T.teal,
              border: `2px solid ${T.teal}`, cursor: 'pointer',
              display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: 6,
            }}>
              <FileText size={14}/> Generate Report
            </button>

            {/* Save / My Scenarios — side by side */}
            <div style={{
              display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8, marginTop: 8,
            }}>
              <button onClick={() => {
                setSaveName(scenarioName && scenarioName !== 'Untitled Scenario' ? scenarioName : '');
                setSaveOverwriteId(null);
                setSaveOpen(true);
              }} style={{
                padding: '12px',
                fontFamily: 'Poppins, sans-serif', fontSize: 10.5, fontWeight: 700,
                letterSpacing: '0.1em', textTransform: 'uppercase',
                background: T.darkBlue, color: '#fff',
                border: `2px solid ${T.darkBlue}`, cursor: 'pointer',
                display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: 6,
              }}>
                <Check size={13}/> Save
              </button>
              <button onClick={onOpenMyScenarios} style={{
                padding: '12px',
                fontFamily: 'Poppins, sans-serif', fontSize: 10.5, fontWeight: 700,
                letterSpacing: '0.1em', textTransform: 'uppercase',
                background: 'transparent', color: T.darkBlue,
                border: `2px solid ${T.darkBlue}`, cursor: 'pointer',
                display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: 6,
              }}>
                <ClipboardList size={13}/> My Scenarios
                {savedScenarios.length > 0 && (
                  <span style={{
                    padding: '1px 6px', background: T.teal, color: '#fff',
                    fontSize: 9, fontWeight: 700, marginLeft: 2,
                  }}>{savedScenarios.length}</span>
                )}
              </button>
            </div>

            {/* Saved-flash confirmation */}
            {savedFlash && (
              <div style={{
                marginTop: 10, padding: '8px 12px',
                background: T.lowSoft, border: `1px solid ${T.low}`,
                fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink,
                display: 'flex', alignItems: 'center', gap: 6,
              }}>
                <Check size={13} color={T.low} strokeWidth={2.5}/>
                Scenario saved.
              </div>
            )}

          </>
        )}
      </div>

      {/* Save sheet */}
      <Sheet open={saveOpen} onClose={() => setSaveOpen(false)} title="Save Scenario">
        <div style={{
          padding: '10px 12px', background: T.surfaceAlt, border: `1px solid ${T.lightTeal}`,
          marginBottom: 16,
        }}>
          <div style={{
            fontFamily: 'Poppins, sans-serif', fontSize: 9, color: T.ink3,
            letterSpacing: '0.1em', textTransform: 'uppercase', fontWeight: 600,
            marginBottom: 2,
          }}>Saving</div>
          <div style={{
            fontFamily: 'Poppins, sans-serif', fontSize: 12, color: T.ink, lineHeight: 1.4,
          }}>{items.length} {items.length === 1 ? 'asset' : 'assets'} · {Object.values(scenarioStates).some(s => s && s !== 'disrupted') ? 'with what-if states' : 'baseline state'}</div>
        </div>

        <div style={{
          fontFamily: 'Poppins, sans-serif', fontSize: 10, color: T.ink3,
          letterSpacing: '0.14em', textTransform: 'uppercase', fontWeight: 700,
          marginBottom: 6,
        }}>Scenario Name</div>
        <input
          value={saveName}
          onChange={e => setSaveName(e.target.value)}
          placeholder="e.g., Cyber outage — Tidalis impact"
          autoFocus
          style={{
            width: '100%', padding: '10px 12px', marginBottom: 14,
            fontFamily: '"Zilla Slab", serif', fontSize: 16, fontWeight: 600,
            color: T.darkBlue, border: `1.5px solid ${T.rule}`, outline: 'none',
            boxSizing: 'border-box',
          }}/>

        {/* If existing scenarios match this name, offer overwrite */}
        {savedScenarios.length > 0 && (
          <>
            <div style={{
              fontFamily: 'Poppins, sans-serif', fontSize: 10, color: T.ink3,
              letterSpacing: '0.14em', textTransform: 'uppercase', fontWeight: 700,
              marginBottom: 6,
            }}>Or overwrite an existing</div>
            <div style={{ marginBottom: 14 }}>
              {savedScenarios.map(s => (
                <button key={s.id}
                  onClick={() => { setSaveOverwriteId(s.id); setSaveName(s.name); }}
                  style={{
                    width: '100%', display: 'flex', alignItems: 'center', gap: 10,
                    padding: '10px 12px', marginBottom: 6,
                    background: saveOverwriteId === s.id ? T.surfaceAlt : T.surface,
                    border: `1.5px solid ${saveOverwriteId === s.id ? T.darkBlue : T.rule}`,
                    cursor: 'pointer', textAlign: 'left', fontFamily: 'inherit',
                  }}>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{
                      fontFamily: '"Zilla Slab", serif', fontSize: 13, fontWeight: 600,
                      color: T.darkBlue, lineHeight: 1.2,
                      overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
                    }}>{s.name}</div>
                    <div style={{
                      fontFamily: 'Poppins, sans-serif', fontSize: 10, color: T.ink3,
                      marginTop: 2,
                    }}>{s.scenario.length} assets · saved {formatRelativeDate(s.updated)}</div>
                  </div>
                  {saveOverwriteId === s.id && <Check size={14} color={T.darkBlue} strokeWidth={3}/>}
                </button>
              ))}
            </div>
          </>
        )}

        <div style={{ display: 'flex', gap: 8 }}>
          <button onClick={() => setSaveOpen(false)} style={{
            flex: 1, padding: '12px', background: 'transparent', color: T.ink2,
            border: `1.5px solid ${T.rule}`, cursor: 'pointer',
            fontFamily: 'Poppins, sans-serif', fontSize: 11, fontWeight: 700,
            letterSpacing: '0.1em', textTransform: 'uppercase',
          }}>Cancel</button>
          <button
            onClick={() => {
              onSaveScenario(saveName, saveOverwriteId);
              setSaveOpen(false);
              setSavedFlash(true);
              setTimeout(() => setSavedFlash(false), 2400);
            }}
            disabled={!saveName.trim()}
            style={{
              flex: 1, padding: '12px',
              background: saveName.trim() ? T.darkBlue : T.rule,
              color: '#fff', border: 'none',
              cursor: saveName.trim() ? 'pointer' : 'not-allowed',
              fontFamily: 'Poppins, sans-serif', fontSize: 11, fontWeight: 700,
              letterSpacing: '0.1em', textTransform: 'uppercase',
            }}>{saveOverwriteId ? 'Overwrite' : 'Save'}</button>
        </div>
      </Sheet>

      {/* CRITICAL QUESTIONS sheet — static reference list, mirrors report content */}
      <Sheet open={questionsOpen} onClose={() => setQuestionsOpen(false)} title="Critical Questions">
        <div style={{ padding: '0 4px 4px' }}>
          <p style={{
            fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink2,
            fontStyle: 'italic', margin: '0 0 14px 0', lineHeight: 1.45,
          }}>Use to ground situational awareness in the operational environment. Consider asking these for any active scenario.</p>
          <div style={{
            background: T.surface, border: `1px solid ${T.rule}`,
          }}>
            {CRITICAL_QUESTIONS.map((q, i) => (
              <div key={i} style={{
                padding: '11px 12px',
                borderBottom: i < CRITICAL_QUESTIONS.length - 1 ? `1px solid ${T.ruleSoft}` : 'none',
                display: 'flex', gap: 10, alignItems: 'flex-start',
              }}>
                <span style={{
                  fontFamily: '"Zilla Slab", serif', fontSize: 14, fontWeight: 700,
                  color: T.teal, minWidth: 22, lineHeight: 1.3,
                }}>{String(i + 1).padStart(2, '0')}</span>
                <span style={{
                  fontFamily: 'Poppins, sans-serif', fontSize: 12, color: T.ink,
                  lineHeight: 1.45,
                }}>{q}</span>
              </div>
            ))}
          </div>
        </div>
      </Sheet>

      {/* INITIAL ACTIONS sheet — dynamic, top short-term step per scenario asset */}
      <Sheet open={actionsOpen} onClose={() => setActionsOpen(false)} title="Initial Actions">
        <div style={{ padding: '0 4px 4px' }}>
          {scenarioInitialActions.length === 0 ? (
            <div style={{
              padding: '24px 16px', textAlign: 'center',
              background: T.surface, border: `1px solid ${T.rule}`,
              fontFamily: 'Poppins, sans-serif', fontSize: 12, color: T.ink2,
              lineHeight: 1.5,
            }}>
              No assets in scenario yet. Add at least one asset to see initial actions.
            </div>
          ) : (
            <>
              <p style={{
                fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink2,
                fontStyle: 'italic', margin: '0 0 14px 0', lineHeight: 1.45,
              }}>Top short-term action for each asset, ordered by Restoration Score. Use these as your starting point.</p>
              {scenarioInitialActions.map((a, i) => {
                const meta = STATE_META[a.state];
                return (
                  <div key={a.assetId} style={{
                    padding: '10px 12px', marginBottom: 8,
                    background: T.surface, border: `1px solid ${T.rule}`,
                    borderLeft: `4px solid ${meta.accent}`,
                  }}>
                    <div style={{
                      display: 'flex', alignItems: 'center', gap: 8, marginBottom: 6,
                      flexWrap: 'wrap',
                    }}>
                      <span style={{
                        fontFamily: '"Zilla Slab", serif', fontSize: 14, fontWeight: 700,
                        color: T.teal, minWidth: 22,
                      }}>{String(i + 1).padStart(2, '0')}</span>
                      <span style={{
                        fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 700,
                        color: T.ink3, letterSpacing: '0.06em', textTransform: 'uppercase',
                      }}>{a.assetType} {String.fromCharCode(183)} {a.assetId}</span>
                      <span style={{
                        padding: '1px 6px', background: meta.color, color: '#fff',
                        fontFamily: 'Poppins, sans-serif', fontSize: 8, fontWeight: 700,
                        letterSpacing: '0.08em',
                      }}>{meta.short}</span>
                    </div>
                    <div style={{
                      fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink2, fontWeight: 500,
                      marginBottom: 4,
                    }}>{a.assetName}</div>
                    <div style={{
                      fontFamily: '"Zilla Slab", serif', fontSize: 14, fontWeight: 600,
                      color: T.darkBlue, lineHeight: 1.25, marginBottom: 6,
                    }}>{a.head}</div>
                    {a.body && a.body.length > 0 && (
                      <ul style={{
                        listStyle: 'none', padding: 0, margin: 0,
                      }}>
                        {a.body.map((b, bi) => (
                          <li key={bi} style={{
                            display: 'flex', gap: 8, padding: '3px 0',
                            fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink,
                            lineHeight: 1.45,
                          }}>
                            <span style={{ color: T.teal, fontWeight: 700 }}>{String.fromCharCode(8250)}</span>
                            <span>{b}</span>
                          </li>
                        ))}
                      </ul>
                    )}
                  </div>
                );
              })}
              <div style={{
                marginTop: 8, padding: '8px 10px',
                background: T.surfaceAlt, border: `1px solid ${T.lightTeal}`,
                fontFamily: 'Poppins, sans-serif', fontSize: 10, color: T.ink2,
                lineHeight: 1.45,
              }}>
                For the full short-term action list per asset, generate the report.
              </div>
            </>
          )}
        </div>
      </Sheet>

      <BottomNav onPrevious={onBack} onHome={onHome} />
    </>
  );
}

/* ============================================================================
   CASCADE LIST SCREEN — drill-down from Scenario Builder's Direct or Total tiles
   ============================================================================ */

function CascadeListScreen({ scenario, scenarioStates = {}, mode, onBack, onOpen, onHome, scenarioCount, onScenarioTap }) {
  const [query, setQuery] = useState('');
  const [sortBy, setSortBy] = useState('score');
  const [deptFilter, setDeptFilter] = useState('All');
  const [deptOpen, setDeptOpen] = useState(false);
  // Tree view state — only meaningful for 'cascade' mode
  const [viewMode, setViewMode] = useState('list'); // 'list' | 'tree'
  // Tree expansion: Set of "seedId:nodeId:depth" path keys that are open
  const [expanded, setExpanded] = useState(new Set());

  // Active seeds = items whose state is in-cascade (Disrupted + Unable to Repair)
  const activeSeeds = useMemo(() =>
    scenario.filter(id => {
      const s = scenarioStates[id] || 'disrupted';
      return STATE_META[s] && STATE_META[s].inCascade;
    }),
  [scenario, scenarioStates]);

  // Detect whether what-if state has been applied
  const whatIfActive = useMemo(() =>
    Object.values(scenarioStates).some(s => s && s !== 'disrupted'),
  [scenarioStates]);

  // Build the per-seed trees from active seeds (memoized)
  const trees = useMemo(() => buildCascadeTree(activeSeeds), [activeSeeds]);
  const seedSet = useMemo(() => new Set(activeSeeds), [activeSeeds]);

  // Compute the cascade for active seeds
  const { cascadeData, allItems } = useMemo(() => {
    const cascade = computeCascade(activeSeeds);
    const ids = mode === 'direct' ? [...cascade.direct] : [...cascade.totalCascade];
    const items = ids.map(id => {
      const detail = getCascadeItem(id);
      const depth = cascade.byDepth.get(id) || 1;
      return detail ? { id, ...detail, depth } : null;
    }).filter(Boolean);
    return { cascadeData: cascade, allItems: items };
  }, [activeSeeds, mode]);

  const depts = useMemo(() => ['All', ...new Set(allItems.map(i => i.dept).filter(Boolean))].sort(), [allItems]);

  const filtered = useMemo(() => {
    let r = allItems;
    if (query) {
      const q = query.toLowerCase();
      r = r.filter(i => (i.name || '').toLowerCase().includes(q));
    }
    if (deptFilter !== 'All') r = r.filter(i => i.dept === deptFilter);
    r = [...r];
    if (sortBy === 'score') r.sort((a, b) => (b.score || 0) - (a.score || 0));
    if (sortBy === 'name')  r.sort((a, b) => (a.name || '').localeCompare(b.name || ''));
    if (sortBy === 'dept')  r.sort((a, b) => (a.dept || '').localeCompare(b.dept || ''));
    if (sortBy === 'depth') r.sort((a, b) => (a.depth || 0) - (b.depth || 0));
    if (sortBy === 'type')  r.sort((a, b) => (a.type || '').localeCompare(b.type || ''));
    return r;
  }, [allItems, query, sortBy, deptFilter]);

  const title = mode === 'direct' ? 'Direct Downstream' : 'Total Cascade';
  const subtitle = mode === 'direct'
    ? 'First-level dependencies of the disrupted assets'
    : 'All downstream items, deduplicated';

  return (
    <>
      <TopNav back={onBack} title={title} sub="Scenario Cascade"
        scenarioCount={scenarioCount} onScenarioTap={onScenarioTap} />
      <div style={{ padding: '12px 16px 20px' }}>
        {/* Context banner */}
        <div style={{
          padding: '10px 12px', background: T.surfaceAlt, border: `1px solid ${T.lightTeal}`,
          marginBottom: 12,
        }}>
          <div style={{
            fontFamily: 'Poppins, sans-serif', fontSize: 9, color: T.darkBlue,
            letterSpacing: '0.12em', textTransform: 'uppercase', fontWeight: 700,
            marginBottom: 3,
          }}>{subtitle}</div>
          <div style={{
            fontFamily: 'Poppins, sans-serif', fontSize: 12, color: T.ink, lineHeight: 1.45,
          }}>
            {allItems.length} unique {allItems.length === 1 ? 'item' : 'items'} affected by the
            current {activeSeeds.length}-asset {whatIfActive ? 'what-if scenario' : 'scenario'}
            {whatIfActive && scenario.length > activeSeeds.length && (
              <span style={{ color: T.ink2 }}>
                {' '}({scenario.length - activeSeeds.length} excluded via what-if)
              </span>
            )}.
          </div>
          {whatIfActive && (
            <div style={{
              marginTop: 8, padding: '6px 10px',
              background: '#fff', border: `1px solid ${T.teal}`,
              fontFamily: 'Poppins, sans-serif', fontSize: 10.5, color: T.darkBlue,
              fontWeight: 600, letterSpacing: '0.04em',
              display: 'inline-flex', alignItems: 'center', gap: 6,
            }}>
              <Cog size={11} strokeWidth={2.25}/>
              WHAT-IF ACTIVE
            </div>
          )}
        </div>

        {/* View toggle — List / Tree (only meaningful for cascade mode) */}
        {mode === 'cascade' && (
          <div style={{
            display: 'flex', justifyContent: 'space-between', alignItems: 'center',
            marginBottom: 12, gap: 10,
          }}>
            <div style={{
              display: 'inline-flex', border: `1px solid ${T.rule}`, background: T.surface,
            }}>
              {[
                { k: 'list', label: 'List' },
                { k: 'tree', label: 'Tree' },
              ].map(({ k, label }) => (
                <button key={k} onClick={() => setViewMode(k)} style={{
                  padding: '7px 16px', border: 'none', cursor: 'pointer',
                  fontFamily: 'Poppins, sans-serif', fontSize: 10, fontWeight: 600,
                  letterSpacing: '0.08em', textTransform: 'uppercase',
                  background: viewMode === k ? T.darkBlue : 'transparent',
                  color: viewMode === k ? '#fff' : T.ink2,
                }}>{label}</button>
              ))}
            </div>
            {viewMode === 'tree' && (
              <div style={{ display: 'flex', gap: 6 }}>
                <button onClick={() => {
                  // Expand all
                  const all = new Set();
                  function walk(node, parentPath) {
                    const key = `${parentPath}:${node.id}`;
                    if (node.children && node.children.length > 0) {
                      all.add(key);
                      for (const ch of node.children) walk(ch, key);
                    }
                  }
                  for (const tree of trees) walk(tree, 'root');
                  setExpanded(all);
                }} style={{
                  padding: '6px 10px', background: 'transparent', cursor: 'pointer',
                  border: `1px solid ${T.rule}`, color: T.ink2,
                  fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 700,
                  letterSpacing: '0.08em', textTransform: 'uppercase',
                }}>Expand All</button>
                <button onClick={() => setExpanded(new Set())} style={{
                  padding: '6px 10px', background: 'transparent', cursor: 'pointer',
                  border: `1px solid ${T.rule}`, color: T.ink2,
                  fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 700,
                  letterSpacing: '0.08em', textTransform: 'uppercase',
                }}>Collapse</button>
              </div>
            )}
          </div>
        )}

        {/* List view controls (search, sort, filter) — hide when in tree view */}
        {viewMode === 'list' && (
          <>
        {/* Search */}
        <div style={{
          display: 'flex', alignItems: 'center', gap: 8, padding: '8px 12px',
          border: `1px solid ${T.rule}`, background: T.surface, marginBottom: 10,
        }}>
          <Search size={14} color={T.ink3}/>
          <input value={query} onChange={e => setQuery(e.target.value)}
            placeholder="Search…"
            style={{
              border: 'none', outline: 'none', flex: 1,
              fontFamily: 'Poppins, sans-serif', fontSize: 13,
              color: T.ink, background: 'transparent',
            }}/>
          {query && <button onClick={() => setQuery('')} style={{
            background: 'none', border: 'none', cursor: 'pointer',
            color: T.ink3, padding: 0, display: 'inline-flex',
          }}><X size={14}/></button>}
        </div>

        {/* Sort + Dept */}
        <div style={{ display: 'flex', justifyContent: 'space-between', gap: 8, marginBottom: 10 }}>
          <div style={{
            display: 'inline-flex', border: `1px solid ${T.rule}`, background: T.surface,
            overflowX: 'auto', maxWidth: 'calc(100% - 92px)',
          }}>
            {[
              { k: 'score', label: 'Score' },
              { k: 'name',  label: 'A–Z' },
              { k: 'dept',  label: 'Dept' },
              { k: 'type',  label: 'Type' },
              ...(mode === 'cascade' ? [{ k: 'depth', label: 'Depth' }] : []),
            ].map(({ k, label }) => (
              <button key={k} onClick={() => setSortBy(k)} style={{
                padding: '7px 11px', border: 'none', cursor: 'pointer',
                fontFamily: 'Poppins, sans-serif', fontSize: 10, fontWeight: 600,
                letterSpacing: '0.08em', textTransform: 'uppercase',
                background: sortBy === k ? T.darkBlue : 'transparent',
                color: sortBy === k ? '#fff' : T.ink2, flexShrink: 0,
              }}>{label}</button>
            ))}
          </div>
          <div style={{ position: 'relative' }}>
            <button onClick={() => setDeptOpen(o => !o)} style={{
              padding: '7px 10px', border: `1px solid ${T.rule}`,
              background: T.surface, color: T.ink, cursor: 'pointer',
              fontFamily: 'Poppins, sans-serif', fontSize: 11, fontWeight: 500,
              display: 'inline-flex', alignItems: 'center', gap: 5,
              maxWidth: 90,
            }}>
              <span style={{ fontWeight: 600, fontSize: 9, letterSpacing: '0.08em', textTransform: 'uppercase', color: T.ink3 }}>Dept</span>
              <ChevronDown size={11}/>
            </button>
            {deptOpen && (
              <div style={{
                position: 'absolute', top: '100%', right: 0, marginTop: 4,
                background: T.surface, border: `1px solid ${T.rule}`,
                minWidth: 220, maxHeight: 280, overflowY: 'auto', zIndex: 30,
                boxShadow: '0 8px 24px rgba(14,30,51,0.12)',
              }}>
                {depts.map(d => (
                  <button key={d} onClick={() => { setDeptFilter(d); setDeptOpen(false); }} style={{
                    display: 'block', width: '100%', textAlign: 'left',
                    padding: '10px 14px', border: 'none', cursor: 'pointer',
                    background: deptFilter === d ? T.surfaceAlt : 'transparent',
                    fontFamily: 'Poppins, sans-serif', fontSize: 12, fontWeight: 500,
                    color: deptFilter === d ? T.darkBlue : T.ink, borderBottom: `1px solid ${T.ruleSoft}`,
                  }}>{d}</button>
                ))}
              </div>
            )}
          </div>
        </div>

        {/* Counter */}
        <div style={{
          padding: '4px 0 8px', borderBottom: `1px solid ${T.darkBlue}`,
          fontFamily: 'Poppins, sans-serif', fontSize: 10, color: T.ink3,
          letterSpacing: '0.1em', textTransform: 'uppercase', fontWeight: 600,
          display: 'flex', justifyContent: 'space-between',
        }}>
          <span>Showing {filtered.length} of {allItems.length}</span>
          {sortBy === 'score' && <span style={{ color: T.teal }}>Highest first</span>}
        </div>

        {/* List */}
        {filtered.map(item => {
          const linked = !!lookup[item.id];
          const depthBadge = mode === 'cascade' && (
            <span style={{
              padding: '2px 6px', background: T.surfaceAlt,
              border: `1px solid ${T.rule}`, color: T.ink2,
              fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 700,
              letterSpacing: '0.06em', flexShrink: 0,
            }}>L{item.depth}</span>
          );
          return (
            <button
              key={item.id}
              onClick={() => linked && onOpen(item.id)}
              disabled={!linked}
              style={{
                width: '100%', display: 'flex', gap: 12, alignItems: 'center',
                padding: '12px 6px', textAlign: 'left',
                cursor: linked ? 'pointer' : 'default',
                borderBottom: `1px solid ${T.ruleSoft}`,
                background: T.surface,
                border: 0, borderBottomWidth: 1, borderBottomStyle: 'solid',
                borderBottomColor: T.ruleSoft, fontFamily: 'inherit',
                opacity: linked ? 1 : 0.7,
              }}>
              <ScoreTile score={item.score || 0} type={item.type || 'Process'} small />
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{
                  fontFamily: 'Poppins, sans-serif', fontSize: 9, color: T.ink3,
                  letterSpacing: '0.04em', fontWeight: 600, marginBottom: 3,
                  textTransform: 'uppercase',
                  display: 'flex', gap: 6, alignItems: 'center',
                }}>
                  <span>{item.type || 'Item'} - {item.id}</span>
                  {depthBadge}
                </div>
                <div style={{
                  fontFamily: '"Zilla Slab", serif', fontSize: 13, fontWeight: 600,
                  color: T.darkBlue, letterSpacing: '-0.005em', lineHeight: 1.2,
                  marginBottom: 3,
                }}>{item.name}</div>
                {item.dept && <DeptChip name={item.dept} tiny />}
              </div>
              {linked
                ? <ChevronRight size={14} color={T.ink3}/>
                : <span style={{
                    fontFamily: 'Poppins, sans-serif', fontSize: 8, fontWeight: 700,
                    letterSpacing: '0.08em', textTransform: 'uppercase', color: T.ink3,
                  }}>Ref only</span>
              }
            </button>
          );
        })}
        {filtered.length === 0 && (
          <div style={{
            padding: 32, textAlign: 'center', fontFamily: 'Poppins, sans-serif',
            color: T.ink3, fontSize: 13,
          }}>No results.</div>
        )}
          </>
        )}

        {/* Tree view */}
        {mode === 'cascade' && viewMode === 'tree' && (
          <div>
            {trees.map((tree, idx) => (
              <CascadeTree
                key={tree.id}
                tree={tree}
                onOpen={onOpen}
                expanded={expanded}
                setExpanded={setExpanded}
                seedSet={seedSet}
                isLast={idx === trees.length - 1}
              />
            ))}
            <div style={{
              marginTop: 18, padding: '10px 14px',
              background: T.bgAlt, border: `1px dashed ${T.rule}`,
              fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink2, lineHeight: 1.5,
            }}>
              <strong style={{ color: T.darkBlue }}>Tree legend:</strong> Items marked
              <span style={{
                margin: '0 4px', padding: '1px 6px',
                background: T.surfaceAlt, border: `1px solid ${T.rule}`,
                fontSize: 9, fontWeight: 700, letterSpacing: '0.06em',
                textTransform: 'uppercase',
              }}>Dup</span>
              appear elsewhere in this branch. Items marked
              <span style={{
                margin: '0 4px', padding: '1px 6px',
                background: T.teal, color: '#fff',
                fontSize: 9, fontWeight: 700, letterSpacing: '0.06em',
                textTransform: 'uppercase',
              }}>Seed</span>
              are also disrupted scenario assets — convergence points.
            </div>
          </div>
        )}
      </div>
      <BottomNav onPrevious={onBack} onHome={onHome}/>
    </>
  );
}

/* Recursive tree node renderer */
function CascadeTree({ tree, onOpen, expanded, setExpanded, seedSet, isLast }) {
  return (
    <div style={{
      marginBottom: isLast ? 0 : 14,
      paddingBottom: isLast ? 0 : 14,
      borderBottom: isLast ? 'none' : `1px dashed ${T.rule}`,
    }}>
      <CascadeNode
        node={tree}
        path="root"
        onOpen={onOpen}
        expanded={expanded}
        setExpanded={setExpanded}
        seedSet={seedSet}
      />
    </div>
  );
}

function CascadeNode({ node, path, onOpen, expanded, setExpanded, seedSet }) {
  const detail = getCascadeItem(node.id);
  if (!detail) return null;

  const myKey = `${path}:${node.id}`;
  const isOpen = expanded.has(myKey);
  const hasChildren = node.children && node.children.length > 0;
  const linked = !!lookup[node.id];
  const indent = node.depth * 16;
  const isSeedRow = node.depth === 0;

  const toggle = (e) => {
    e.stopPropagation();
    setExpanded(prev => {
      const next = new Set(prev);
      if (next.has(myKey)) next.delete(myKey);
      else next.add(myKey);
      return next;
    });
  };

  const navigate = () => {
    if (linked) onOpen(node.id);
  };

  // Score chip
  const scoreVal = detail.score || 0;
  const b = band(scoreVal, detail.type || 'Process');

  return (
    <>
      <div style={{
        display: 'flex', alignItems: 'stretch',
        position: 'relative',
        marginLeft: indent,
        background: isSeedRow ? T.surfaceAlt : 'transparent',
        borderLeft: isSeedRow ? `3px solid ${T.darkBlue}` : 'none',
      }}>
        {/* Connector line for non-seed rows */}
        {!isSeedRow && (
          <div style={{
            position: 'absolute', left: -8, top: 0, bottom: 0,
            width: 1, background: T.rule,
          }}/>
        )}
        {/* Toggle column */}
        <button
          onClick={hasChildren && !node.isDup ? toggle : undefined}
          disabled={!hasChildren || node.isDup}
          style={{
            background: 'transparent', border: 'none',
            cursor: (hasChildren && !node.isDup) ? 'pointer' : 'default',
            padding: '8px 4px 8px 8px',
            display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
            minWidth: 22,
          }}
        >
          {hasChildren && !node.isDup ? (
            isOpen
              ? <ChevronDown size={14} color={T.darkBlue} strokeWidth={2.5}/>
              : <ChevronRight size={14} color={T.darkBlue} strokeWidth={2.5}/>
          ) : (
            <span style={{ width: 14, height: 14, display: 'inline-block' }}/>
          )}
        </button>
        {/* Content row (tappable to navigate) */}
        <button
          onClick={navigate}
          disabled={!linked}
          style={{
            flex: 1, display: 'flex', alignItems: 'center', gap: 8,
            padding: '8px 6px 8px 4px', background: 'transparent',
            border: 'none', textAlign: 'left',
            cursor: linked ? 'pointer' : 'default',
            fontFamily: 'inherit',
            opacity: node.isDup ? 0.7 : 1,
          }}
        >
          {/* Type icon */}
          {(() => {
            const t = (detail.type || '').toLowerCase();
            const Icon = t === 'system' ? Server : t === 'facility' ? Building2 : Activity;
            return <Icon size={13} color={T.ink2} strokeWidth={1.75} style={{ flexShrink: 0 }}/>;
          })()}
          {/* ID + name */}
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{
              fontFamily: 'Poppins, sans-serif', fontSize: 8.5, fontWeight: 700,
              color: T.ink3, letterSpacing: '0.06em', textTransform: 'uppercase',
              marginBottom: 1,
              display: 'flex', gap: 5, alignItems: 'center', flexWrap: 'wrap',
            }}>
              <span>{detail.type || 'Item'} - {node.id}</span>
              {/* Badges */}
              {node.isSeed && !isSeedRow && (
                <span style={{
                  padding: '1px 5px', background: T.teal, color: '#fff',
                  fontSize: 7.5, fontWeight: 700, letterSpacing: '0.08em',
                }}>SEED</span>
              )}
              {node.isDup && (
                <span style={{
                  padding: '1px 5px', background: T.surfaceAlt,
                  border: `1px solid ${T.rule}`, color: T.ink2,
                  fontSize: 7.5, fontWeight: 700, letterSpacing: '0.08em',
                }}>DUP</span>
              )}
            </div>
            <div style={{
              fontFamily: '"Zilla Slab", serif',
              fontSize: isSeedRow ? 13 : 12, fontWeight: 600,
              color: T.darkBlue, letterSpacing: '-0.005em', lineHeight: 1.18,
              overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
            }}>{detail.name}</div>
          </div>
          {/* Tiny score chip */}
          {scoreVal > 0 && (
            <span style={{
              padding: '2px 6px', background: b.soft, color: b.color,
              fontFamily: '"Zilla Slab", serif', fontWeight: 700, fontSize: 11,
              minWidth: 26, textAlign: 'center', flexShrink: 0,
            }}>{scoreVal}</span>
          )}
          {/* Child count when collapsed */}
          {hasChildren && !node.isDup && !isOpen && (
            <span style={{
              fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 700,
              color: T.ink3, letterSpacing: '0.04em',
              padding: '2px 6px', background: T.bgAlt, flexShrink: 0,
            }}>{node.children.length}</span>
          )}
        </button>
      </div>
      {/* Children */}
      {isOpen && hasChildren && !node.isDup && node.children.map(child => (
        <CascadeNode
          key={`${myKey}-${child.id}-${child.depth}`}
          node={child}
          path={myKey}
          onOpen={onOpen}
          expanded={expanded}
          setExpanded={setExpanded}
          seedSet={seedSet}
        />
      ))}
    </>
  );
}

const StatTile = ({ label, value, accent, onTap, sublabel }) => {
  const inner = (
    <>
      <div style={{
        fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 700,
        letterSpacing: '0.12em', textTransform: 'uppercase',
        color: accent ? 'rgba(255,255,255,0.75)' : T.ink3, marginBottom: 4,
      }}>{label}</div>
      <div style={{
        display: 'flex', alignItems: 'baseline', justifyContent: 'space-between',
      }}>
        <div style={{
          fontFamily: '"Zilla Slab", serif', fontSize: 28, fontWeight: 700,
          color: accent ? '#fff' : T.darkBlue, lineHeight: 1, letterSpacing: '-0.02em',
        }}>{value}</div>
        {onTap && <ChevronRight size={14} color={accent ? '#fff' : T.teal} />}
      </div>
      {sublabel && (
        <div style={{
          marginTop: 6, fontFamily: 'Poppins, sans-serif', fontSize: 9.5, fontWeight: 500,
          color: accent ? 'rgba(255,255,255,0.7)' : T.ink3, lineHeight: 1.3,
        }}>{sublabel}</div>
      )}
    </>
  );
  const baseStyle = {
    padding: '14px 12px',
    background: accent ? T.darkBlue : T.surfaceAlt,
    border: `1px solid ${accent ? T.darkBlue : T.rule}`,
    color: accent ? '#fff' : T.ink,
    textAlign: 'left',
  };
  if (onTap) {
    return (
      <button onClick={onTap} style={{
        ...baseStyle, cursor: 'pointer', fontFamily: 'inherit', width: '100%',
      }}>{inner}</button>
    );
  }
  return <div style={baseStyle}>{inner}</div>;
};

/* ============================================================================
   SCENARIO SECTION — group of scenario items in the same what-if state
   ============================================================================ */

function ScenarioSection({ state, items, onCycleState, onSetState, onRemove, onOpen, showRank, rankStartAt = 1 }) {
  const meta = STATE_META[state];
  const isActive = meta.inCascade;
  const [pickerForId, setPickerForId] = useState(null);
  const pickerItem = pickerForId ? items.find(i => i.id === pickerForId) : null;
  const pickerCurrentState = pickerForId ? state : null;

  return (
    <div style={{ marginBottom: 14 }}>
      {/* Section header */}
      <div style={{
        display: 'flex', alignItems: 'center', gap: 8,
        paddingBottom: 6, marginBottom: 6,
        borderBottom: `2px solid ${meta.accent}`,
      }}>
        <div style={{
          width: 6, height: 18, background: meta.accent,
        }}/>
        <div style={{
          fontFamily: '"Zilla Slab", serif', fontSize: 14, fontWeight: 600,
          color: meta.color, letterSpacing: '-0.005em',
        }}>{meta.label}</div>
        <span style={{
          padding: '2px 7px', background: meta.soft, color: meta.color,
          fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 700,
          letterSpacing: '0.08em',
        }}>{items.length}</span>
        {!isActive && (
          <span style={{
            marginLeft: 'auto',
            fontFamily: 'Poppins, sans-serif', fontSize: 9, color: T.ink3,
            letterSpacing: '0.06em', fontStyle: 'italic',
          }}>excluded from cascade</span>
        )}
      </div>

      {/* Items */}
      {items.map((item, idx) => (
        <div key={item.id} style={{
          display: 'flex', gap: 10, alignItems: 'center',
          padding: '10px 4px', borderBottom: `1px solid ${T.ruleSoft}`,
          background: T.surface,
          opacity: isActive ? 1 : 0.78,
        }}>
          {showRank && (
            <div style={{
              fontFamily: '"Zilla Slab", serif', fontSize: 22, fontWeight: 700,
              color: meta.accent, lineHeight: 1, letterSpacing: '-0.02em', minWidth: 26,
            }}>{String(rankStartAt + idx).padStart(2, '0')}</div>
          )}
          <ScoreTile score={item.restorationScore} type={item.type} small />
          <div style={{
            flex: 1, minWidth: 0, cursor: 'pointer',
            textDecoration: state === 'fixing' ? 'line-through' : 'none',
            textDecorationColor: T.low, textDecorationThickness: 1.5,
          }}
            onClick={() => onOpen(item.id)}>
            <div style={{
              fontFamily: 'Poppins, sans-serif', fontSize: 9, color: T.ink3,
              letterSpacing: '0.04em', fontWeight: 600,
              textTransform: 'uppercase', marginBottom: 2,
            }}>{item.type} - {item.id}</div>
            <div style={{
              fontFamily: '"Zilla Slab", serif', fontSize: 13, fontWeight: 600,
              color: T.darkBlue, letterSpacing: '-0.005em', lineHeight: 1.2,
              marginBottom: 3,
            }}>{item.name}</div>
            <DeptChip name={item.dept} tiny />
          </div>
          {/* State chip — tap to open picker */}
          <button onClick={() => setPickerForId(item.id)} style={{
            padding: '4px 8px', background: meta.color, color: '#fff',
            fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 700,
            letterSpacing: '0.08em', border: 'none', cursor: 'pointer',
            flexShrink: 0,
            display: 'inline-flex', alignItems: 'center', gap: 4,
          }}>
            {meta.short}
            <ChevronDown size={10} strokeWidth={2.5}/>
          </button>
          {/* Remove */}
          <button onClick={() => onRemove(item.id)} style={{
            background: 'transparent', border: 'none', cursor: 'pointer',
            padding: 4, color: T.ink3, display: 'inline-flex', flexShrink: 0,
          }}><X size={14}/></button>
        </div>
      ))}

      {/* State picker sheet */}
      <Sheet
        open={!!pickerItem}
        onClose={() => setPickerForId(null)}
        title="Set Asset State"
      >
        {pickerItem && (
          <>
            <div style={{
              padding: '10px 12px', background: T.surfaceAlt, border: `1px solid ${T.lightTeal}`,
              marginBottom: 16,
            }}>
              <div style={{
                fontFamily: 'Poppins, sans-serif', fontSize: 9, color: T.ink3,
                letterSpacing: '0.1em', textTransform: 'uppercase', fontWeight: 600,
              }}>{pickerItem.type} - {pickerItem.id}</div>
              <div style={{
                fontFamily: '"Zilla Slab", serif', fontSize: 16, fontWeight: 600,
                color: T.darkBlue, letterSpacing: '-0.005em', lineHeight: 1.2, marginTop: 2,
              }}>{pickerItem.name}</div>
            </div>

            <div style={{
              fontFamily: 'Poppins, sans-serif', fontSize: 10, color: T.ink3,
              letterSpacing: '0.14em', textTransform: 'uppercase', fontWeight: 700,
              marginBottom: 8,
            }}>What's happening with this asset?</div>

            {STATES.map(s => {
              const m = STATE_META[s];
              const isSelected = s === pickerCurrentState;
              return (
                <button key={s}
                  onClick={() => {
                    onSetState(pickerItem.id, s);
                    setPickerForId(null);
                  }}
                  style={{
                    width: '100%', display: 'flex', gap: 12, alignItems: 'center',
                    padding: '12px 14px', marginBottom: 8,
                    background: isSelected ? m.soft : T.surface,
                    border: `1.5px solid ${isSelected ? m.color : T.rule}`,
                    cursor: 'pointer', textAlign: 'left',
                    fontFamily: 'inherit',
                  }}>
                  <div style={{
                    width: 6, height: 38, background: m.accent, flexShrink: 0,
                  }}/>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{
                      display: 'flex', alignItems: 'center', gap: 8, marginBottom: 2,
                    }}>
                      <span style={{
                        fontFamily: '"Zilla Slab", serif', fontSize: 14, fontWeight: 600,
                        color: m.color, letterSpacing: '-0.005em',
                      }}>{m.label}</span>
                      {m.inCascade ? (
                        <span style={{
                          padding: '1px 6px', background: T.surfaceAlt,
                          color: T.ink2, border: `1px solid ${T.rule}`,
                          fontFamily: 'Poppins, sans-serif', fontSize: 8.5, fontWeight: 700,
                          letterSpacing: '0.08em',
                        }}>IN CASCADE</span>
                      ) : (
                        <span style={{
                          padding: '1px 6px', background: T.surfaceAlt,
                          color: T.ink3, border: `1px solid ${T.rule}`,
                          fontFamily: 'Poppins, sans-serif', fontSize: 8.5, fontWeight: 700,
                          letterSpacing: '0.08em',
                        }}>EXCLUDED</span>
                      )}
                      {isSelected && (
                        <Check size={14} color={m.color} strokeWidth={3} style={{ marginLeft: 'auto' }}/>
                      )}
                    </div>
                    <div style={{
                      fontFamily: 'Poppins, sans-serif', fontSize: 12, color: T.ink2,
                      lineHeight: 1.4,
                    }}>{m.description}</div>
                  </div>
                </button>
              );
            })}
          </>
        )}
      </Sheet>
    </div>
  );
}

/* ============================================================================
   REPORT PREVIEW SCREEN — Phase 3a
   Renders a print-optimized scenario impact report. Sections toggle on/off.
   Print button invokes window.print() — production iOS opens native share/save.
   ============================================================================ */

function ReportPreviewScreen({ scenario, scenarioStates = {}, scenarioName, scenarioNotes = [], scenarioGeometry = [], onSetScenarioName, onBack, onHome, scenarioCount, onScenarioTap, onOpen }) {
  const [sections, setSections] = useState({
    summary: true,
    weatherReport: false,
    questions: true,
    initialActions: true,
    priority: true,
    mapArea: true,
    assetDetail: true,
    cascade: true,
    contacts: true,
    shortTermByAsset: true,
    notes: true,
  });
  // Report weather: fetched at report view time, only when the section is on.
  const reportWx = useReportWeather(PCCA_FACILITY_PINS, sections.weatherReport);
  // Cascade rendering style: 'grouped' (default; flat list grouped by depth band)
  // or 'tree' (full hierarchical traversal showing parentage). User picks in
  // Configure Report when the Cascade Analysis section is enabled.
  const [cascadeStyle, setCascadeStyle] = useState('tree');
  const [configOpen, setConfigOpen] = useState(false);
  const [editingName, setEditingName] = useState(false);
  const [nameDraft, setNameDraft] = useState(scenarioName || '');
  const [shareFlash, setShareFlash] = useState(null); // {kind, message} | null

  // Today's date formatted as "March 14, 2026 · 2:45 PM" style
  const reportDate = useMemo(() => {
    const d = new Date();
    const dateStr = d.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
    const timeStr = d.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' });
    return `${dateStr} · ${timeStr}`;
  }, []);

  // Compute scenario stats and groupings — same math as ScenarioBuilder
  const items = scenario.map(id => lookup[id]).filter(Boolean);
  const itemsByState = useMemo(() => {
    const groups = { disrupted: [], unable: [], manual: [], fixing: [] };
    for (const item of items) {
      const state = scenarioStates[item.id] || 'disrupted';
      (groups[state] || groups.disrupted).push(item);
    }
    for (const k of Object.keys(groups)) {
      groups[k].sort((a, b) => (b.restorationScore || 0) - (a.restorationScore || 0));
    }
    return groups;
  }, [items, scenarioStates]);

  const activeSeeds = useMemo(() =>
    scenario.filter(id => {
      const s = scenarioStates[id] || 'disrupted';
      return STATE_META[s] && STATE_META[s].inCascade;
    }),
  [scenario, scenarioStates]);

  const whatIfActive = useMemo(() =>
    Object.values(scenarioStates).some(s => s && s !== 'disrupted'),
  [scenarioStates]);

  const stats = useMemo(() => {
    if (items.length === 0) return null;
    const cascade = computeCascade(activeSeeds);
    const totalDirect = cascade.direct.size;
    const totalCascade = cascade.totalCascade.size;
    const activeItems = activeSeeds.map(id => lookup[id]).filter(Boolean);
    const prioritized = [...activeItems].sort((a, b) => (b.restorationScore || 0) - (a.restorationScore || 0));
    const allPrioritized = [...items].sort((a, b) => (b.restorationScore || 0) - (a.restorationScore || 0));
    const depts = [...new Set(items.map(i => i.dept))];
    const directList = [...cascade.direct].map(id => {
      const d = getCascadeItem(id);
      return d ? { id, ...d } : null;
    }).filter(Boolean).sort((a, b) => (b.score || 0) - (a.score || 0));
    const cascadeList = [...cascade.totalCascade].map(id => {
      const d = getCascadeItem(id);
      return d ? { id, ...d, depth: cascade.byDepth.get(id) || 1 } : null;
    }).filter(Boolean).sort((a, b) => (b.score || 0) - (a.score || 0));
    return {
      totalDirect, totalCascade, prioritized, allPrioritized, depts,
      directList, cascadeList, activeCount: activeSeeds.length,
    };
  }, [items, scenario, activeSeeds]);

  // Cascade list grouped by depth band (Option C — "Grouped by Level"). Each item
  // appears once, in the depth band of its shortest path from any seed.
  // Within each band, items are sorted by Restoration Score (highest first).
  const cascadeByDepth = useMemo(() => {
    if (!stats) return [];
    const bands = new Map();
    for (const item of stats.cascadeList) {
      const d = item.depth || 1;
      if (!bands.has(d)) bands.set(d, []);
      bands.get(d).push(item);
    }
    return [...bands.entries()]
      .sort((a, b) => a[0] - b[0])
      .map(([depth, items]) => ({ depth, items }));
  }, [stats]);

  // Full per-seed cascade trees (Option A — "Full Cascade Tree"). Built fresh
  // here rather than reusing the on-screen tree state because the report has
  // no concept of expand/collapse: every node is rendered.
  const cascadeTrees = useMemo(() => {
    if (!stats || activeSeeds.length === 0) return [];
    return buildCascadeTree(activeSeeds, 8);
  }, [stats, activeSeeds]);

  // Departments touched -> contacts (only directors of relevant depts)
  const reportContacts = useMemo(() => {
    if (!stats) return [];
    const seen = new Set();
    const list = [];
    for (const dept of stats.depts) {
      const dir = DIRECTORS[dept];
      if (dir && !seen.has(dir.email)) {
        seen.add(dir.email);
        list.push({ ...dir, dept });
      }
    }
    return list;
  }, [stats]);

  // Initial Actions — top entry from each scenario asset's short-term list,
  // ordered by restoration score (highest first) so highest-priority actions lead.
  const initialActions = useMemo(() => {
    if (!stats) return [];
    return stats.allPrioritized
      .map(item => {
        const list = item.shortTerm || [];
        if (list.length === 0) return null;
        const top = list[0];
        const state = scenarioStates[item.id] || 'disrupted';
        return {
          assetId: item.id,
          assetName: item.name,
          assetType: item.type,
          assetScore: item.restorationScore,
          assetDept: item.dept,
          state,
          head: top.head,
          body: top.body || [],
        };
      })
      .filter(Boolean);
  }, [stats, scenarioStates]);

  // Full short-term lists, grouped per asset, in priority order
  const shortTermByAsset = useMemo(() => {
    if (!stats) return [];
    return stats.allPrioritized
      .map(item => ({
        assetId: item.id,
        assetName: item.name,
        assetType: item.type,
        assetScore: item.restorationScore,
        assetDept: item.dept,
        state: scenarioStates[item.id] || 'disrupted',
        items: item.shortTerm || [],
      }))
      .filter(g => g.items.length > 0);
  }, [stats, scenarioStates]);

  // Auto-generated executive summary
  const executiveSummary = useMemo(() => {
    if (!stats || items.length === 0) return null;
    const lines = [];
    const total = items.length;
    const deptCount = stats.depts.length;
    const cascadeN = stats.totalCascade;
    const directN = stats.totalDirect;
    const top = stats.prioritized[0];

    if (whatIfActive) {
      const actCount = stats.activeCount;
      const inactiveCount = total - actCount;
      lines.push(
        `This scenario assesses disruption to ${total} critical asset${total !== 1 ? 's' : ''} ` +
        `across ${deptCount} department${deptCount !== 1 ? 's' : ''}. A what-if hypothesis is currently applied: ` +
        `${actCount} asset${actCount !== 1 ? 's are' : ' is'} actively contributing to the cascade ` +
        `and ${inactiveCount} ${inactiveCount !== 1 ? 'are' : 'is'} excluded ` +
        `(running on manual operations or being fixed).`
      );
    } else {
      lines.push(
        `This scenario assesses disruption to ${total} critical asset${total !== 1 ? 's' : ''} ` +
        `across ${deptCount} department${deptCount !== 1 ? 's' : ''}.`
      );
    }

    if (stats.activeCount > 0) {
      lines.push(
        `The combined impact reaches ${cascadeN} unique downstream item${cascadeN !== 1 ? 's' : ''} ` +
        `in the full cascade, including ${directN} immediate first-level dependenc${directN !== 1 ? 'ies' : 'y'}.`
      );
      if (top) {
        lines.push(
          `The highest-priority restoration target is ${top.name} (Restoration Score ${top.restorationScore}), ` +
          `${top.dept ? `a ${top.dept} ${top.type.toLowerCase()}` : 'an asset'} required for ongoing port operations.`
        );
      }
    } else {
      lines.push(
        `Under the current what-if hypothesis, all assets are being addressed via active fixes or manual ` +
        `operations. The active cascade is empty.`
      );
    }

    return lines;
  }, [items, stats, whatIfActive]);

  // Compute section numbering — only count sections that are toggled on AND have content
  const sectionOrder = [
    { key: 'summary',          hasContent: !!executiveSummary },
    { key: 'weatherReport',    hasContent: sections.weatherReport },
    { key: 'questions',        hasContent: true },
    { key: 'initialActions',   hasContent: initialActions.length > 0 },
    { key: 'priority',         hasContent: items.length > 0 },
    { key: 'mapArea',          hasContent: scenarioGeometry.length > 0 },
    { key: 'assetDetail',      hasContent: items.length > 0 },
    { key: 'cascade',          hasContent: !!stats },
    { key: 'contacts',         hasContent: reportContacts.length > 0 },
    { key: 'shortTermByAsset', hasContent: shortTermByAsset.length > 0 },
    { key: 'notes',            hasContent: scenarioNotes.length > 0 },
  ];
  const sectionIdx = {};
  let n = 0;
  for (const s of sectionOrder) {
    if (sections[s.key] && s.hasContent) {
      n += 1;
      sectionIdx[s.key] = String(n).padStart(2, '0');
    }
  }

  const handlePrint = () => {
    const oldTitle = document.title;
    document.title = `${DST_CONFIG.org.titleShort} — ${scenarioName || 'Scenario Report'}`;
    window.print();
    setTimeout(() => { document.title = oldTitle; }, 1000);
  };

  // Build a plain-text summary of the report — for navigator.share text path
  const buildShareText = () => {
    if (!stats) return '';
    const lines = [];
    lines.push(`${DST_CONFIG.org.titleShort} — ${scenarioName || 'Scenario Report'}`);
    lines.push(reportDate);
    lines.push('');
    lines.push(`${items.length} ${items.length === 1 ? 'asset' : 'assets'} · ${stats.depts.length} ${stats.depts.length === 1 ? 'department' : 'departments'} · ${stats.totalCascade} downstream items in cascade`);
    if (whatIfActive) {
      lines.push(`What-if hypothesis applied: ${stats.activeCount} active in cascade, ${items.length - stats.activeCount} excluded`);
    }
    lines.push('');

    // Executive summary
    if (executiveSummary) {
      lines.push('EXECUTIVE SUMMARY');
      executiveSummary.forEach(p => lines.push(p));
      lines.push('');
    }

    // Top 3 priority items
    if (stats.prioritized.length > 0) {
      lines.push('TOP RESTORATION PRIORITIES');
      stats.prioritized.slice(0, 3).forEach((it, i) => {
        const state = scenarioStates[it.id] || 'disrupted';
        const meta = STATE_META[state];
        lines.push(`${i + 1}. ${it.name} (Score ${it.restorationScore}, ${meta.label}) — ${it.dept}`);
      });
      lines.push('');
    }

    // Initial actions — one per asset
    if (initialActions.length > 0) {
      lines.push('INITIAL ACTIONS');
      initialActions.slice(0, 5).forEach((a, i) => {
        lines.push(`${i + 1}. [${a.assetName}] ${a.head}`);
      });
      lines.push('');
    }

    // Notes summary
    if (scenarioNotes.length > 0) {
      lines.push(`Notes: ${scenarioNotes.length} ${scenarioNotes.length === 1 ? 'entry' : 'entries'} in running log (full text in PDF report)`);
      lines.push('');
    }

    lines.push(DST_CONFIG.copy.reportFooter);
    return lines.join('\n');
  };

  const handleShareText = async () => {
    const text = buildShareText();
    const title = `${DST_CONFIG.org.titleShort} — ${scenarioName || 'Scenario Report'}`;
    // Try native share first
    if (typeof navigator !== 'undefined' && navigator.share) {
      try {
        await navigator.share({ title, text });
        setShareFlash({ kind: 'shared', message: 'Shared.' });
      } catch (err) {
        // User cancelled or share failed — silent unless not AbortError
        if (err && err.name !== 'AbortError') {
          // fall through to clipboard fallback
          await fallbackCopy(text);
        }
      }
    } else {
      // No share API — copy to clipboard as fallback
      await fallbackCopy(text);
    }
    setTimeout(() => setShareFlash(null), 2400);
  };

  const fallbackCopy = async (text) => {
    try {
      if (typeof navigator !== 'undefined' && navigator.clipboard) {
        await navigator.clipboard.writeText(text);
        setShareFlash({ kind: 'copied', message: 'Summary copied to clipboard.' });
      } else {
        // Last-resort textarea fallback
        const ta = document.createElement('textarea');
        ta.value = text;
        document.body.appendChild(ta);
        ta.select();
        document.execCommand('copy');
        document.body.removeChild(ta);
        setShareFlash({ kind: 'copied', message: 'Summary copied to clipboard.' });
      }
    } catch {
      setShareFlash({ kind: 'error', message: 'Share unavailable on this device.' });
    }
  };

  const saveName = () => {
    onSetScenarioName(nameDraft.trim() || 'Untitled Scenario');
    setEditingName(false);
  };

  const sectionDefs = [
    { key: 'summary',          label: 'Executive Summary' },
    { key: 'weatherReport',    label: 'Weather Conditions & Forecast' },
    { key: 'questions',        label: 'Critical Questions' },
    { key: 'initialActions',   label: 'Initial Actions / Considerations' },
    { key: 'priority',         label: 'Restoration Priority List' },
    { key: 'mapArea',          label: 'Affected Area Map' },
    { key: 'assetDetail',      label: 'Affected Asset Detail' },
    { key: 'cascade',          label: 'Cascade Analysis' },
    { key: 'contacts',         label: 'Critical Contacts' },
    { key: 'shortTermByAsset', label: 'Short-Term Options by Asset' },
    { key: 'notes',            label: 'Scenario Notes Log' },
  ];

  // -------------------------------------------------------------------------
  // Affected Area Map — build a Mapbox Static Images API URL showing all
  // scenario facility markers plus every drawn area (radius circles rendered
  // as many-point polygons, freehand polygons as-is), auto-framed to the
  // shapes. Returns null if there's no geometry or no token.
  // -------------------------------------------------------------------------
  const mapImageUrl = useMemo(() => {
    const token = MAPBOX_CFG.token;
    if (!token || !scenarioGeometry || scenarioGeometry.length === 0) return null;

    const teal = '2ca6a4';       // fill/stroke for drawn shapes (hex w/o #)
    const pinColor = '1e293b';   // facility markers

    // Build a circle ring (approx) for a radius shape.
    const circleRing = (center, radiusMi, steps = 48) => {
      const latRad = (center.lat * Math.PI) / 180;
      const dLat = radiusMi / 69.0;
      const dLng = radiusMi / (69.0 * Math.cos(latRad) || 1);
      const coords = [];
      for (let i = 0; i <= steps; i++) {
        const t = (i / steps) * 2 * Math.PI;
        coords.push([
          +(center.lng + dLng * Math.cos(t)).toFixed(5),
          +(center.lat + dLat * Math.sin(t)).toFixed(5),
        ]);
      }
      return coords;
    };

    // GeoJSON features for each drawn shape.
    const shapeFeatures = scenarioGeometry.map(g => {
      let ring;
      if (g.kind === 'radius' && g.center) ring = circleRing(g.center, g.radiusMi);
      else if (g.kind === 'polygon' && g.points && g.points.length >= 3) {
        ring = g.points.map(p => [+p.lng.toFixed(5), +p.lat.toFixed(5)]);
        ring.push(ring[0]);
      }
      if (!ring) return null;
      return {
        type: 'Feature',
        properties: { fill: '#' + teal, 'fill-opacity': 0.2, stroke: '#' + teal, 'stroke-width': 2 },
        geometry: { type: 'Polygon', coordinates: [ring] },
      };
    }).filter(Boolean);

    if (shapeFeatures.length === 0) return null;

    // Facility markers (all scenario facilities that have coordinates).
    const facById = {};
    PCCA_FACILITY_PINS.forEach(f => { facById[f.id] = f; });
    const markerFeatures = scenario
      .map(id => facById[id])
      .filter(f => f && typeof f.lat === 'number' && typeof f.lng === 'number')
      .map(f => ({
        type: 'Feature',
        properties: { 'marker-color': '#' + pinColor, 'marker-size': 'small' },
        geometry: { type: 'Point', coordinates: [+f.lng.toFixed(5), +f.lat.toFixed(5)] },
      }));

    const geojson = { type: 'FeatureCollection', features: [...shapeFeatures, ...markerFeatures] };
    const overlay = 'geojson(' + encodeURIComponent(JSON.stringify(geojson)) + ')';

    // Compute a bounding box of the shapes (so the image frames the drawn
    // areas), with a little padding, and let Mapbox 'auto' fit it.
    const style = 'streets-v12';
    const size = '640x360@2x';
    const url = `https://api.mapbox.com/styles/v1/mapbox/${style}/static/${overlay}/auto/${size}?padding=40&access_token=${token}`;
    // Guard against overly long URLs (static API caps around 8k chars).
    if (url.length > 8000) return { tooComplex: true };
    return { url };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [scenarioGeometry, scenario]);

  if (items.length === 0) {
    return (
      <>
        <TopNav back={onBack} title="Report Preview" sub="Scenario Builder"
          scenarioCount={scenarioCount} onScenarioTap={onScenarioTap}/>
        <div style={{
          padding: '40px 20px', textAlign: 'center',
          fontFamily: 'Poppins, sans-serif', color: T.ink3,
        }}>
          <FileText size={36} color={T.ink3} strokeWidth={1.25} style={{ marginBottom: 12 }}/>
          <div style={{
            fontFamily: '"Zilla Slab", serif', fontSize: 18, fontWeight: 600,
            color: T.darkBlue, marginBottom: 6,
          }}>No scenario to report on</div>
          <div style={{ fontSize: 13 }}>Add assets to your scenario to generate a report.</div>
        </div>
        <BottomNav onPrevious={onBack} onHome={onHome}/>
      </>
    );
  }

  return (
    <>
      <TopNav back={onBack} title="Report Preview" sub="Scenario Builder"
        scenarioCount={scenarioCount} onScenarioTap={onScenarioTap}/>

      {/* Configure Report panel — collapsible, applies to print */}
      <div className="dst-no-print" style={{
        background: T.bgAlt, borderBottom: `1px solid ${T.rule}`,
      }}>
        <button onClick={() => setConfigOpen(o => !o)} style={{
          width: '100%', padding: '10px 16px',
          background: 'transparent', border: 'none', cursor: 'pointer',
          display: 'flex', alignItems: 'center', justifyContent: 'space-between',
          fontFamily: 'Poppins, sans-serif', fontSize: 11, fontWeight: 700,
          letterSpacing: '0.1em', textTransform: 'uppercase', color: T.ink2,
        }}>
          <span style={{ display: 'inline-flex', alignItems: 'center', gap: 6 }}>
            <Cog size={13} strokeWidth={2}/> Configure Report
          </span>
          {configOpen ? <ChevronDown size={14}/> : <ChevronRight size={14}/>}
        </button>
        {configOpen && (
          <div style={{ padding: '4px 16px 16px' }}>
            <div style={{
              fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 700,
              letterSpacing: '0.12em', textTransform: 'uppercase',
              color: T.ink3, marginBottom: 6,
            }}>Sections</div>
            {sectionDefs.filter(({ key }) => key !== 'mapArea' || scenarioGeometry.length > 0).map(({ key, label }) => (
              <button key={key} onClick={() => setSections(s => ({ ...s, [key]: !s[key] }))}
                style={{
                  width: '100%', display: 'flex', alignItems: 'center', gap: 10,
                  padding: '8px 4px', background: 'transparent', border: 'none',
                  cursor: 'pointer', textAlign: 'left',
                  fontFamily: 'inherit', borderBottom: `1px solid ${T.ruleSoft}`,
                }}>
                <div style={{
                  width: 20, height: 20, flexShrink: 0,
                  border: `2px solid ${sections[key] ? T.teal : T.rule}`,
                  background: sections[key] ? T.teal : 'transparent',
                  display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
                }}>
                  {sections[key] && <Check size={13} color="#fff" strokeWidth={3}/>}
                </div>
                <span style={{
                  fontFamily: 'Poppins, sans-serif', fontSize: 12, color: T.ink, fontWeight: 500,
                }}>{label}</span>
              </button>
            ))}

            {/* Cascade Analysis style picker — only meaningful if Cascade section is on */}
            {sections.cascade && (
              <div style={{ marginTop: 14, paddingTop: 12, borderTop: `1px solid ${T.rule}` }}>
                <div style={{
                  fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 700,
                  letterSpacing: '0.12em', textTransform: 'uppercase',
                  color: T.ink3, marginBottom: 8,
                }}>Cascade Analysis Style</div>
                {[
                  {
                    key: 'tree',
                    label: 'Full Cascade Tree',
                    desc: 'Hierarchical view showing parentage. Items may appear multiple times reflecting different dependency paths. Longer.',
                  },
                  {
                    key: 'grouped',
                    label: 'Grouped by Level',
                    desc: 'Flat list grouped by depth (L1, L2, L3...) and sorted by Restoration Score within each level. Each item appears once.',
                  },
                ].map(opt => {
                  const isSelected = cascadeStyle === opt.key;
                  return (
                    <button key={opt.key} onClick={() => setCascadeStyle(opt.key)}
                      style={{
                        width: '100%', display: 'flex', alignItems: 'flex-start', gap: 10,
                        padding: '10px 8px', marginBottom: 6,
                        background: isSelected ? T.surfaceAlt : 'transparent',
                        border: `1.5px solid ${isSelected ? T.teal : T.rule}`,
                        cursor: 'pointer', textAlign: 'left',
                        fontFamily: 'inherit',
                      }}>
                      <div style={{
                        width: 16, height: 16, marginTop: 2, flexShrink: 0,
                        borderRadius: '50%',
                        border: `2px solid ${isSelected ? T.teal : T.rule}`,
                        background: isSelected ? T.teal : 'transparent',
                        display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
                      }}>
                        {isSelected && (
                          <div style={{
                            width: 6, height: 6, borderRadius: '50%', background: '#fff',
                          }}/>
                        )}
                      </div>
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <div style={{
                          fontFamily: 'Poppins, sans-serif', fontSize: 12, color: T.ink, fontWeight: 600,
                          marginBottom: 2,
                        }}>{opt.label}</div>
                        <div style={{
                          fontFamily: 'Poppins, sans-serif', fontSize: 10.5, color: T.ink2,
                          lineHeight: 1.4,
                        }}>{opt.desc}</div>
                      </div>
                    </button>
                  );
                })}
              </div>
            )}
          </div>
        )}
      </div>

      {/* Print/Share action bar */}
      <div className="dst-no-print" style={{
        padding: '10px 16px', background: T.surface,
        borderBottom: `1px solid ${T.rule}`,
      }}>
        <div style={{ display: 'flex', gap: 8 }}>
          <button onClick={handleShareText} style={{
            flex: 1, padding: '12px',
            background: T.teal, color: '#fff', border: 'none', cursor: 'pointer',
            fontFamily: 'Poppins, sans-serif', fontSize: 11, fontWeight: 700,
            letterSpacing: '0.1em', textTransform: 'uppercase',
            display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: 6,
          }}>
            <Share2 size={14}/> Share Summary
          </button>
          <button onClick={handlePrint} style={{
            flex: 1, padding: '12px',
            background: T.darkBlue, color: '#fff', border: 'none', cursor: 'pointer',
            fontFamily: 'Poppins, sans-serif', fontSize: 11, fontWeight: 700,
            letterSpacing: '0.1em', textTransform: 'uppercase',
            display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: 6,
          }}>
            <Printer size={14}/> Print / Save PDF
          </button>
        </div>
        {/* Share flash confirmation */}
        {shareFlash && (
          <div style={{
            marginTop: 8, padding: '8px 12px',
            background: shareFlash.kind === 'error' ? T.criticalSoft : T.lowSoft,
            border: `1px solid ${shareFlash.kind === 'error' ? T.critical : T.low}`,
            fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink,
            display: 'flex', alignItems: 'center', gap: 6,
          }}>
            {shareFlash.kind === 'copied' && <Copy size={13} color={T.low} strokeWidth={2.5}/>}
            {shareFlash.kind === 'shared' && <Check size={13} color={T.low} strokeWidth={2.5}/>}
            {shareFlash.kind === 'error' && <Info size={13} color={T.critical} strokeWidth={2.5}/>}
            {shareFlash.message}
          </div>
        )}
        {/* Helper text — only when no flash showing */}
        {!shareFlash && (
          <div style={{
            marginTop: 6,
            fontFamily: 'Poppins, sans-serif', fontSize: 10, color: T.ink3,
            lineHeight: 1.4, fontStyle: 'italic',
          }}>
            Share Summary sends a plain-text brief via your device's share sheet.
            Print / Save PDF opens the system print dialog for the full report.
          </div>
        )}
      </div>

      {/* Report content — paper styling on screen, clean on print */}
      <div className="dst-report-wrap" style={{
        padding: '14px',
        background: T.bgAlt,
      }}>
        <div className="dst-report" style={{
          background: '#fff',
          padding: '24px 20px',
          boxShadow: '0 2px 8px rgba(14,30,51,0.08)',
        }}>
          {/* Report header */}
          <div style={{
            display: 'flex', alignItems: 'center', gap: 12,
            paddingBottom: 14, marginBottom: 16,
            borderBottom: `2px solid ${T.darkBlue}`,
          }}>
            <PCCALogo height={48} showWordmark={false}/>
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{
                fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 700,
                letterSpacing: '0.16em', textTransform: 'uppercase', color: T.teal,
                marginBottom: 2,
              }}>Decision Support Tool</div>
              <div style={{
                fontFamily: '"Zilla Slab", serif', fontSize: 18, fontWeight: 600,
                color: T.darkBlue, letterSpacing: '-0.01em', lineHeight: 1.1,
              }}>Scenario Impact Report</div>
            </div>
          </div>

          {/* Scenario name (editable) */}
          <div style={{ marginBottom: 10 }}>
            <div style={{
              fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 700,
              letterSpacing: '0.14em', textTransform: 'uppercase', color: T.ink3,
              marginBottom: 4,
            }}>Scenario</div>
            {editingName ? (
              <div className="dst-no-print" style={{
                display: 'flex', gap: 6, alignItems: 'center',
              }}>
                <input
                  value={nameDraft}
                  onChange={e => setNameDraft(e.target.value)}
                  onBlur={saveName}
                  onKeyDown={e => e.key === 'Enter' && saveName()}
                  autoFocus
                  style={{
                    flex: 1, padding: '6px 10px',
                    border: `1px solid ${T.darkBlue}`, outline: 'none',
                    fontFamily: '"Zilla Slab", serif', fontSize: 17, fontWeight: 600,
                    color: T.darkBlue,
                  }}/>
                <button onClick={saveName} style={{
                  padding: '6px 10px', background: T.teal, color: '#fff', border: 'none',
                  cursor: 'pointer', fontFamily: 'Poppins, sans-serif', fontSize: 10, fontWeight: 700,
                }}>SAVE</button>
              </div>
            ) : (
              <div style={{
                fontFamily: '"Zilla Slab", serif', fontSize: 19, fontWeight: 600,
                color: T.darkBlue, letterSpacing: '-0.01em',
                display: 'flex', alignItems: 'center', gap: 8,
              }}>
                {scenarioName || 'Untitled Scenario'}
                <button className="dst-no-print" onClick={() => { setNameDraft(scenarioName || ''); setEditingName(true); }}
                  style={{
                    background: 'transparent', border: 'none', cursor: 'pointer',
                    color: T.teal, padding: 0,
                    fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 700,
                    letterSpacing: '0.08em', textTransform: 'uppercase',
                  }}>Rename</button>
              </div>
            )}
          </div>

          {/* Date and metadata */}
          <div style={{
            display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: 10,
            marginBottom: 22, padding: '10px 12px',
            background: T.surfaceAlt, border: `1px solid ${T.lightTeal}`,
          }}>
            <div>
              <div style={{
                fontFamily: 'Poppins, sans-serif', fontSize: 8, fontWeight: 700,
                letterSpacing: '0.14em', textTransform: 'uppercase', color: T.ink3,
              }}>Generated</div>
              <div style={{
                fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink, fontWeight: 500,
              }}>{reportDate}</div>
            </div>
            <div>
              <div style={{
                fontFamily: 'Poppins, sans-serif', fontSize: 8, fontWeight: 700,
                letterSpacing: '0.14em', textTransform: 'uppercase', color: T.ink3,
              }}>Status</div>
              <div style={{
                fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink, fontWeight: 500,
              }}>{whatIfActive ? 'What-If Hypothesis' : 'Baseline Scenario'}</div>
            </div>
            <div>
              <div style={{
                fontFamily: 'Poppins, sans-serif', fontSize: 8, fontWeight: 700,
                letterSpacing: '0.14em', textTransform: 'uppercase', color: T.ink3,
              }}>Assets in Scenario</div>
              <div style={{
                fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink, fontWeight: 500,
              }}>{items.length}</div>
            </div>
            <div>
              <div style={{
                fontFamily: 'Poppins, sans-serif', fontSize: 8, fontWeight: 700,
                letterSpacing: '0.14em', textTransform: 'uppercase', color: T.ink3,
              }}>Cascade Impact</div>
              <div style={{
                fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink, fontWeight: 500,
              }}>{stats?.totalCascade || 0} unique items</div>
            </div>
          </div>

          {/* 01 — Executive Summary */}
          {sections.summary && executiveSummary && (
            <ReportSection title="Executive Summary" idx={sectionIdx.summary}>
              {executiveSummary.map((line, i) => (
                <p key={i} style={{
                  fontFamily: 'Poppins, sans-serif', fontSize: 12, lineHeight: 1.55,
                  color: T.ink, margin: '0 0 10px 0',
                }}>{line}</p>
              ))}
            </ReportSection>
          )}

          {/* 01b — Weather Conditions & Forecast (opt-in; fetched at report time) */}
          {sections.weatherReport && (
            <ReportSection title="Weather Conditions & Forecast" idx={sectionIdx.weatherReport}>
              {reportWx.status === 'loading' && (
                <p style={{ fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink3, fontStyle: 'italic', margin: 0 }}>Loading current conditions and forecast…</p>
              )}
              {reportWx.status === 'error' && (
                <p style={{ fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink3, fontStyle: 'italic', margin: 0 }}>Weather data is unavailable at this time.</p>
              )}
              {reportWx.status === 'ready' && (() => {
                const cur = reportWx.current;
                const hz = reportWx.horizons || [];
                // Build the narrative: current first, then the forecast trend.
                const parts = [];
                if (cur) {
                  const bits = [];
                  if (cur.tempF != null) bits.push(cur.tempF + '\u00B0F');
                  if (cur.text) bits.push(cur.text.toLowerCase());
                  let s = 'At time of report, conditions at the facility area were ' + (bits.join(', ') || 'as recorded');
                  if (cur.windMph != null) s += ', wind ' + cur.windMph + ' mph' + (cur.windDir ? ' ' + cur.windDir : '');
                  if (cur.humidity != null) s += ', humidity ' + cur.humidity + '%';
                  s += '.';
                  parts.push(s);
                }
                const h24 = hz.find(h => h.key === '24h');
                const h4 = hz.find(h => h.key === '4h');
                if (h24) {
                  let s = 'Over the next 24 hours, ';
                  if (h24.lo != null && h24.hi != null) s += 'temperatures ranging ' + h24.lo + '\u00B0 to ' + h24.hi + '\u00B0';
                  else if (h24.hi != null) s += 'temperatures near ' + h24.hi + '\u00B0';
                  if (h24.summary) s += (h24.hi != null ? ', ' : '') + h24.summary.toLowerCase();
                  else if (h24.pop != null) s += ', up to ' + h24.pop + '% chance of precipitation';
                  s += '.';
                  parts.push(s);
                } else if (h4 && h4.summary) {
                  parts.push('In the near term, ' + h4.summary.toLowerCase() + '.');
                }

                // Table rows: metric per row, horizon per column.
                const cols = [
                  { key: 'current', label: 'Current' },
                  ...hz.map(h => ({ key: h.key, label: h.label })),
                ];
                const cellTemp = (colKey) => {
                  if (colKey === 'current') return cur && cur.tempF != null ? cur.tempF + '\u00B0' : '\u2014';
                  const h = hz.find(x => x.key === colKey);
                  if (!h) return '\u2014';
                  if (h.key === '1h') return h.tempNow != null ? h.tempNow + '\u00B0' : '\u2014';
                  return (h.lo != null && h.hi != null) ? h.lo + '\u00B0\u2013' + h.hi + '\u00B0' : '\u2014';
                };
                const cellCond = (colKey) => {
                  if (colKey === 'current') return cur && cur.text ? cur.text : '\u2014';
                  const h = hz.find(x => x.key === colKey);
                  return h ? (h.summary || h.shortForecast || '\u2014') : '\u2014';
                };
                const cellWind = (colKey) => {
                  if (colKey === 'current') return cur && cur.windMph != null ? cur.windMph + ' mph' + (cur.windDir ? ' ' + cur.windDir : '') : '\u2014';
                  const h = hz.find(x => x.key === colKey);
                  return h && h.wind ? h.wind + (h.windDir ? ' ' + h.windDir : '') : '\u2014';
                };
                const cellPop = (colKey) => {
                  if (colKey === 'current') return '\u2014';
                  const h = hz.find(x => x.key === colKey);
                  return h && h.pop != null ? h.pop + '%' : '\u2014';
                };
                const cellHum = (colKey) => {
                  if (colKey === 'current') return cur && cur.humidity != null ? cur.humidity + '%' : '\u2014';
                  return '\u2014';
                };
                const rows = [
                  { label: 'Temperature', fn: cellTemp },
                  { label: 'Conditions', fn: cellCond },
                  { label: 'Wind', fn: cellWind },
                  { label: 'Precip chance', fn: cellPop },
                  { label: 'Humidity', fn: cellHum },
                ];

                const thtd = {
                  fontFamily: 'Poppins, sans-serif', fontSize: 10, textAlign: 'left',
                  padding: '6px 8px', borderBottom: `1px solid ${T.ruleSoft}`, verticalAlign: 'top',
                };
                return (
                  <>
                    {parts.map((p, i) => (
                      <p key={i} style={{ fontFamily: 'Poppins, sans-serif', fontSize: 12, lineHeight: 1.55, color: T.ink, margin: '0 0 10px 0' }}>{p}</p>
                    ))}
                    <table style={{ width: '100%', borderCollapse: 'collapse', marginTop: 4 }}>
                      <thead>
                        <tr>
                          <th style={{ ...thtd, fontWeight: 700, color: T.ink3, textTransform: 'uppercase', letterSpacing: '0.04em', fontSize: 9, borderBottom: `1.5px solid ${T.rule}` }}></th>
                          {cols.map(c => (
                            <th key={c.key} style={{ ...thtd, fontWeight: 700, color: T.darkBlue, borderBottom: `1.5px solid ${T.rule}` }}>{c.label}</th>
                          ))}
                        </tr>
                      </thead>
                      <tbody>
                        {rows.map(r => (
                          <tr key={r.label}>
                            <td style={{ ...thtd, fontWeight: 700, color: T.ink2, whiteSpace: 'nowrap' }}>{r.label}</td>
                            {cols.map(c => (
                              <td key={c.key} style={{ ...thtd, color: T.ink }}>{r.fn(c.key)}</td>
                            ))}
                          </tr>
                        ))}
                      </tbody>
                    </table>
                    {reportWx.current && reportWx.current.timestamp && (
                      <p style={{ fontFamily: 'Poppins, sans-serif', fontSize: 9, color: T.ink3, margin: '8px 0 0 0' }}>Current observation as of {new Date(reportWx.current.timestamp).toLocaleString([], { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' })}{reportWx.current.stationName ? ' · ' + reportWx.current.stationName : ''}. Forecast via NWS.</p>
                    )}
                  </>
                );
              })()}
            </ReportSection>
          )}

          {/* 02 — Critical Questions */}
          {sections.questions && (
            <ReportSection title="Critical Questions" idx={sectionIdx.questions}>
              <p style={{
                fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink2,
                fontStyle: 'italic', margin: '0 0 10px 0', lineHeight: 1.4,
              }}>Use to ground situational awareness in the operational environment.</p>
              <ol style={{ listStyle: 'none', padding: 0, margin: 0 }}>
                {CRITICAL_QUESTIONS.map((q, i) => (
                  <li key={i} style={{
                    display: 'flex', gap: 8, padding: '6px 0',
                    borderBottom: i < CRITICAL_QUESTIONS.length - 1 ? `1px solid ${T.ruleSoft}` : 'none',
                  }}>
                    <span style={{
                      fontFamily: '"Zilla Slab", serif', fontSize: 14, fontWeight: 700,
                      color: T.teal, minWidth: 22,
                    }}>{String(i + 1).padStart(2, '0')}</span>
                    <span style={{
                      fontFamily: 'Poppins, sans-serif', fontSize: 11.5, lineHeight: 1.45,
                      color: T.ink,
                    }}>{q}</span>
                  </li>
                ))}
              </ol>
            </ReportSection>
          )}

          {/* 03 — Initial Actions / Considerations */}
          {sections.initialActions && initialActions.length > 0 && (
            <ReportSection title="Initial Actions / Considerations" idx={sectionIdx.initialActions}>
              <p style={{
                fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink2,
                fontStyle: 'italic', margin: '0 0 12px 0', lineHeight: 1.4,
              }}>Top short-term action for each asset, ordered by Restoration Score. See Short-Term Options by Asset for the full list per asset.</p>
              {initialActions.map((a, i) => {
                const meta = STATE_META[a.state];
                return (
                  <div key={a.assetId} style={{
                    padding: '10px 12px', marginBottom: 8,
                    background: T.surface, border: `1px solid ${T.rule}`,
                    borderLeft: `4px solid ${meta.accent}`,
                    pageBreakInside: 'avoid',
                  }}>
                    <div style={{
                      display: 'flex', alignItems: 'center', gap: 8, marginBottom: 6,
                      flexWrap: 'wrap',
                    }}>
                      <span style={{
                        fontFamily: '"Zilla Slab", serif', fontSize: 14, fontWeight: 700,
                        color: T.teal, minWidth: 22,
                      }}>{String(i + 1).padStart(2, '0')}</span>
                      <span style={{
                        fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 700,
                        color: T.ink3, letterSpacing: '0.06em', textTransform: 'uppercase',
                      }}>{a.assetType} - {a.assetId}</span>
                      <span style={{
                        padding: '1px 6px', background: meta.color, color: '#fff',
                        fontFamily: 'Poppins, sans-serif', fontSize: 8, fontWeight: 700,
                        letterSpacing: '0.08em',
                      }}>{meta.short}</span>
                      <span style={{
                        marginLeft: 'auto',
                        fontFamily: 'Poppins, sans-serif', fontSize: 10, color: T.ink2, fontWeight: 500,
                      }}>{a.assetName}</span>
                    </div>
                    <div style={{
                      fontFamily: '"Zilla Slab", serif', fontSize: 14, fontWeight: 600,
                      color: T.darkBlue, lineHeight: 1.25, marginBottom: 6,
                    }}>{a.head}</div>
                    {a.body && a.body.length > 0 && (
                      <ul style={{
                        listStyle: 'none', padding: 0, margin: 0,
                      }}>
                        {a.body.map((b, bi) => (
                          <li key={bi} style={{
                            display: 'flex', gap: 8, padding: '3px 0',
                            fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink,
                            lineHeight: 1.45,
                          }}>
                            <span style={{ color: T.teal, fontWeight: 700 }}>›</span>
                            <span>{b}</span>
                          </li>
                        ))}
                      </ul>
                    )}
                  </div>
                );
              })}
            </ReportSection>
          )}

          {/* 04 — Restoration Priority List */}
          {sections.priority && (
            <ReportSection title="Restoration Priority List" idx={sectionIdx.priority}>
              <p style={{
                fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink2,
                fontStyle: 'italic', margin: '0 0 12px 0', lineHeight: 1.4,
              }}>Ordered by Restoration Score, highest first. Items grouped by what-if state.</p>
              {STATES.map(stateKey => {
                const list = itemsByState[stateKey];
                if (!list || list.length === 0) return null;
                const meta = STATE_META[stateKey];
                return (
                  <div key={stateKey} style={{ marginBottom: 14 }}>
                    <div style={{
                      display: 'flex', alignItems: 'center', gap: 8,
                      padding: '4px 0', marginBottom: 4,
                      borderBottom: `1.5px solid ${meta.accent}`,
                    }}>
                      <div style={{ width: 4, height: 14, background: meta.accent }}/>
                      <div style={{
                        fontFamily: '"Zilla Slab", serif', fontSize: 12, fontWeight: 600,
                        color: meta.color,
                      }}>{meta.label}</div>
                      <span style={{
                        padding: '1px 6px', background: meta.soft, color: meta.color,
                        fontFamily: 'Poppins, sans-serif', fontSize: 8.5, fontWeight: 700,
                        letterSpacing: '0.08em',
                      }}>{list.length}</span>
                      {!meta.inCascade && (
                        <span style={{
                          marginLeft: 'auto',
                          fontFamily: 'Poppins, sans-serif', fontSize: 8.5,
                          fontStyle: 'italic', color: T.ink3, letterSpacing: '0.04em',
                        }}>excluded from cascade</span>
                      )}
                    </div>
                    {list.map((item, idx) => (
                      <div key={item.id} style={{
                        display: 'flex', gap: 10, padding: '8px 4px',
                        borderBottom: `1px solid ${T.ruleSoft}`,
                        opacity: meta.inCascade ? 1 : 0.75,
                      }}>
                        <div style={{
                          fontFamily: '"Zilla Slab", serif', fontSize: 14, fontWeight: 700,
                          color: meta.accent, minWidth: 24,
                        }}>{String(idx + 1).padStart(2, '0')}</div>
                        <div style={{ flex: 1, minWidth: 0 }}>
                          <div style={{
                            fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 600,
                            color: T.ink3, letterSpacing: '0.04em', textTransform: 'uppercase',
                            marginBottom: 1,
                          }}>{item.type} - {item.id} · Priority {item.priority}</div>
                          <div style={{
                            fontFamily: '"Zilla Slab", serif', fontSize: 13, fontWeight: 600,
                            color: T.darkBlue, lineHeight: 1.2, marginBottom: 2,
                          }}>{item.name}</div>
                          <div style={{
                            fontFamily: 'Poppins, sans-serif', fontSize: 10, color: T.ink2,
                          }}>{item.dept} · {item.opCategory}</div>
                        </div>
                        <div style={{
                          fontFamily: '"Zilla Slab", serif', fontSize: 18, fontWeight: 700,
                          color: meta.accent, minWidth: 36, textAlign: 'right',
                        }}>{item.restorationScore}</div>
                      </div>
                    ))}
                  </div>
                );
              })}
            </ReportSection>
          )}

          {/* 04b — Affected Area Map (only when a shape was drawn) */}
          {sections.mapArea && scenarioGeometry.length > 0 && (
            <ReportSection title="Affected Area Map" idx={sectionIdx.mapArea}>
              <p style={{
                fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink2,
                fontStyle: 'italic', margin: '0 0 12px 0', lineHeight: 1.4,
              }}>{scenarioGeometry.length === 1 ? 'The drawn selection area' : `${scenarioGeometry.length} drawn selection areas`} with facility locations. Facilities shown as points; selection areas shaded.</p>
              {mapImageUrl && mapImageUrl.url && (
                <img
                  src={mapImageUrl.url}
                  alt="Map of affected area with facility locations"
                  style={{ width: '100%', borderRadius: 6, border: `1px solid ${T.rule}`, display: 'block' }}
                />
              )}
              {mapImageUrl && mapImageUrl.tooComplex && (
                <div style={{
                  padding: '16px', textAlign: 'center', background: T.surfaceAlt,
                  border: `1px solid ${T.rule}`, borderRadius: 6,
                  fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink3,
                }}>The drawn area is too detailed to render as a static map image.</div>
              )}
            </ReportSection>
          )}

          {/* 05 — Affected Asset Detail */}
          {sections.assetDetail && stats && (
            <ReportSection title="Affected Asset Detail" idx={sectionIdx.assetDetail}>
              {stats.allPrioritized.map((item, idx) => {
                const state = scenarioStates[item.id] || 'disrupted';
                const meta = STATE_META[state];
                const poc = getPOC(item);
                return (
                  <div key={item.id} style={{
                    marginBottom: 18, paddingBottom: 14,
                    borderBottom: idx < stats.allPrioritized.length - 1 ? `1px solid ${T.ruleSoft}` : 'none',
                    pageBreakInside: 'avoid',
                  }}>
                    <div style={{
                      display: 'flex', alignItems: 'baseline', gap: 8, marginBottom: 8,
                      flexWrap: 'wrap',
                    }}>
                      <div style={{
                        fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 600,
                        color: T.ink3, letterSpacing: '0.06em', textTransform: 'uppercase',
                      }}>{item.type} - {item.id}</div>
                      <span style={{
                        padding: '1px 6px', background: meta.color, color: '#fff',
                        fontFamily: 'Poppins, sans-serif', fontSize: 8, fontWeight: 700,
                        letterSpacing: '0.08em',
                      }}>{meta.short}</span>
                      <span style={{ marginLeft: 'auto',
                        fontFamily: '"Zilla Slab", serif', fontSize: 16, fontWeight: 700,
                        color: meta.accent,
                      }}>Score {item.restorationScore}</span>
                    </div>
                    <div style={{
                      fontFamily: '"Zilla Slab", serif', fontSize: 16, fontWeight: 600,
                      color: T.darkBlue, letterSpacing: '-0.005em', lineHeight: 1.15,
                      marginBottom: 8,
                    }}>{item.name}</div>
                    {item.description && (
                      <p style={{
                        fontFamily: 'Poppins, sans-serif', fontSize: 11.5, lineHeight: 1.5,
                        color: T.ink, margin: '0 0 8px 0',
                      }}>{item.description}</p>
                    )}
                    {item.impacts && (
                      <>
                        <div style={{
                          fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 700,
                          letterSpacing: '0.12em', textTransform: 'uppercase', color: T.teal,
                          marginBottom: 4,
                        }}>Impacts from Disruption</div>
                        <p style={{
                          fontFamily: 'Poppins, sans-serif', fontSize: 11.5, lineHeight: 1.5,
                          color: T.ink, margin: '0 0 8px 0',
                        }}>{item.impacts}</p>
                      </>
                    )}
                    <div style={{
                      display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 6,
                      padding: '6px 8px', background: T.surfaceAlt, border: `1px solid ${T.rule}`,
                      marginBottom: poc ? 8 : 0,
                    }}>
                      {[
                        { l: 'Direct',    v: item.direct },
                        { l: 'Total',     v: item.total },
                        { l: 'Depth',     v: item.depth },
                      ].map(({ l, v }) => (
                        <div key={l}>
                          <div style={{
                            fontFamily: 'Poppins, sans-serif', fontSize: 8, fontWeight: 700,
                            color: T.ink3, letterSpacing: '0.1em', textTransform: 'uppercase',
                          }}>{l}</div>
                          <div style={{
                            fontFamily: '"Zilla Slab", serif', fontSize: 14, fontWeight: 700,
                            color: T.darkBlue,
                          }}>{v}</div>
                        </div>
                      ))}
                    </div>
                    {poc && (
                      <div style={{
                        fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink2,
                      }}>
                        <strong style={{ color: T.darkBlue }}>POC:</strong> {poc.name}, {poc.title} ·
                        {' '}{poc.phone} · {poc.email}
                      </div>
                    )}
                  </div>
                );
              })}
            </ReportSection>
          )}

          {/* 06 — Cascade Analysis */}
          {sections.cascade && stats && (
            <ReportSection title="Cascade Analysis" idx={sectionIdx.cascade}>
              {/* Direct Downstream — always shown the same way; first-level dependencies */}
              <div style={{ marginBottom: 16 }}>
                <div style={{
                  fontFamily: '"Zilla Slab", serif', fontSize: 13, fontWeight: 600,
                  color: T.darkBlue, marginBottom: 6,
                  paddingBottom: 4, borderBottom: `1.5px solid ${T.darkBlue}`,
                }}>Direct Downstream ({stats.directList.length})</div>
                {stats.directList.length === 0 ? (
                  <div style={{
                    fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink3,
                    fontStyle: 'italic',
                  }}>None.</div>
                ) : stats.directList.map(item => (
                  <CascadeReportRow key={item.id} item={item}/>
                ))}
              </div>

              {/* Total Cascade — rendered as either Grouped (default) or Tree per Configure Report */}
              <div>
                <div style={{
                  fontFamily: '"Zilla Slab", serif', fontSize: 13, fontWeight: 600,
                  color: T.darkBlue, marginBottom: 6,
                  paddingBottom: 4, borderBottom: `1.5px solid ${T.darkBlue}`,
                }}>Total Cascade ({stats.cascadeList.length})</div>

                {stats.cascadeList.length === 0 ? (
                  <div style={{
                    fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink3,
                    fontStyle: 'italic',
                  }}>None.</div>
                ) : cascadeStyle === 'grouped' ? (
                  /* OPTION C: Grouped by depth band — each item once, sorted by score within band */
                  <>
                    <p style={{
                      fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink2,
                      fontStyle: 'italic', margin: '0 0 12px 0', lineHeight: 1.4,
                    }}>Grouped by depth from the disrupted asset(s). Within each level, items are sorted by Restoration Score.</p>
                    {cascadeByDepth.map(({ depth, items }) => (
                      <div key={depth} style={{ marginBottom: 14 }}>
                        <div style={{
                          fontFamily: 'Poppins, sans-serif', fontSize: 10, fontWeight: 700,
                          letterSpacing: '0.1em', textTransform: 'uppercase',
                          color: T.teal, marginBottom: 6, paddingBottom: 3,
                          borderBottom: `1px solid ${T.lightTeal}`,
                          display: 'flex', justifyContent: 'space-between', alignItems: 'baseline',
                        }}>
                          <span>Level {depth}{depth === 1 ? ' — Direct' : ''}</span>
                          <span style={{
                            fontSize: 10, fontWeight: 600, color: T.ink3,
                          }}>{items.length} {items.length === 1 ? 'item' : 'items'}</span>
                        </div>
                        <div style={{ paddingLeft: (depth - 1) * 14 }}>
                          {items.map(item => (
                            <CascadeReportRow key={item.id} item={item}/>
                          ))}
                        </div>
                      </div>
                    ))}
                  </>
                ) : (
                  /* OPTION A: Full cascade tree — hierarchical, items may repeat across paths */
                  <>
                    <p style={{
                      fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink2,
                      fontStyle: 'italic', margin: '0 0 12px 0', lineHeight: 1.4,
                    }}>Full hierarchical cascade. Items may appear multiple times reflecting different dependency paths from the disrupted asset(s).</p>
                    {cascadeTrees.map(tree => {
                      const seedDetail = getCascadeItem(tree.id);
                      return (
                        <div key={tree.id} style={{
                          marginBottom: 18, paddingBottom: 10,
                          borderBottom: `1px solid ${T.ruleSoft}`,
                        }}>
                          <div style={{
                            fontFamily: '"Zilla Slab", serif', fontSize: 13, fontWeight: 700,
                            color: T.darkBlue, marginBottom: 6,
                          }}>
                            <span style={{
                              fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 700,
                              color: T.ink3, letterSpacing: '0.06em', textTransform: 'uppercase',
                              marginRight: 6,
                            }}>{seedDetail?.type || 'Asset'} {String.fromCharCode(183)} {tree.id}</span>
                            {seedDetail?.name || tree.id}
                          </div>
                          {tree.children.length === 0 ? (
                            <div style={{
                              fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink3,
                              fontStyle: 'italic', paddingLeft: 12,
                            }}>No downstream dependencies.</div>
                          ) : tree.children.map((child, idx) => (
                            <CascadeTreeRow key={`${tree.id}-${child.id}-${idx}`} node={child}/>
                          ))}
                        </div>
                      );
                    })}
                  </>
                )}
              </div>
            </ReportSection>
          )}

          {/* 07 — Critical Contacts */}
          {sections.contacts && reportContacts.length > 0 && (
            <ReportSection title="Critical Contacts" idx={sectionIdx.contacts}>
              <p style={{
                fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink2,
                fontStyle: 'italic', margin: '0 0 10px 0', lineHeight: 1.4,
              }}>Department directors for areas touched by this scenario.</p>
              {reportContacts.map(c => (
                <div key={c.email} style={{
                  padding: '8px 0', borderBottom: `1px solid ${T.ruleSoft}`,
                  pageBreakInside: 'avoid',
                }}>
                  <div style={{
                    fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 600,
                    color: T.ink3, letterSpacing: '0.06em', textTransform: 'uppercase',
                  }}>{c.dept}</div>
                  <div style={{
                    fontFamily: '"Zilla Slab", serif', fontSize: 13, fontWeight: 600,
                    color: T.darkBlue, marginBottom: 2,
                  }}>{c.name} — <span style={{
                    fontFamily: 'Poppins, sans-serif', fontSize: 11, fontWeight: 500, color: T.ink2,
                  }}>{c.title}</span></div>
                  <div style={{
                    fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink,
                  }}>{c.phone} · {c.email}</div>
                </div>
              ))}
            </ReportSection>
          )}

          {/* 08 — Short-Term Options by Asset */}
          {sections.shortTermByAsset && shortTermByAsset.length > 0 && (
            <ReportSection title="Short-Term Options by Asset" idx={sectionIdx.shortTermByAsset}>
              <p style={{
                fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink2,
                fontStyle: 'italic', margin: '0 0 12px 0', lineHeight: 1.4,
              }}>Full list of short-term options and considerations for each scenario asset.</p>
              {shortTermByAsset.map(group => {
                const meta = STATE_META[group.state];
                return (
                  <div key={group.assetId} style={{
                    marginBottom: 18, paddingBottom: 12,
                    pageBreakInside: 'auto',
                  }}>
                    {/* Asset header */}
                    <div style={{
                      display: 'flex', alignItems: 'center', gap: 8,
                      marginBottom: 8, paddingBottom: 4,
                      borderBottom: `1.5px solid ${meta.accent}`,
                      flexWrap: 'wrap',
                    }}>
                      <div style={{ width: 4, height: 14, background: meta.accent }}/>
                      <span style={{
                        fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 700,
                        color: T.ink3, letterSpacing: '0.06em', textTransform: 'uppercase',
                      }}>{group.assetType} - {group.assetId}</span>
                      <span style={{
                        padding: '1px 6px', background: meta.color, color: '#fff',
                        fontFamily: 'Poppins, sans-serif', fontSize: 8, fontWeight: 700,
                        letterSpacing: '0.08em',
                      }}>{meta.short}</span>
                      <span style={{
                        fontFamily: '"Zilla Slab", serif', fontSize: 14, fontWeight: 600,
                        color: T.darkBlue,
                      }}>{group.assetName}</span>
                      <span style={{
                        marginLeft: 'auto',
                        fontFamily: '"Zilla Slab", serif', fontSize: 14, fontWeight: 700,
                        color: meta.accent,
                      }}>{group.assetScore}</span>
                    </div>
                    {/* Items */}
                    {group.items.map((it, ii) => (
                      <div key={ii} style={{
                        marginBottom: 10, paddingLeft: 12,
                        borderLeft: `2px solid ${T.ruleSoft}`,
                        pageBreakInside: 'avoid',
                      }}>
                        <div style={{
                          display: 'flex', gap: 8, alignItems: 'baseline', marginBottom: 4,
                        }}>
                          <span style={{
                            fontFamily: '"Zilla Slab", serif', fontSize: 12, fontWeight: 700,
                            color: T.teal, minWidth: 22,
                          }}>{String(ii + 1).padStart(2, '0')}</span>
                          <div style={{
                            flex: 1,
                            fontFamily: '"Zilla Slab", serif', fontSize: 13, fontWeight: 600,
                            color: T.darkBlue, lineHeight: 1.25,
                          }}>{it.head}</div>
                        </div>
                        {it.body && it.body.length > 0 && (
                          <ul style={{
                            listStyle: 'none', padding: 0, margin: '0 0 0 30px',
                          }}>
                            {it.body.map((b, bi) => (
                              <li key={bi} style={{
                                display: 'flex', gap: 6, padding: '2px 0',
                                fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink,
                                lineHeight: 1.45,
                              }}>
                                <span style={{ color: T.teal }}>›</span>
                                <span>{b}</span>
                              </li>
                            ))}
                          </ul>
                        )}
                      </div>
                    ))}
                  </div>
                );
              })}
            </ReportSection>
          )}

          {/* 09 — Scenario Notes Log */}
          {sections.notes && scenarioNotes.length > 0 && (
            <ReportSection title="Scenario Notes Log" idx={sectionIdx.notes}>
              <p style={{
                fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink2,
                fontStyle: 'italic', margin: '0 0 12px 0', lineHeight: 1.4,
              }}>Append-only running log of decisions, observations, and status updates captured during this scenario. Newest entries first.</p>
              {[...scenarioNotes]
                .sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp))
                .map(entry => {
                  const d = new Date(entry.timestamp);
                  const dateStr = d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
                  const timeStr = d.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' });
                  return (
                    <div key={entry.id} style={{
                      marginBottom: 10, padding: '10px 12px',
                      background: T.surface, border: `1px solid ${T.rule}`,
                      borderLeft: `4px solid ${T.teal}`,
                      pageBreakInside: 'avoid',
                    }}>
                      <div style={{
                        display: 'flex', justifyContent: 'space-between',
                        alignItems: 'baseline', marginBottom: 6, paddingBottom: 4,
                        borderBottom: `1px solid ${T.ruleSoft}`,
                      }}>
                        <div style={{
                          fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 700,
                          color: T.darkBlue, letterSpacing: '0.1em', textTransform: 'uppercase',
                        }}>{dateStr} · {timeStr}</div>
                        <div style={{
                          fontFamily: 'Poppins, sans-serif', fontSize: 9, color: T.ink3,
                          fontStyle: 'italic',
                        }}>{entry.author || 'User'}</div>
                      </div>
                      <div style={{
                        fontFamily: 'Poppins, sans-serif', fontSize: 11.5, color: T.ink,
                        lineHeight: 1.5, whiteSpace: 'pre-wrap', wordBreak: 'break-word',
                      }}>{entry.text}</div>
                    </div>
                  );
                })}
            </ReportSection>
          )}

          {/* Footer */}
          <div style={{
            marginTop: 22, paddingTop: 12,
            borderTop: `1px solid ${T.rule}`,
            fontFamily: 'Poppins, sans-serif', fontSize: 9, color: T.ink3,
            display: 'flex', justifyContent: 'space-between',
            letterSpacing: '0.06em',
          }}>
            <span>{DST_CONFIG.copy.portFooter}</span>
            <span>{reportDate}</span>
          </div>
        </div>
      </div>
      <BottomNav onPrevious={onBack} onHome={onHome}/>
    </>
  );
}

function ReportSection({ title, idx, children }) {
  return (
    <div className="dst-report-section" style={{
      marginBottom: 22, pageBreakInside: 'auto',
    }}>
      <div className="dst-section-subhead" style={{
        display: 'flex', alignItems: 'baseline', gap: 8,
        marginBottom: 12, paddingBottom: 6,
        borderBottom: `2px solid ${T.darkBlue}`,
      }}>
        <span style={{
          fontFamily: '"Zilla Slab", serif', fontSize: 14, fontWeight: 400,
          color: T.lightTeal,
        }}>{idx}</span>
        <h2 style={{
          fontFamily: '"Zilla Slab", serif', fontSize: 17, fontWeight: 600,
          color: T.darkBlue, letterSpacing: '-0.01em', margin: 0,
        }}>{title}</h2>
      </div>
      {children}
    </div>
  );
}

function CascadeReportRow({ item, showDepth }) {
  const b = band(item.score || 0, item.type || 'Process');
  return (
    <div style={{
      display: 'flex', gap: 8, padding: '5px 4px',
      borderBottom: `1px solid ${T.ruleSoft}`,
      alignItems: 'center',
    }}>
      <div style={{
        fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 600,
        color: T.ink3, letterSpacing: '0.04em', textTransform: 'uppercase',
        minWidth: 64,
      }}>{item.type} - {item.id}</div>
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{
          fontFamily: 'Poppins, sans-serif', fontSize: 11, fontWeight: 500,
          color: T.ink, lineHeight: 1.25,
          overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
        }}>{item.name}</div>
        {item.dept && (
          <div style={{
            fontFamily: 'Poppins, sans-serif', fontSize: 9, color: T.ink3,
          }}>{item.dept}</div>
        )}
      </div>
      {showDepth && item.depth && (
        <span style={{
          padding: '1px 5px', background: T.surfaceAlt, border: `1px solid ${T.rule}`,
          fontFamily: 'Poppins, sans-serif', fontSize: 8, fontWeight: 700,
          color: T.ink2, letterSpacing: '0.06em',
        }}>L{item.depth}</span>
      )}
      {item.score > 0 && (
        <span style={{
          padding: '2px 6px', background: b.soft, color: b.color,
          fontFamily: '"Zilla Slab", serif', fontSize: 11, fontWeight: 700,
          minWidth: 26, textAlign: 'center',
        }}>{item.score}</span>
      )}
    </div>
  );
}

/* Recursive renderer for the full cascade tree (Option A in the report).
   Indents progressively by depth. Renders every node; "isDup" nodes show
   a small badge but no further descent. Designed for print: no interactivity,
   no expand/collapse. */
function CascadeTreeRow({ node }) {
  const detail = getCascadeItem(node.id);
  if (!detail) return null;
  const b = band(detail.score || 0, detail.type || 'Process');
  const indent = node.depth * 14;
  return (
    <>
      <div style={{
        display: 'flex', gap: 6, padding: '4px 0', alignItems: 'center',
        marginLeft: indent, borderBottom: `1px solid ${T.ruleSoft}`,
      }}>
        {/* Tree connector */}
        <span style={{
          color: T.ink3, fontFamily: 'Poppins, sans-serif', fontSize: 10,
          minWidth: 12, flexShrink: 0,
        }}>{String.fromCharCode(8627)}</span>
        {/* Type/ID */}
        <span style={{
          fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 600,
          color: T.ink3, letterSpacing: '0.04em', textTransform: 'uppercase',
          minWidth: 60, flexShrink: 0,
        }}>{detail.type} - {node.id}</span>
        {/* Name + dept */}
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{
            fontFamily: 'Poppins, sans-serif', fontSize: 10.5, fontWeight: 500,
            color: T.ink, lineHeight: 1.25,
            overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
          }}>{detail.name}</div>
          {detail.dept && (
            <div style={{
              fontFamily: 'Poppins, sans-serif', fontSize: 9, color: T.ink3,
            }}>{detail.dept}</div>
          )}
        </div>
        {/* Dup or Seed badge */}
        {node.isDup && (
          <span style={{
            padding: '1px 5px', background: T.surfaceAlt,
            border: `1px solid ${T.rule}`, color: T.ink3,
            fontFamily: 'Poppins, sans-serif', fontSize: 8, fontWeight: 700,
            letterSpacing: '0.06em',
          }}>DUP</span>
        )}
        {node.isSeed && !node.isDup && (
          <span style={{
            padding: '1px 5px', background: T.criticalSoft,
            border: `1px solid ${T.critical}`, color: T.critical,
            fontFamily: 'Poppins, sans-serif', fontSize: 8, fontWeight: 700,
            letterSpacing: '0.06em',
          }}>SEED</span>
        )}
        {/* Score badge */}
        {detail.score > 0 && (
          <span style={{
            padding: '2px 5px', background: b.soft, color: b.color,
            fontFamily: '"Zilla Slab", serif', fontSize: 10, fontWeight: 700,
            minWidth: 24, textAlign: 'center', flexShrink: 0,
          }}>{detail.score}</span>
        )}
      </div>
      {/* Render children — only if this node wasn't a dup (dups don't recurse) */}
      {!node.isDup && node.children && node.children.map((child, idx) => (
        <CascadeTreeRow key={`${node.id}-${child.id}-${idx}`} node={child}/>
      ))}
    </>
  );
}

/* ============================================================================
   SCENARIO NOTES SCREEN — append-only timestamped log
   ============================================================================ */

function NotesScreen({ scenarioName, scenarioNotes = [], onAddNote, onBack, onHome, scenarioCount, onScenarioTap }) {
  const [draft, setDraft] = useState('');

  // Show entries newest-first
  const sorted = useMemo(() =>
    [...scenarioNotes].sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp)),
  [scenarioNotes]);

  const formatTs = (iso) => {
    const d = new Date(iso);
    const dateStr = d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
    const timeStr = d.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' });
    return { date: dateStr, time: timeStr };
  };

  const handleAdd = () => {
    if (!draft.trim()) return;
    onAddNote(draft);
    setDraft('');
  };

  return (
    <>
      <TopNav back={onBack} title="Scenario Notes" sub={scenarioName || 'Untitled Scenario'}
        scenarioCount={scenarioCount} onScenarioTap={onScenarioTap}/>

      <div style={{
        padding: '14px 16px 200px', // bottom padding accounts for sticky input
      }}>
        {/* Context */}
        <div style={{
          padding: '10px 12px', background: T.surfaceAlt, border: `1px solid ${T.lightTeal}`,
          marginBottom: 14,
        }}>
          <div style={{
            fontFamily: 'Poppins, sans-serif', fontSize: 9, color: T.darkBlue,
            letterSpacing: '0.12em', textTransform: 'uppercase', fontWeight: 700,
            marginBottom: 3,
          }}>Running Log</div>
          <div style={{
            fontFamily: 'Poppins, sans-serif', fontSize: 12, color: T.ink, lineHeight: 1.45,
          }}>
            Append-only timestamped log for this scenario. Entries cannot be edited once added —
            keeps the record of decision-making intact.
          </div>
        </div>

        {/* Entry count */}
        {sorted.length > 0 ? (
          <div style={{
            fontFamily: 'Poppins, sans-serif', fontSize: 10, color: T.ink3,
            letterSpacing: '0.14em', textTransform: 'uppercase', fontWeight: 700,
            marginBottom: 10,
            display: 'flex', justifyContent: 'space-between',
          }}>
            <span>{sorted.length} {sorted.length === 1 ? 'Entry' : 'Entries'}</span>
            <span style={{ color: T.teal }}>Newest First</span>
          </div>
        ) : (
          <div style={{
            padding: '32px 20px', textAlign: 'center',
            fontFamily: 'Poppins, sans-serif', color: T.ink3,
          }}>
            <FileText size={32} color={T.ink3} strokeWidth={1.25} style={{ marginBottom: 10 }}/>
            <div style={{
              fontFamily: '"Zilla Slab", serif', fontSize: 16, fontWeight: 600,
              color: T.darkBlue, marginBottom: 4,
            }}>No entries yet</div>
            <div style={{ fontSize: 12 }}>
              Add the first entry below to start a running log of decisions and observations.
            </div>
          </div>
        )}

        {/* Entries — log style */}
        {sorted.map((entry, idx) => {
          const { date, time } = formatTs(entry.timestamp);
          return (
            <div key={entry.id} style={{
              marginBottom: 10, padding: '12px 14px',
              background: T.surface, border: `1px solid ${T.rule}`,
              borderLeft: `4px solid ${T.teal}`,
            }}>
              <div style={{
                display: 'flex', justifyContent: 'space-between', alignItems: 'baseline',
                marginBottom: 6, paddingBottom: 5,
                borderBottom: `1px solid ${T.ruleSoft}`,
              }}>
                <div style={{
                  fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 700,
                  color: T.darkBlue, letterSpacing: '0.1em', textTransform: 'uppercase',
                }}>{date} · {time}</div>
                <div style={{
                  fontFamily: 'Poppins, sans-serif', fontSize: 9, color: T.ink3,
                  fontStyle: 'italic',
                }}>{entry.author || 'User'}</div>
              </div>
              <div style={{
                fontFamily: 'Poppins, sans-serif', fontSize: 12.5, color: T.ink,
                lineHeight: 1.5, whiteSpace: 'pre-wrap', wordBreak: 'break-word',
              }}>{entry.text}</div>
            </div>
          );
        })}
      </div>

      {/* Sticky input bar */}
      <div style={{
        position: 'sticky', bottom: 56, zIndex: 30,
        background: T.bg, borderTop: `1px solid ${T.rule}`,
        padding: '10px 14px',
      }}>
        <div style={{
          fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 700,
          letterSpacing: '0.12em', textTransform: 'uppercase', color: T.ink3,
          marginBottom: 5,
        }}>New Entry</div>
        <textarea
          value={draft}
          onChange={e => setDraft(e.target.value)}
          placeholder="Decision, observation, or status update…"
          rows={2}
          style={{
            width: '100%', padding: '8px 10px', marginBottom: 8,
            fontFamily: 'Poppins, sans-serif', fontSize: 12.5, color: T.ink,
            border: `1.5px solid ${T.rule}`, outline: 'none',
            resize: 'vertical', boxSizing: 'border-box',
            lineHeight: 1.45,
          }}/>
        <button
          onClick={handleAdd}
          disabled={!draft.trim()}
          style={{
            width: '100%', padding: '11px',
            background: draft.trim() ? T.darkBlue : T.rule,
            color: '#fff', border: 'none',
            cursor: draft.trim() ? 'pointer' : 'not-allowed',
            fontFamily: 'Poppins, sans-serif', fontSize: 11, fontWeight: 700,
            letterSpacing: '0.1em', textTransform: 'uppercase',
            display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: 6,
          }}>
          <Plus size={13}/> Add Entry
        </button>
      </div>

      <BottomNav onPrevious={onBack} onHome={onHome}/>
    </>
  );
}

/* ============================================================================
   ADMIN PORTAL — user management. Production wires to Cognito Admin APIs
   via Lambda. Mockup mutates the in-memory user list directly.
   ============================================================================ */

function AdminPortalScreen({ users = [], currentUser, onInvite, onUpdateUser, onResetCredential, onBack, onHome, scenarioCount, onScenarioTap }) {
  const [filter, setFilter] = useState('all'); // 'all' | 'active' | 'pending' | 'deactivated'
  const [query, setQuery] = useState('');
  const [inviteOpen, setInviteOpen] = useState(false);
  const [actionUserId, setActionUserId] = useState(null);
  const [flash, setFlash] = useState(null);

  const filtered = useMemo(() => {
    let r = [...users];
    if (filter !== 'all') r = r.filter(u => u.status === filter);
    if (query) {
      const q = query.toLowerCase();
      r = r.filter(u => (u.name || '').toLowerCase().includes(q)
        || (u.email || '').toLowerCase().includes(q));
    }
    // Stable order: active first, then pending, then deactivated; within each, alpha by name
    const statusOrder = { active: 0, pending: 1, deactivated: 2 };
    return r.sort((a, b) => {
      const so = statusOrder[a.status] - statusOrder[b.status];
      if (so !== 0) return so;
      return (a.name || '').localeCompare(b.name || '');
    });
  }, [users, filter, query]);

  const counts = useMemo(() => ({
    all:         users.length,
    active:      users.filter(u => u.status === 'active').length,
    pending:     users.filter(u => u.status === 'pending').length,
    deactivated: users.filter(u => u.status === 'deactivated').length,
  }), [users]);

  const showFlash = (kind, message, durationMs = 2400) => {
    setFlash({ kind, message });
    setTimeout(() => setFlash(null), durationMs);
  };

  const handleInvite = async (data) => {
    const result = await onInvite(data);
    setInviteOpen(false);
    if (result?.ok) {
      // Long timeout so admin has time to copy the temp password from the
      // flash. They need to communicate it out-of-band to the invited user.
      showFlash('ok',
        `${data.email} invited. Temp password: ${result.tempPassword} - copy and communicate now.`,
        15000);
    } else {
      showFlash('err', result?.error || 'Invite failed.');
    }
  };

  const actionUser = actionUserId ? users.find(u => u.id === actionUserId) : null;

  return (
    <>
      <TopNav back={onBack} title="Admin Portal" sub="User management"
        scenarioCount={scenarioCount} onScenarioTap={onScenarioTap}/>

      <div style={{ padding: '14px 16px 24px' }}>
        {/* Storage / scope note */}
        <div style={{
          padding: '10px 12px', background: T.surfaceAlt, border: `1px solid ${T.lightTeal}`,
          marginBottom: 12,
        }}>
          <div style={{
            fontFamily: 'Poppins, sans-serif', fontSize: 9, color: T.darkBlue,
            letterSpacing: '0.12em', textTransform: 'uppercase', fontWeight: 700,
            marginBottom: 3,
          }}>User Management</div>
          <div style={{
            fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink, lineHeight: 1.45,
          }}>
            {DST_CONFIG.copy.adminPortalBlurb}
          </div>
        </div>

        {/* Action bar */}
        <button onClick={() => setInviteOpen(true)} style={{
          width: '100%', padding: '12px',
          background: T.darkBlue, color: '#fff', border: 'none', cursor: 'pointer',
          fontFamily: 'Poppins, sans-serif', fontSize: 11, fontWeight: 700,
          letterSpacing: '0.12em', textTransform: 'uppercase',
          display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: 6,
          marginBottom: 12,
        }}>
          <Plus size={14}/> Invite User
        </button>

        {/* Search */}
        <div style={{
          display: 'flex', alignItems: 'center', gap: 8, padding: '8px 12px',
          border: `1px solid ${T.rule}`, background: T.surface, marginBottom: 10,
        }}>
          <Search size={14} color={T.ink3}/>
          <input value={query} onChange={e => setQuery(e.target.value)}
            placeholder="Search by name or email…"
            style={{
              border: 'none', outline: 'none', flex: 1,
              fontFamily: 'Poppins, sans-serif', fontSize: 13,
              color: T.ink, background: 'transparent',
            }}/>
          {query && <button onClick={() => setQuery('')} style={{
            background: 'none', border: 'none', cursor: 'pointer',
            color: T.ink3, padding: 0, display: 'inline-flex',
          }}><X size={14}/></button>}
        </div>

        {/* Status tabs */}
        <div style={{
          display: 'flex', border: `1px solid ${T.rule}`, background: T.surface,
          overflowX: 'auto', marginBottom: 12,
        }}>
          {[
            { k: 'all',         label: 'All' },
            { k: 'active',      label: 'Active' },
            { k: 'pending',     label: 'Pending' },
            { k: 'deactivated', label: 'Inactive' },
          ].map(({ k, label }) => (
            <button key={k} onClick={() => setFilter(k)} style={{
              flex: 1, padding: '8px 10px', border: 'none', cursor: 'pointer',
              fontFamily: 'Poppins, sans-serif', fontSize: 10, fontWeight: 600,
              letterSpacing: '0.08em', textTransform: 'uppercase',
              background: filter === k ? T.darkBlue : 'transparent',
              color: filter === k ? '#fff' : T.ink2,
              display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: 4,
              flexShrink: 0,
            }}>
              {label}
              <span style={{
                padding: '0 5px',
                background: filter === k ? 'rgba(255,255,255,0.2)' : T.surfaceAlt,
                color: filter === k ? '#fff' : T.ink3,
                fontSize: 9, fontWeight: 700, borderRadius: 0,
              }}>{counts[k]}</span>
            </button>
          ))}
        </div>

        {flash && (
          <div style={{
            marginBottom: 10, padding: '8px 12px',
            background: flash.kind === 'ok' ? T.lowSoft : T.criticalSoft,
            border: `1px solid ${flash.kind === 'ok' ? T.low : T.critical}`,
            fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink,
            display: 'flex', alignItems: 'center', gap: 6,
          }}>
            <Check size={13} color={flash.kind === 'ok' ? T.low : T.critical} strokeWidth={2.5}/>
            {flash.message}
          </div>
        )}

        {/* User list */}
        {filtered.length === 0 ? (
          <div style={{
            padding: '40px 20px', textAlign: 'center',
            fontFamily: 'Poppins, sans-serif', color: T.ink3, fontSize: 13,
          }}>No users match.</div>
        ) : filtered.map(u => {
          const role = USER_ROLES[u.role] || USER_ROLES.user;
          const status = USER_STATUS[u.status] || USER_STATUS.active;
          const isCurrent = currentUser && u.id === currentUser.id;
          return (
            <button key={u.id}
              onClick={() => setActionUserId(u.id)}
              style={{
                width: '100%', display: 'flex', gap: 12, alignItems: 'center',
                padding: '12px 10px', textAlign: 'left',
                cursor: 'pointer',
                background: T.surface,
                border: 'none', borderBottom: `1px solid ${T.ruleSoft}`,
                fontFamily: 'inherit',
                opacity: u.status === 'deactivated' ? 0.65 : 1,
              }}>
              {/* Avatar circle with initial */}
              <div style={{
                width: 36, height: 36, flexShrink: 0,
                background: role.soft, color: role.color,
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                fontFamily: '"Zilla Slab", serif', fontSize: 16, fontWeight: 700,
                border: `1.5px solid ${role.color}`,
              }}>
                {(u.name || u.email).charAt(0).toUpperCase()}
              </div>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{
                  display: 'flex', alignItems: 'baseline', gap: 6, marginBottom: 2,
                  flexWrap: 'wrap',
                }}>
                  <span style={{
                    fontFamily: '"Zilla Slab", serif', fontSize: 14, fontWeight: 600,
                    color: T.darkBlue,
                  }}>{u.name || u.email}</span>
                  {isCurrent && (
                    <span style={{
                      padding: '1px 5px', background: T.teal, color: '#fff',
                      fontFamily: 'Poppins, sans-serif', fontSize: 8, fontWeight: 700,
                      letterSpacing: '0.08em',
                    }}>YOU</span>
                  )}
                </div>
                <div style={{
                  fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink2,
                  marginBottom: 3, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
                }}>{u.email}</div>
                <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap' }}>
                  <span style={{
                    padding: '1px 6px', background: role.soft, color: role.color,
                    fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 700,
                    letterSpacing: '0.08em', textTransform: 'uppercase',
                  }}>{role.label}</span>
                  <span style={{
                    padding: '1px 6px', background: status.soft, color: status.color,
                    fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 700,
                    letterSpacing: '0.08em', textTransform: 'uppercase',
                  }}>{status.label}</span>
                  <span style={{
                    fontFamily: 'Poppins, sans-serif', fontSize: 9, color: T.ink3,
                    letterSpacing: '0.04em',
                  }}>
                    {u.lastLogin ? `Last login ${formatRelativeDate(u.lastLogin)}` : 'Never logged in'}
                  </span>
                </div>
              </div>
              <ChevronRight size={14} color={T.ink3}/>
            </button>
          );
        })}
      </div>

      {/* Invite User sheet */}
      <Sheet open={inviteOpen} onClose={() => setInviteOpen(false)} title="Invite User">
        <InviteUserForm onCancel={() => setInviteOpen(false)} onSubmit={handleInvite}/>
      </Sheet>

      {/* User Action sheet */}
      <Sheet open={!!actionUser} onClose={() => setActionUserId(null)} title="User Actions">
        {actionUser && (
          <UserActions
            user={actionUser}
            currentUser={currentUser}
            onUpdate={async (updates) => {
              const result = await onUpdateUser(actionUser.id, updates);
              setActionUserId(null);
              if (result?.ok) {
                showFlash('ok', `${actionUser.name || actionUser.email} updated.`);
              } else {
                showFlash('err', result?.error || 'Update failed.');
              }
            }}
            onResetCredential={async () => {
              const result = await onResetCredential(actionUser.id);
              setActionUserId(null);
              if (result?.ok) {
                showFlash('ok',
                  `${actionUser.email} reset. Temp password: ${result.tempPassword} - copy and communicate now.`,
                  15000);
              } else {
                showFlash('err', result?.error || 'Reset failed.');
              }
            }}
            onClose={() => setActionUserId(null)}
          />
        )}
      </Sheet>

      <BottomNav onPrevious={onBack} onHome={onHome}/>
    </>
  );
}

function InviteUserForm({ onCancel, onSubmit }) {
  const [email, setEmail] = useState('');
  const [name, setName] = useState('');
  const [role, setRole] = useState('user');
  const [error, setError] = useState(null);

  const handleSubmit = () => {
    setError(null);
    const trimmed = email.trim().toLowerCase();
    if (!trimmed.includes('@')) { setError('Enter a valid email.'); return; }
    onSubmit({ email: trimmed, name: name.trim() || trimmed, role });
  };

  return (
    <>
      <div style={{
        padding: '10px 12px', background: T.surfaceAlt, border: `1px solid ${T.lightTeal}`,
        marginBottom: 16, fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink2,
        lineHeight: 1.45,
      }}>
        A temporary password will be generated. Copy it from the confirmation
        and communicate it to the user out-of-band (phone, text, or in person).
        They'll be required to set a new password on first sign-in.
      </div>

      <div style={{
        fontFamily: 'Poppins, sans-serif', fontSize: 10, color: T.ink3,
        letterSpacing: '0.14em', textTransform: 'uppercase', fontWeight: 700, marginBottom: 6,
      }}>Email Address</div>
      <input
        type="email"
        value={email}
        onChange={e => setEmail(e.target.value)}
        autoFocus
        placeholder={`user@${DST_CONFIG.org.emailDomain}`}
        autoCapitalize="none"
        style={{
          width: '100%', padding: '10px 12px', boxSizing: 'border-box', marginBottom: 12,
          fontFamily: 'Poppins, sans-serif', fontSize: 14, color: T.ink,
          border: `1.5px solid ${T.rule}`, outline: 'none',
        }}/>

      <div style={{
        fontFamily: 'Poppins, sans-serif', fontSize: 10, color: T.ink3,
        letterSpacing: '0.14em', textTransform: 'uppercase', fontWeight: 700, marginBottom: 6,
      }}>Display Name <span style={{ fontWeight: 400, fontStyle: 'italic' }}>(optional)</span></div>
      <input
        type="text"
        value={name}
        onChange={e => setName(e.target.value)}
        placeholder="Full name"
        style={{
          width: '100%', padding: '10px 12px', boxSizing: 'border-box', marginBottom: 16,
          fontFamily: 'Poppins, sans-serif', fontSize: 14, color: T.ink,
          border: `1.5px solid ${T.rule}`, outline: 'none',
        }}/>

      <div style={{
        fontFamily: 'Poppins, sans-serif', fontSize: 10, color: T.ink3,
        letterSpacing: '0.14em', textTransform: 'uppercase', fontWeight: 700, marginBottom: 8,
      }}>Role</div>
      <div style={{ marginBottom: 16 }}>
        {Object.entries(USER_ROLES).map(([k, m]) => (
          <button key={k} onClick={() => setRole(k)} style={{
            width: '100%', display: 'flex', alignItems: 'center', gap: 10,
            padding: '10px 12px', marginBottom: 6,
            background: role === k ? m.soft : T.surface,
            border: `1.5px solid ${role === k ? m.color : T.rule}`,
            cursor: 'pointer', textAlign: 'left', fontFamily: 'inherit',
          }}>
            <div style={{ width: 4, height: 28, background: m.color, flexShrink: 0 }}/>
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{
                fontFamily: '"Zilla Slab", serif', fontSize: 13, fontWeight: 600,
                color: m.color, marginBottom: 1,
              }}>{m.label}</div>
              <div style={{
                fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink2,
                lineHeight: 1.35,
              }}>{m.description}</div>
            </div>
            {role === k && <Check size={14} color={m.color} strokeWidth={3}/>}
          </button>
        ))}
      </div>

      {error && (
        <div style={{
          marginBottom: 12, padding: '8px 10px',
          background: T.criticalSoft, border: `1px solid ${T.critical}`,
          fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink,
        }}>{error}</div>
      )}

      <div style={{ display: 'flex', gap: 8 }}>
        <button onClick={onCancel} style={{
          flex: 1, padding: '12px',
          background: 'transparent', color: T.ink2,
          border: `1.5px solid ${T.rule}`, cursor: 'pointer',
          fontFamily: 'Poppins, sans-serif', fontSize: 11, fontWeight: 700,
          letterSpacing: '0.1em', textTransform: 'uppercase',
        }}>Cancel</button>
        <button onClick={handleSubmit} style={{
          flex: 1, padding: '12px',
          background: T.darkBlue, color: '#fff', border: 'none', cursor: 'pointer',
          fontFamily: 'Poppins, sans-serif', fontSize: 11, fontWeight: 700,
          letterSpacing: '0.1em', textTransform: 'uppercase',
          display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: 6,
        }}>
          <Send size={13}/> Send Invite
        </button>
      </div>
    </>
  );
}

function UserActions({ user, currentUser, onUpdate, onResetCredential, onClose }) {
  const role = USER_ROLES[user.role];
  const status = USER_STATUS[user.status];
  const isSelf = currentUser && user.id === currentUser.id;

  return (
    <>
      {/* User context */}
      <div style={{
        padding: '12px', marginBottom: 16,
        background: T.surfaceAlt, border: `1px solid ${T.lightTeal}`,
      }}>
        <div style={{
          fontFamily: '"Zilla Slab", serif', fontSize: 16, fontWeight: 600,
          color: T.darkBlue, marginBottom: 2,
        }}>{user.name || user.email}</div>
        <div style={{
          fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink2, marginBottom: 6,
        }}>{user.email}</div>
        <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap' }}>
          <span style={{
            padding: '1px 6px', background: role.soft, color: role.color,
            fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 700,
            letterSpacing: '0.08em', textTransform: 'uppercase',
          }}>{role.label}</span>
          <span style={{
            padding: '1px 6px', background: status.soft, color: status.color,
            fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 700,
            letterSpacing: '0.08em', textTransform: 'uppercase',
          }}>{status.label}</span>
        </div>
      </div>

      {/* Role change */}
      <div style={{
        fontFamily: 'Poppins, sans-serif', fontSize: 10, color: T.ink3,
        letterSpacing: '0.14em', textTransform: 'uppercase', fontWeight: 700, marginBottom: 6,
      }}>Change Role</div>
      <div style={{ display: 'flex', gap: 6, marginBottom: 16 }}>
        {Object.entries(USER_ROLES).map(([k, m]) => (
          <button key={k}
            onClick={() => onUpdate({ role: k })}
            disabled={user.role === k || isSelf}
            style={{
              flex: 1, padding: '10px',
              background: user.role === k ? m.soft : T.surface,
              border: `1.5px solid ${user.role === k ? m.color : T.rule}`,
              cursor: (user.role === k || isSelf) ? 'not-allowed' : 'pointer',
              fontFamily: 'Poppins, sans-serif', fontSize: 11, fontWeight: 700,
              color: user.role === k ? m.color : T.ink2,
              letterSpacing: '0.08em', textTransform: 'uppercase',
              opacity: isSelf ? 0.5 : 1,
            }}>{m.label}</button>
        ))}
      </div>
      {isSelf && (
        <div style={{
          marginTop: -10, marginBottom: 14,
          fontFamily: 'Poppins, sans-serif', fontSize: 10, color: T.ink3, fontStyle: 'italic',
        }}>You can't change your own role.</div>
      )}

      {/* Credential reset */}
      <button onClick={onResetCredential} style={{
        width: '100%', padding: '12px', marginBottom: 8,
        background: 'transparent', color: T.darkBlue,
        border: `1.5px solid ${T.darkBlue}`, cursor: 'pointer',
        fontFamily: 'Poppins, sans-serif', fontSize: 11, fontWeight: 700,
        letterSpacing: '0.1em', textTransform: 'uppercase',
        display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: 6,
      }}>
        <KeyRound size={14}/>
        Reset Password
      </button>

      {/* Status change */}
      {user.status !== 'deactivated' ? (
        <button
          onClick={() => onUpdate({ status: 'deactivated' })}
          disabled={isSelf}
          style={{
            width: '100%', padding: '12px', marginBottom: 8,
            background: 'transparent', color: T.critical,
            border: `1.5px solid ${T.critical}`,
            cursor: isSelf ? 'not-allowed' : 'pointer',
            fontFamily: 'Poppins, sans-serif', fontSize: 11, fontWeight: 700,
            letterSpacing: '0.1em', textTransform: 'uppercase',
            opacity: isSelf ? 0.5 : 1,
            display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: 6,
          }}>
          <X size={13}/> Deactivate User
        </button>
      ) : (
        <button
          onClick={() => onUpdate({ status: 'active' })}
          style={{
            width: '100%', padding: '12px', marginBottom: 8,
            background: T.low, color: '#fff', border: 'none', cursor: 'pointer',
            fontFamily: 'Poppins, sans-serif', fontSize: 11, fontWeight: 700,
            letterSpacing: '0.1em', textTransform: 'uppercase',
            display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: 6,
          }}>
          <Check size={13}/> Reactivate User
        </button>
      )}

      <button onClick={onClose} style={{
        width: '100%', padding: '12px',
        background: 'transparent', color: T.ink2,
        border: `1px solid ${T.rule}`, cursor: 'pointer',
        fontFamily: 'Poppins, sans-serif', fontSize: 11, fontWeight: 700,
        letterSpacing: '0.1em', textTransform: 'uppercase',
      }}>Close</button>
    </>
  );
}

/* ============================================================================
   MY SCENARIOS SCREEN — list of saved scenarios with load/delete
   ============================================================================ */

function MyScenariosScreen({ savedScenarios = [], onLoad, onDelete, onBack, onHome, scenarioCount, onScenarioTap }) {
  const [confirmDeleteId, setConfirmDeleteId] = useState(null);

  // Sort by most recently updated
  const sorted = useMemo(() =>
    [...savedScenarios].sort((a, b) =>
      new Date(b.updated || b.created) - new Date(a.updated || a.created)
    ),
  [savedScenarios]);

  return (
    <>
      <TopNav back={onBack} title="My Scenarios" sub="Saved on this device"
        scenarioCount={scenarioCount} onScenarioTap={onScenarioTap}/>

      <div style={{ padding: '14px 16px 20px' }}>
        {/* Storage note */}
        <div style={{
          padding: '8px 12px', background: T.bgAlt, border: `1px dashed ${T.rule}`,
          fontFamily: 'Poppins, sans-serif', fontSize: 10.5, color: T.ink2,
          lineHeight: 1.45, marginBottom: 14,
        }}>
          <strong style={{ color: T.darkBlue }}>Local to this device.</strong> Saved scenarios persist
          between sessions but don't sync across devices.
        </div>

        {sorted.length === 0 ? (
          <div style={{
            padding: '40px 20px', textAlign: 'center',
            fontFamily: 'Poppins, sans-serif', color: T.ink3,
          }}>
            <ClipboardList size={36} color={T.ink3} strokeWidth={1.25} style={{ marginBottom: 12 }}/>
            <div style={{
              fontFamily: '"Zilla Slab", serif', fontSize: 18, fontWeight: 600,
              color: T.darkBlue, marginBottom: 6,
            }}>No saved scenarios yet</div>
            <div style={{ fontSize: 13 }}>
              Build a scenario in Scenario Builder, then tap Save to keep it here.
            </div>
          </div>
        ) : (
          <>
            <div style={{
              fontFamily: 'Poppins, sans-serif', fontSize: 10, color: T.ink3,
              letterSpacing: '0.14em', textTransform: 'uppercase', fontWeight: 700,
              marginBottom: 10,
            }}>{sorted.length} Saved {sorted.length === 1 ? 'Scenario' : 'Scenarios'}</div>
            {sorted.map(s => {
              const stateCount = Object.values(s.scenarioStates || {}).filter(v => v && v !== 'disrupted').length;
              const hasWhatIf = stateCount > 0;
              const noteCount = (s.notes || []).length;
              const isConfirming = confirmDeleteId === s.id;
              return (
                <div key={s.id} style={{
                  marginBottom: 10, background: T.surface,
                  border: `1px solid ${T.rule}`,
                  borderLeft: `4px solid ${hasWhatIf ? T.teal : T.darkBlue}`,
                }}>
                  <div style={{
                    padding: '12px 14px',
                    display: 'flex', gap: 10, alignItems: 'flex-start',
                  }}>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{
                        fontFamily: '"Zilla Slab", serif', fontSize: 15, fontWeight: 600,
                        color: T.darkBlue, lineHeight: 1.2, marginBottom: 4,
                      }}>{s.name}</div>
                      <div style={{
                        display: 'flex', flexWrap: 'wrap', gap: 8,
                        fontFamily: 'Poppins, sans-serif', fontSize: 10.5, color: T.ink2,
                        marginBottom: 2,
                      }}>
                        <span><strong style={{ color: T.darkBlue }}>{s.scenario.length}</strong> {s.scenario.length === 1 ? 'asset' : 'assets'}</span>
                        {hasWhatIf && (
                          <span style={{
                            padding: '1px 6px', background: T.teal, color: '#fff',
                            fontSize: 9, fontWeight: 700, letterSpacing: '0.08em',
                            textTransform: 'uppercase',
                          }}>What-If · {stateCount}</span>
                        )}
                        {noteCount > 0 && (
                          <span style={{
                            padding: '1px 6px', background: T.surfaceAlt,
                            border: `1px solid ${T.rule}`, color: T.ink2,
                            fontSize: 9, fontWeight: 700, letterSpacing: '0.08em',
                            textTransform: 'uppercase',
                          }}>{noteCount} {noteCount === 1 ? 'note' : 'notes'}</span>
                        )}
                      </div>
                      <div style={{
                        fontFamily: 'Poppins, sans-serif', fontSize: 10, color: T.ink3,
                      }}>Saved {formatRelativeDate(s.updated || s.created)}</div>
                    </div>
                    <button onClick={() => setConfirmDeleteId(isConfirming ? null : s.id)}
                      style={{
                        background: 'transparent', border: 'none', cursor: 'pointer',
                        padding: 4, color: isConfirming ? T.critical : T.ink3,
                        display: 'inline-flex', flexShrink: 0,
                      }}>
                      <Trash2 size={16}/>
                    </button>
                  </div>
                  {isConfirming ? (
                    <div style={{
                      padding: '10px 14px', borderTop: `1px solid ${T.rule}`,
                      background: T.criticalSoft,
                    }}>
                      <div style={{
                        fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink,
                        marginBottom: 8, lineHeight: 1.4,
                      }}>Delete <strong>{s.name}</strong>? This cannot be undone.</div>
                      <div style={{ display: 'flex', gap: 8 }}>
                        <button onClick={() => setConfirmDeleteId(null)} style={{
                          flex: 1, padding: '8px',
                          background: T.surface, border: `1px solid ${T.rule}`, color: T.ink2,
                          cursor: 'pointer',
                          fontFamily: 'Poppins, sans-serif', fontSize: 10, fontWeight: 700,
                          letterSpacing: '0.08em', textTransform: 'uppercase',
                        }}>Cancel</button>
                        <button onClick={() => { onDelete(s.id); setConfirmDeleteId(null); }} style={{
                          flex: 1, padding: '8px',
                          background: T.critical, border: 'none', color: '#fff',
                          cursor: 'pointer',
                          fontFamily: 'Poppins, sans-serif', fontSize: 10, fontWeight: 700,
                          letterSpacing: '0.08em', textTransform: 'uppercase',
                        }}>Delete</button>
                      </div>
                    </div>
                  ) : (
                    <button onClick={() => onLoad(s)} style={{
                      width: '100%', padding: '10px',
                      background: T.surfaceAlt, border: 'none',
                      borderTop: `1px solid ${T.rule}`,
                      cursor: 'pointer', color: T.darkBlue,
                      fontFamily: 'Poppins, sans-serif', fontSize: 10.5, fontWeight: 700,
                      letterSpacing: '0.1em', textTransform: 'uppercase',
                      display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: 6,
                    }}>
                      Load Scenario <ChevronRight size={13}/>
                    </button>
                  )}
                </div>
              );
            })}
          </>
        )}
      </div>
      <BottomNav onPrevious={onBack} onHome={onHome}/>
    </>
  );
}

/* ============================================================================
   APP
   ============================================================================ */

function DSTApp() {
  const [screen, setScreen] = useState('login');
  const [category, setCategory] = useState(null);
  const [detailId, setDetailId] = useState(null);
  const [scenario, setScenario] = useState([]);
  const [scenarioStates, setScenarioStates] = useState({}); // id -> state string
  const [scenarioName, setScenarioName] = useState('Untitled Scenario');
  const [scenarioNotes, setScenarioNotes] = useState([]); // [{id, text, timestamp, author}]
  // Drawn areas (radius circles / polygons) captured from spatial selection,
  // for display on the generated report. Array supports multiple shapes.
  // Each entry: { kind:'radius', center:{lat,lng}, radiusMi }  OR
  //             { kind:'polygon', points:[{lat,lng}...] }
  const [scenarioGeometry, setScenarioGeometry] = useState([]);
  const [history, setHistory] = useState([]);
  const [cascadeMode, setCascadeMode] = useState('direct');

  // User and session state.
  // - `users` is the locally-cached list, seeded from SEED_USERS so the Admin
  //   Portal renders immediately. Admin operations update both the real
  //   Cognito User Pool (via adminApi) and this local cache.
  // - `currentUser` comes from the Cognito session (token claims).
  // - `idToken` is the JWT used for admin API calls. Refreshes transparently
  //   via the Cognito SDK; refreshed token comes back on next getCurrentSession.
  const [users, setUsers]                 = useState(SEED_USERS);
  const [currentUser, setCurrentUser]     = useState(null);
  const [idToken, setIdToken]             = useState(null);
  const [userMenuOpen, setUserMenuOpen]   = useState(false);

  // On app load, restore an existing Cognito session if the user still has
  // valid tokens in localStorage. Skips the login screen entirely if so.
  useEffect(() => {
    getCurrentSession().then(session => {
      if (session) {
        setCurrentUser(session.user);
        setIdToken(session.tokens.idToken);
        setScreen('home');
      }
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleLogin = (user, tokens) => {
    setCurrentUser(user);
    setIdToken(tokens.idToken);
    // Cache or update the local users list so the Admin Portal table includes
    // the signed-in user even if they weren't in the original SEED_USERS.
    setUsers(prev => {
      const idx = prev.findIndex(u => u.email.toLowerCase() === user.email.toLowerCase());
      const now = new Date().toISOString();
      if (idx === -1) {
        return [...prev, {
          id: `cog-${user.sub}`, email: user.email, name: user.name || user.email,
          role: user.role, status: user.status, authMode: 'password',
          lastLogin: now, invitedAt: now,
        }];
      }
      return prev.map((u, i) => i === idx
        ? { ...u, role: user.role, status: user.status, lastLogin: now }
        : u);
    });
    setScreen('home');
    setHistory([]);
  };

  const handleLogout = () => {
    signOut();
    setCurrentUser(null);
    setIdToken(null);
    setUserMenuOpen(false);
    // Clear in-progress work to be safe
    setScenario([]);
    setScenarioStates({});
    setScenarioNotes([]);
    setScenarioGeometry([]);
    setScenarioName('Untitled Scenario');
    setHistory([]);
    setScreen('login');
  };

  // Generate a strong temp password meeting Cognito's policy.
  // 16 chars, includes upper, lower, digit, symbol. Avoids ambiguous chars
  // (no I/l/1/0/O) for easier dictation. Avoids `!` so zsh history doesn't
  // misinterpret it when the user pastes the password into a command.
  const generateTempPassword = () => {
    const upper  = 'ABCDEFGHJKMNPQRSTUVWXYZ';
    const lower  = 'abcdefghjkmnpqrstuvwxyz';
    const digit  = '23456789';
    const symbol = '@#$%&*?';
    const all    = upper + lower + digit + symbol;
    const rand = s => s.charAt(Math.floor(Math.random() * s.length));
    let pw = rand(upper) + rand(lower) + rand(digit) + rand(symbol);
    for (let i = 0; i < 12; i++) pw += rand(all);
    return pw.split('').sort(() => Math.random() - 0.5).join('');
  };

  const inviteUser = async (data) => {
    const tempPassword = data.tempPassword || generateTempPassword();
    try {
      const response = await adminApi('invite', {
        email: data.email,
        name:  data.name || data.email,
        role:  data.role || 'user',
        tempPassword,
      }, idToken);
      setUsers(prev => [...prev, {
        id: `cog-${response.user.username}`, email: response.user.email,
        name: response.user.name, role: response.user.role, status: response.user.status,
        authMode: 'password', lastLogin: null, invitedAt: new Date().toISOString(),
      }]);
      return { ok: true, tempPassword: response.tempPassword, user: response.user };
    } catch (err) {
      return { ok: false, error: err.message || 'Invite failed' };
    }
  };

  const updateUser = async (userId, updates) => {
    const user = users.find(u => u.id === userId);
    if (!user) return { ok: false, error: 'User not found' };
    try {
      if (updates.role !== undefined && updates.role !== user.role) {
        await adminApi('changeRole', { email: user.email, role: updates.role }, idToken);
      }
      if (updates.status !== undefined && updates.status !== user.status) {
        if (updates.status === 'deactivated') {
          await adminApi('deactivate', { email: user.email }, idToken);
        } else if (updates.status === 'active') {
          await adminApi('reactivate', { email: user.email }, idToken);
        }
      }
      setUsers(prev => prev.map(u => u.id === userId ? { ...u, ...updates } : u));
      return { ok: true };
    } catch (err) {
      return { ok: false, error: err.message || 'Update failed' };
    }
  };

  const resetUserCredential = async (userId) => {
    const user = users.find(u => u.id === userId);
    if (!user) return { ok: false, error: 'User not found' };
    const tempPassword = generateTempPassword();
    try {
      const response = await adminApi('resetPassword', {
        email: user.email,
        tempPassword,
      }, idToken);
      return { ok: true, tempPassword: response.tempPassword };
    } catch (err) {
      return { ok: false, error: err.message || 'Reset failed' };
    }
  };

  const openAdmin = () => {
    setHistory(h => [...h, screen]);
    setScreen('admin');
  };

  // Saved scenarios — in-memory for the mockup; production swaps in localStorage
  // (read on mount, write on every change of `savedScenarios`).
  const [savedScenarios, setSavedScenarios] = useState([
    {
      id: 'demo-1',
      name: 'Cyber outage — Tidalis impact',
      created: '2026-04-22T14:30:00Z',
      updated: '2026-04-22T14:30:00Z',
      scenario: ['T2-01', '2CO07', '2CO08'],
      scenarioStates: { '2CO08': 'manual' },
      notes: [
        { id: 'n-1', text: 'Tidalis OS unresponsive across multiple workstations. Vendor notified. Initial scope unclear.', timestamp: '2026-04-22T14:30:00Z', author: 'User' },
        { id: 'n-2', text: 'Vessel Movement Execution running on phone radio + paper charts. USCG advised.', timestamp: '2026-04-22T15:12:00Z', author: 'User' },
      ],
    },
    {
      id: 'demo-2',
      name: 'Hurricane post-event channel reopen',
      created: '2026-04-19T09:15:00Z',
      updated: '2026-04-19T09:15:00Z',
      scenario: ['2CO02', '2CO01', 'FLS1001'],
      scenarioStates: {},
      notes: [],
    },
  ]);

  const data = { processes: PROCESSES, systems: SYSTEMS, facilities: FACILITIES };

  // Notes — append-only log
  const addScenarioNote = (text) => {
    const trimmed = (text || '').trim();
    if (!trimmed) return;
    const entry = {
      id: `n-${Date.now()}`,
      text: trimmed,
      timestamp: new Date().toISOString(),
      author: 'User',
    };
    setScenarioNotes(notes => [...notes, entry]);
  };

  const goHome = () => { setScreen('home'); setCategory(null); setDetailId(null); setHistory([]); };
  const goCategory = (cat) => {
    setCategory(cat); setScreen('list'); setDetailId(null);
    setHistory(['home']);
  };
  const openDetail = (id) => {
    setHistory(h => [...h, screen === 'detail' ? `detail:${detailId}` : screen === 'deps' ? `deps:${detailId}` : screen === 'cascade' ? `cascade:${cascadeMode}` : screen]);
    setDetailId(id); setScreen('detail');
  };
  const openDeps = () => {
    setHistory(h => [...h, `detail:${detailId}`]);
    setScreen('deps');
  };
  const openMap = () => {
    setHistory(['home']);
    setScreen('map');
  };
  const openContacts = () => {
    setHistory(['home']);
    setScreen('contacts');
  };
  const openScenario = () => {
    setHistory(['home']);
    setScreen('scenario');
  };
  const openCascade = (mode) => {
    setCascadeMode(mode);
    setHistory(h => [...h, 'scenario']);
    setScreen('cascade');
  };
  const openReport = () => {
    setHistory(h => [...h, 'scenario']);
    setScreen('report');
  };
  const goBack = () => {
    const prev = history[history.length - 1];
    if (!prev) return goHome();
    setHistory(h => h.slice(0, -1));
    if (prev === 'home') return goHome();
    if (prev === 'list') { setScreen('list'); setDetailId(null); return; }
    if (prev === 'map') { setScreen('map'); return; }
    if (prev === 'contacts') { setScreen('contacts'); return; }
    if (prev === 'scenario') { setScreen('scenario'); return; }
    if (prev === 'report') { setScreen('report'); return; }
    if (prev === 'myScenarios') { setScreen('myScenarios'); return; }
    if (prev === 'notes') { setScreen('notes'); return; }
    if (prev === 'admin') { setScreen('admin'); return; }
    if (prev.startsWith('cascade:')) {
      setCascadeMode(prev.split(':')[1]);
      setScreen('cascade');
      return;
    }
    if (prev.startsWith('detail:')) {
      setDetailId(prev.split(':')[1]);
      setScreen('detail');
      return;
    }
    if (prev.startsWith('deps:')) {
      setDetailId(prev.split(':')[1]);
      setScreen('deps');
      return;
    }
  };

  const toggleScenario = () => setScenario(s =>
    s.includes(detailId) ? s.filter(x => x !== detailId) : [...s, detailId]
  );
  const addToScenario = (id) => setScenario(s => s.includes(id) ? s : [...s, id]);
  // Capture a drawn area (from spatial selection) onto the scenario for the
  // report. Appends so multiple shapes can accumulate.
  const addScenarioGeometry = (geom) => {
    if (!geom) return;
    setScenarioGeometry(g => [...g, geom]);
  };
  const removeFromScenario = (id) => {
    setScenario(s => s.filter(x => x !== id));
    setScenarioStates(states => {
      const next = { ...states };
      delete next[id];
      return next;
    });
  };
  const clearScenario = () => {
    setScenario([]);
    setScenarioStates({});
    setScenarioNotes([]);
    setScenarioGeometry([]);
    setScenarioName('Untitled Scenario');
  };
  // What-if state cycler: disrupted -> fixing -> manual -> unable -> disrupted
  const cycleScenarioState = (id) => {
    setScenarioStates(states => {
      const current = states[id] || 'disrupted';
      const idx = STATES.indexOf(current);
      const next = STATES[(idx + 1) % STATES.length];
      return { ...states, [id]: next };
    });
  };
  const setScenarioState = (id, newState) => {
    setScenarioStates(states => ({ ...states, [id]: newState }));
  };
  // Reset all scenario items back to disrupted
  const resetScenarioStates = () => setScenarioStates({});

  // Save / load / delete scenarios
  const saveCurrentScenario = (name, idToOverwrite = null) => {
    const now = new Date().toISOString();
    const trimmed = (name || '').trim() || 'Untitled Scenario';
    setSavedScenarios(prev => {
      if (idToOverwrite) {
        return prev.map(s => s.id === idToOverwrite
          ? { ...s, name: trimmed, updated: now,
              scenario: [...scenario], scenarioStates: { ...scenarioStates },
              notes: [...scenarioNotes] }
          : s);
      }
      const newId = `s-${Date.now()}`;
      return [
        {
          id: newId, name: trimmed, created: now, updated: now,
          scenario: [...scenario], scenarioStates: { ...scenarioStates },
          notes: [...scenarioNotes],
        },
        ...prev,
      ];
    });
    setScenarioName(trimmed);
  };

  const loadScenario = (saved) => {
    setScenario([...saved.scenario]);
    setScenarioStates({ ...saved.scenarioStates });
    setScenarioName(saved.name);
    setScenarioNotes([...(saved.notes || [])]);
    setHistory(['home']);
    setScreen('scenario');
  };

  const deleteScenario = (id) => {
    setSavedScenarios(prev => prev.filter(s => s.id !== id));
  };

  const openMyScenarios = () => {
    setHistory(h => [...h, screen]);
    setScreen('myScenarios');
  };

  const openNotes = () => {
    setHistory(h => [...h, screen]);
    setScreen('notes');
  };

  // -----------------------------------------------------------------------
  // Desktop responsiveness (Session 1.6)
  //
  // The sidebar is a desktop-only persistent navigation. It calls back into
  // DSTApp via sidebarNavigate(screen), which routes to the right top-level
  // screen and resets history (sidebar nav is always a fresh starting point,
  // not a back-stack push). Mobile is unaffected; isDesktop just gates
  // sidebar rendering and the BottomNav hide.
  // -----------------------------------------------------------------------
  const isDesktop = useIsDesktop();

  const sidebarNavigate = (target) => {
    setHistory([]);
    setCategory(null);
    setDetailId(null);
    setScreen(target);
  };

  const activeSidebarKey = screenToSidebarKey(screen);

  // Screen router. The JSX block below is what the app renders for the
  // current `screen` state. On mobile this is the entire visible area; on
  // desktop it sits inside the sidebar+main shell.
  const screenRouter = (
    <>
      {/* Auth gate - show login if no current user */}
      {!currentUser && screen === 'login' && (
        <LoginScreen onLogin={handleLogin}/>
      )}
      {currentUser && screen === 'home' && (
        <Home
          onNavigate={goCategory}
          scenarioCount={scenario.length}
          onOpenScenario={openScenario}
          onOpenMap={openMap}
          onOpenContacts={openContacts}
          onOpenMyScenarios={openMyScenarios}
          savedCount={savedScenarios.length}
          currentUser={currentUser}
          onOpenAdmin={openAdmin}
          onOpenUserMenu={() => setUserMenuOpen(true)}
          onLogout={handleLogout}
        />
      )}
      {currentUser && screen === 'admin' && (
        <AdminPortalScreen
          users={users}
          currentUser={currentUser}
          onInvite={inviteUser}
          onUpdateUser={updateUser}
          onResetCredential={resetUserCredential}
          onBack={goBack}
          onHome={goHome}
          scenarioCount={scenario.length}
          onScenarioTap={openScenario}
        />
      )}
      {screen === 'list' && (
        <CategoryList
          category={category} items={data[category]}
          onOpen={openDetail} onBack={goHome}
          scenarioCount={scenario.length}
          scenario={scenario}
          addToScenario={addToScenario}
          onScenarioTap={openScenario}
          onHome={goHome}
        />
      )}
      {screen === 'detail' && (
        <Detail
          id={detailId} onOpen={openDetail}
          onBack={goBack}
          onOpenDeps={openDeps}
          inScenario={scenario.includes(detailId)}
          toggleScenario={toggleScenario}
          scenarioCount={scenario.length}
          onScenarioTap={openScenario}
          onHome={goHome}
        />
      )}
      {screen === 'deps' && (
        <DependenciesScreen
          id={detailId} onOpen={openDetail}
          onBack={goBack} scenarioCount={scenario.length}
          onScenarioTap={openScenario}
          onHome={goHome}
        />
      )}
      {screen === 'map' && (
        <PortMapScreen
          onBack={goHome} onOpen={openDetail}
          scenarioCount={scenario.length}
          scenario={scenario}
          addToScenario={addToScenario}
          onAddGeometry={addScenarioGeometry}
          onScenarioTap={openScenario}
          onHome={goHome}
        />
      )}
      {screen === 'contacts' && (
        <CriticalContactsScreen
          onBack={goHome} scenarioCount={scenario.length}
          onScenarioTap={openScenario}
          onHome={goHome}
        />
      )}
      {screen === 'scenario' && (
        <ScenarioBuilderScreen
          scenario={scenario}
          scenarioStates={scenarioStates}
          scenarioName={scenarioName}
          scenarioNotes={scenarioNotes}
          onBack={goHome}
          onOpen={openDetail}
          onRemove={removeFromScenario}
          onClear={clearScenario}
          onAddNew={() => goCategory('processes')}
          onHome={goHome}
          onOpenCascade={openCascade}
          onCycleState={cycleScenarioState}
          onSetState={setScenarioState}
          onResetStates={resetScenarioStates}
          onGenerateReport={openReport}
          onSaveScenario={saveCurrentScenario}
          onOpenMyScenarios={openMyScenarios}
          onOpenNotes={openNotes}
          onSetScenarioName={setScenarioName}
          savedScenarios={savedScenarios}
        />
      )}
      {screen === 'myScenarios' && (
        <MyScenariosScreen
          savedScenarios={savedScenarios}
          onLoad={loadScenario}
          onDelete={deleteScenario}
          onBack={goBack}
          onHome={goHome}
          scenarioCount={scenario.length}
          onScenarioTap={openScenario}
        />
      )}
      {screen === 'notes' && (
        <NotesScreen
          scenarioName={scenarioName}
          scenarioNotes={scenarioNotes}
          onAddNote={addScenarioNote}
          onBack={goBack}
          onHome={goHome}
          scenarioCount={scenario.length}
          onScenarioTap={openScenario}
        />
      )}
      {screen === 'cascade' && (
        <CascadeListScreen
          scenario={scenario}
          scenarioStates={scenarioStates}
          mode={cascadeMode}
          onBack={goBack}
          onOpen={openDetail}
          onHome={goHome}
          scenarioCount={scenario.length}
          onScenarioTap={openScenario}
        />
      )}
      {screen === 'report' && (
        <ReportPreviewScreen
          scenario={scenario}
          scenarioStates={scenarioStates}
          scenarioName={scenarioName}
          scenarioNotes={scenarioNotes}
          scenarioGeometry={scenarioGeometry}
          onSetScenarioName={setScenarioName}
          onBack={goBack}
          onHome={goHome}
          scenarioCount={scenario.length}
          onScenarioTap={openScenario}
          onOpen={openDetail}
        />
      )}

      {/* User menu sheet — profile + logout */}
      <Sheet open={userMenuOpen} onClose={() => setUserMenuOpen(false)} title="Account">
        {currentUser && (
          <>
            <div style={{
              padding: '14px', marginBottom: 16,
              background: T.surfaceAlt, border: `1px solid ${T.lightTeal}`,
              display: 'flex', alignItems: 'center', gap: 12,
            }}>
              <div style={{
                width: 44, height: 44, flexShrink: 0,
                background: currentUser.role === 'admin' ? '#7A1F12' : T.darkBlue,
                color: '#fff',
                display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
                fontFamily: '"Zilla Slab", serif', fontSize: 20, fontWeight: 700,
              }}>{(currentUser.name || currentUser.email).charAt(0).toUpperCase()}</div>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{
                  fontFamily: '"Zilla Slab", serif', fontSize: 16, fontWeight: 600,
                  color: T.darkBlue, marginBottom: 2,
                }}>{currentUser.name || currentUser.email}</div>
                <div style={{
                  fontFamily: 'Poppins, sans-serif', fontSize: 11, color: T.ink2,
                  marginBottom: 4, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
                }}>{currentUser.email}</div>
                <span style={{
                  padding: '1px 6px',
                  background: USER_ROLES[currentUser.role]?.soft,
                  color: USER_ROLES[currentUser.role]?.color,
                  fontFamily: 'Poppins, sans-serif', fontSize: 9, fontWeight: 700,
                  letterSpacing: '0.08em', textTransform: 'uppercase',
                }}>{USER_ROLES[currentUser.role]?.label}</span>
              </div>
            </div>

            {currentUser.role === 'admin' && (
              <button onClick={() => { setUserMenuOpen(false); openAdmin(); }} style={{
                width: '100%', padding: '12px', marginBottom: 8,
                background: 'transparent', color: T.darkBlue,
                border: `1.5px solid ${T.darkBlue}`, cursor: 'pointer',
                fontFamily: 'Poppins, sans-serif', fontSize: 11, fontWeight: 700,
                letterSpacing: '0.1em', textTransform: 'uppercase',
                display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: 6,
              }}>
                <UserCog size={14}/> Admin Portal
              </button>
            )}

            <button onClick={handleLogout} style={{
              width: '100%', padding: '12px', marginBottom: 8,
              background: T.critical, color: '#fff', border: 'none', cursor: 'pointer',
              fontFamily: 'Poppins, sans-serif', fontSize: 11, fontWeight: 700,
              letterSpacing: '0.1em', textTransform: 'uppercase',
              display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: 6,
            }}>
              <LogOut size={14}/> Sign Out
            </button>

            <button onClick={() => setUserMenuOpen(false)} style={{
              width: '100%', padding: '12px',
              background: 'transparent', color: T.ink2,
              border: `1px solid ${T.rule}`, cursor: 'pointer',
              fontFamily: 'Poppins, sans-serif', fontSize: 11, fontWeight: 700,
              letterSpacing: '0.1em', textTransform: 'uppercase',
            }}>Close</button>
          </>
        )}
      </Sheet>
    </>
  );

  // Desktop shell: sidebar on the left, screen router on the right. Login
  // screen sits OUTSIDE the desktop shell (sidebar makes no sense before
  // sign-in). Mobile: render screen router directly with no shell.
  if (isDesktop && currentUser) {
    return (
      <div className="dst-app-root dst-desktop" style={{
        height: '100%', overflow: 'hidden',
        background: T.bg, position: 'relative',
        display: 'flex', flexDirection: 'row',
      }}>
        <Sidebar
          currentUser={currentUser}
          activeKey={activeSidebarKey}
          onNavigate={sidebarNavigate}
          onLogout={handleLogout}
        />
        <main style={{
          flex: 1, height: '100%', overflowY: 'auto', overflowX: 'hidden',
          background: T.bg,
          WebkitOverflowScrolling: 'touch', position: 'relative',
        }}>
          {screenRouter}
        </main>
      </div>
    );
  }

  return (
    <div className="dst-app-root" style={{
      height: '100%', overflowY: 'auto', overflowX: 'hidden',
      background: T.bg,
      WebkitOverflowScrolling: 'touch', position: 'relative',
    }}>
      {screenRouter}
    </div>
  );
}

/* ============================================================================
   OUTER — iPhone frame
   ============================================================================ */

export default function App() {
  return (
    <>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Poppins:ital,wght@0,300;0,400;0,500;0,600;0,700;0,800;1,400;1,500&family=Zilla+Slab:ital,wght@0,300;0,400;0,500;0,600;0,700;1,400;1,500;1,600&display=swap');
        * { box-sizing: border-box; }
        button:focus-visible { outline: 2px solid ${T.teal}; outline-offset: 2px; }
        ::-webkit-scrollbar { width: 6px; height: 6px; }
        ::-webkit-scrollbar-thumb { background: ${T.rule}; border-radius: 3px; }
        ::-webkit-scrollbar-track { background: transparent; }

        /* Full-bleed app shell — no iPhone frame in the deployed demo */
        html, body, #root { height: 100%; margin: 0; padding: 0; }
        body { background: ${T.bg}; }

        /* On mobile/narrow screens, constrain the app to a phone-sized column
           for legibility. On desktop (>= 1024px breakpoint), the constraint is
           removed so the sidebar + main-content layout can use the full
           viewport width. */
        .pcca-app-shell {
          width: 100%; height: 100%;
          max-width: 480px; margin: 0 auto;
          background: ${T.bg};
          position: relative;
          box-shadow: 0 0 40px rgba(0,0,0,0.08);
        }
        @media (max-width: 480px) {
          .pcca-app-shell { box-shadow: none; max-width: none; }
        }
        @media (min-width: ${DESKTOP_BREAKPOINT}px) {
          .pcca-app-shell { max-width: none; box-shadow: none; }
          /* Hide the mobile BottomNav on desktop. The Sidebar (rendered by
             DSTApp at the same breakpoint) supersedes its navigation role. */
          .dst-bottom-nav { display: none !important; }
        }

        /* Print-only styles for the Report Preview */
        @media print {
          body { background: #fff !important; margin: 0 !important; }
          html, body, #root {
            height: auto !important;
            overflow: visible !important;
          }
          /* CRITICAL: override the app-shell and DSTApp height constraints so
             content beyond the viewport can flow onto subsequent pages. Without
             these overrides, the printer sees only viewport-height of content
             and stops at one page. */
          .pcca-app-shell {
            max-width: none !important;
            box-shadow: none !important;
            height: auto !important;
            overflow: visible !important;
          }
          .dst-app-root {
            height: auto !important;
            overflow: visible !important;
          }
          .dst-no-print { display: none !important; }
          .dst-report-wrap {
            padding: 0 !important;
            background: #fff !important;
            height: auto !important;
            overflow: visible !important;
          }
          .dst-report {
            box-shadow: none !important;
            padding: 0 !important;
            height: auto !important;
            overflow: visible !important;
          }
          @page { margin: 0.5in; }

          /* Section breaks: avoid splitting within a section, but let pages flow
             naturally. We don't force a page break before every section. */
          .dst-report-section {
            break-inside: avoid-page;
            page-break-inside: avoid;
          }
          .dst-section-subhead {
            break-after: avoid;
            page-break-after: avoid;
          }
          .dst-report-card {
            break-inside: avoid;
            page-break-inside: avoid;
          }
        }
      `}</style>
      <div className="pcca-app-shell">
        <DSTApp />
      </div>
    </>
  );
}
